  ui_story_5029_50290002_45_dialog_content = "嗯……",
  ui_story_5029_50290002_46_dialog_content = "剛才你為了撕下那面牆上的<color=#793f76>懸賞任務委託單</color>，不慎跌倒。",
  ui_story_5029_50290002_47_dialog_content = "委託單？",
