  ui_story_5029_50290002_57_dialog_content = "你一定是被「高額賞金」這幾個字衝昏頭了吧。",
  ui_story_5029_50290002_58_dialog_content = "我非常能理解你當時的心情！",
  ui_story_5029_50290002_59_dialog_content = "一直聽說好泊城治安良好，人民富足，竟然也有這種惡劣的盜竊事件？",
  ui_story_5029_50290002_60_dialog_content = "而且，為什麼這戶人家不去找領主解決問題？",
  ui_story_5029_50290002_61_dialog_content = "可能是領主解決不了這個問題吧......",
  ui_story_5029_50290002_62_dialog_content = "哎呀，有這麼好的機會還等什麼呀？",
  ui_story_5029_50290002_63_dialog_content = "既然我們還有時間，不如就去當一回偵探，順便賺些賞金吧。",
