  ui_story_5029_50290002_69_dialog_content = "囉！",
  ui_story_5029_50290002_70_dialog_content = "啊，懸賞任務單......被搶走了！",
  ui_story_5029_50290002_71_dialog_content = "哈哈，做得不錯嘛，凱羅。",
