  ui_story_5029_50290002_73_option_content = "還以為是強盜來了......",
  ui_story_5029_50290002_74_dialog_content = "PlayerName，你這樣說菲雅要生氣啦！",
  ui_story_5029_50290002_74X1_dialog_content = "看清楚，菲雅怎麼會是強盜呢。",
