  ui_story_5029_50290002_94_dialog_content = "菲雅能讓最兇猛最暴躁的動物變得溫順平靜，還會怕罪犯嗎？",
  ui_story_5029_50290002_95_dialog_content = "菲雅，罪犯和神奇動物還是很不一樣的。",
  ui_story_5029_50290002_96_dialog_content = "連PlayerName都不幫我說話？",
  ui_story_5029_50290002_97_dialog_content = "喔～我知道了，你們幾個是不是都想接這個任務呀？",
  ui_story_5029_50290002_98_dialog_content = "大不了，我們就<color=#793f76>公平競爭</color>呀。",
  ui_story_5029_50290002_99_dialog_content = "誰找到犯人，賞金就歸誰嗎？感覺是個好主意欸！",
  ui_story_5029_50290002_100_dialog_content = "這樣的話，妳們可要做好心理準備。",
  ui_story_5029_50290002_101_dialog_content = "我在白夜城衛隊待了這麼多年，多少還是有點經驗的。",
  ui_story_5029_50290002_102_dialog_content = "大家......那我......？",
  ui_story_5029_50290002_103_dialog_content = "抱歉，讓各位久等了。",
  ui_story_5029_50290002_104_dialog_content = "我是懸賞任務上提到的聯絡人，贊恩。",
  ui_story_5029_50290002_105_dialog_content = "如果四位決定接下任務的話，就請隨我來吧。",
  ui_story_5029_50290003_1_dialog_content = "PlayerName。",
  ui_story_5029_50290003_2_dialog_content = "……",
  ui_story_5029_50290003_3_dialog_content = "PlayerName，你不要嚇我啊。",
  ui_story_5029_50290003_4_dialog_content = "我們經歷過那麼多危機和災難，你都挺過來了。",
  ui_story_5029_50290003_5_dialog_content = "不會因為摔了一跤就變傻了吧？",
  ui_story_5029_50290003_6_dialog_content = "啊！對了，我記得巨像裡有維生裝置......",
  ui_story_5029_50290003_7_dialog_content = "PlayerName，你等著，我背你過去。",
  ui_story_5029_50290003_8_dialog_content = "你一定會沒事的！",
  ui_story_5029_50290003_9_dialog_content = "我……",
  ui_story_5029_50290003_10_dialog_content = "謝天謝地，你終於醒了！",
  ui_story_5029_50290003_11_option_content = "我好害怕",
  ui_story_5029_50290003_12_dialog_content = "沒事的，PlayerName，我一直在這裡陪著你呀。",
  ui_story_5029_50290003_13_dialog_content = "這座城市很安全的，剛才你摔倒只是個意外。",
  ui_story_5029_50290003_14_dialog_content = "別怕，萬一有什麼事情，也有我保護你。",
  ui_story_5029_50290003_15_dialog_content = "啊，我在說什麼？",
  ui_story_5029_50290003_16_option_content = "還好有妳在我身邊",
  ui_story_5029_50290003_17_dialog_content = "欸？",
  ui_story_5029_50290003_18_dialog_content = "幹嘛忽然說這個啊。",
  ui_story_5029_50290003_19_dialog_content = "讓人怪難為情的。",
  ui_story_5029_50290003_20_dialog_content = "欸，我我我......",
  ui_story_5029_50290003_21_option_content = "我沒事的",
  ui_story_5029_50290003_22_dialog_content = "真的嗎？",
  ui_story_5029_50290003_23_dialog_content = "會覺得頭疼嗎？或者身體有沒有什麼地方不舒服？",
  ui_story_5029_50290003_24_dialog_content = "都沒有，我覺得自己挺好的。只是......",
  ui_story_5029_50290003_25_option_content = "我不用妳擔心",
  ui_story_5029_50290003_26_dialog_content = "妳……",
  ui_story_5029_50290003_27_dialog_content = "不過是摔了一跤，性格怎麼變得這麼惡劣？",
  ui_story_5029_50290003_28_dialog_content = "難道要再摔一跤，原來的PlayerName才能變回來？",
  ui_story_5029_50290003_29_dialog_content = "啊，薇絲？！妳要幹什麼！",
  ui_story_5029_50290003_30_dialog_content = "妳聽我解釋......",
  ui_story_5029_50290003_31_dialog_content = "我好像做了一個夢。",
  ui_story_5029_50290003_32_dialog_content = "如果我剛才說了什麼奇怪的夢話，請妳千萬不要介意啊......",
  ui_story_5029_50290003_33_dialog_content = "好啦好啦，你沒事比什麼都重要。",
  ui_story_5029_50290003_34_dialog_content = "地上太涼，別一直躺著了。",
  ui_story_5029_50290003_35_dialog_content = "我扶你起來，小心喔。",
  ui_story_5029_50290003_36_dialog_content = "謝謝……",
  ui_story_5029_50290003_37_dialog_content = "薇絲，妳怎麼在這裡？不是說要去美術館提高審美嗎？",
  ui_story_5029_50290003_38_dialog_content = "嘿嘿，路上遇到一點狀況。",
  ui_story_5029_50290003_39_dialog_content = "嗯？PlayerName也在......？",
  ui_story_5029_50290003_40_dialog_content = "你看起來臉色很差，發生什麼事了嗎？",
  ui_story_5029_50290003_41_option_content = "不是什麼大事",
  ui_story_5029_50290003_42_dialog_content = "看到卡蓮也在，我就更安心了。",
  ui_story_5029_50290003_43_dialog_content = "放心，好泊城還是很安全的。",
  ui_story_5029_50290003_44_option_content = "都怪這破地方",
  ui_story_5029_50290003_45_dialog_content = "好泊城的路是怎麼修的，害得我剛剛摔倒了。",
  ui_story_5029_50290003_45X1_dialog_content = "這裡道路平整，你確定是因為道路的關係？",
  ui_story_5029_50290003_45X2_dialog_content = "（卡蓮是生氣了嗎？啊，差點忘了這裡是白夜城的領土......快換個話題。）",
  ui_story_5029_50290003_46_dialog_content = "我忽然想起來......剛才我好像做了個夢。",
  ui_story_5029_50290003_47_dialog_content = "不過，我好像不記得自己在這裡做什麼了......",
  ui_story_5029_50290003_48_dialog_content = "欸，你忘了嗎？",
  ui_story_5029_50290003_49_dialog_content = "剛才你看到牆上貼著一張<color=#793f76>懸賞任務委託單</color>，說什麼要賺回路費......",
  ui_story_5029_50290003_50_dialog_content = "結果撕委託單的時候，腳下沒踩穩，就摔到了。",
  ui_story_5029_50290003_51_dialog_content = "委託單？",
  ui_story_5029_50290003_52_dialog_content = "嗯，就是PlayerName手裡攥著的那張。",
  ui_story_5029_50290003_53_dialog_content = "我手裡......還真的有一張紙？！",
  ui_story_5029_50290003_54_dialog_content = "家中珍寶失竊，願出高額賞金聘請偵探。",
  ui_story_5029_50290003_55_dialog_content = "有意者請撕下此單，聯絡人自會出現。",
  ui_story_5029_50290003_56_dialog_content = "......這，這真的是我自己撕下來的嗎？怎麼一點印象都沒有。",
  ui_story_5029_50290003_57_dialog_content = "我路過這裡的時候，看見你興高采烈的。",
  ui_story_5029_50290003_58_dialog_content = "還拉著我談論了半天「高額賞金」到底有多少呢。",
  ui_story_5029_50290003_59_dialog_content = "我只是看過一些不入流的偵探小說而已，根本沒有當過偵探啊。",
  ui_story_5029_50290003_60_dialog_content = "反正我們還有時間，可以體驗當一次偵探，順便賺些賞金嘛。",
  ui_story_5029_50290003_61_dialog_content = "一直聽說好泊城治安良好，人民富足，竟然也有這種惡劣的盜竊事件？",
  ui_story_5029_50290003_62_dialog_content = "而且，為什麼這戶人家不去找領主解決問題？",
  ui_story_5029_50290003_63_dialog_content = "可能是領主解決不了這個問題吧......",
  ui_story_5029_50290003_64_dialog_content = "既然這件事發生在白夜城的屬地之上，我便不能置之不理。",
  ui_story_5029_50290003_65_dialog_content = "我想以白夜城衛隊的名義，用白夜城的律法去懲罰罪犯。",
  ui_story_5029_50290003_66_dialog_content = "那樣的話......是不是就賺不到賞金了？",
  ui_story_5029_50290003_67_dialog_content = "……",
  ui_story_5029_50290003_68_dialog_content = "凱羅，Plan C，立刻行動！",
  ui_story_5029_50290003_69_dialog_content = "囉！",
  ui_story_5029_50290003_70_dialog_content = "啊，懸賞任務單......被搶走了！",
  ui_story_5029_50290003_71_dialog_content = "哈哈，做得不錯嘛，凱羅。",
  ui_story_5029_50290003_72_dialog_content = "菲雅？！這次又是從哪裡忽然冒出來的？",
  ui_story_5029_50290003_73_option_content = "還以為是強盜來了......",
  ui_story_5029_50290003_74_dialog_content = "PlayerName，你這樣說菲雅要生氣啦！",
  ui_story_5029_50290003_74X1_dialog_content = "看清楚，菲雅怎麼會是強盜呢。",
  ui_story_5029_50290003_75_dialog_content = "我只是好奇，我的神奇動物PlayerName在看什麼東西嘛。",
  ui_story_5029_50290003_76_option_content = "不愧是神奇動物專家......",
  ui_story_5029_50290003_77_dialog_content = "把自己的氣息隱藏得很好啊。",
  ui_story_5029_50290003_78_dialog_content = "嘿嘿，那當然啦。",
  ui_story_5029_50290003_79_dialog_content = "不然我當初怎麼會抓到你這隻神奇動物呢～",
  ui_story_5029_50290003_80_dialog_content = "好啦，讓我瞧瞧你剛才在看什麼東西。",
  ui_story_5029_50290003_81_dialog_content = "好好好，下次別這麼嚇人就行。",
  ui_story_5029_50290003_82_dialog_content = "哇，是懸賞任務欸！",
  ui_story_5029_50290003_83_dialog_content = "凱羅，我們真是太走運了，接下來的旅費有著落了！",
  ui_story_5029_50290003_84_dialog_content = "囉囉囉！",
  ui_story_5029_50290003_85_dialog_content = "臭師父，壞師父，派我來這麼遠的地方，結果只給了一點點旅費。",
  ui_story_5029_50290003_86_dialog_content = "根本不夠我買好吃的、玩好玩的嘛。哼，要讓師父看看......",
  ui_story_5029_50290003_87_dialog_content = "菲雅不僅能完成師父給的任務，還能順便賺大錢呢。",
  ui_story_5029_50290003_88_dialog_content = "囉囉囉！",
  ui_story_5029_50290003_89_dialog_content = "菲雅，妳該不會也想接下這個任務吧？",
  ui_story_5029_50290003_90_dialog_content = "妳看清楚，這可不是扮家家酒。",
  ui_story_5029_50290003_91_dialog_content = "接下任務，就意味著要和貨真價實的罪犯打交道。",
  ui_story_5029_50290003_92_dialog_content = "我、我……",
  ui_story_5029_50290003_93_dialog_content = "哼，妳們不要太小瞧我喔。",
  ui_story_5029_50290003_94_dialog_content = "菲雅能讓最兇猛最暴躁的動物變得溫順平靜，還會怕罪犯嗎？",
  ui_story_5029_50290003_95_dialog_content = "菲雅，罪犯和神奇動物還是很不一樣的。",
  ui_story_5029_50290003_96_dialog_content = "連PlayerName都不幫我說話？",
  ui_story_5029_50290003_97_dialog_content = "喔～我知道了，你們幾個是不是都想接這個任務呀？",
  ui_story_5029_50290003_98_dialog_content = "大不了，我們就<color=#793f76>公平競爭</color>呀。",
  ui_story_5029_50290003_99_dialog_content = "誰找到犯人，賞金就歸誰嗎？感覺是個好主意欸！",
  ui_story_5029_50290003_100_dialog_content = "這樣的話，妳們可要做好心理準備。",
  ui_story_5029_50290003_101_dialog_content = "我在白夜城衛隊待了這麼多年，多少還是有點經驗的。",
  ui_story_5029_50290003_102_dialog_content = "大家......那我......？",
  ui_story_5029_50290003_103_dialog_content = "抱歉，讓各位久等了。",
  ui_story_5029_50290003_104_dialog_content = "我是懸賞任務上提到的聯絡人，贊恩。",
  ui_story_5029_50290003_105_dialog_content = "如果四位決定接下任務的話，就請隨我來吧。",
  ui_story_5029_50290004_1_dialog_content = "PlayerName！",
  ui_story_5029_50290004_2_dialog_content = "……",
  ui_story_5029_50290004_3_dialog_content = "呃，PlayerName摔倒在地上不會說話了？",
  ui_story_5029_50290004_4_dialog_content = "凱羅，我們該怎麼辦？",
  ui_story_5029_50290004_5_dialog_content = "囉囉！",
  ui_story_5029_50290004_6_dialog_content = "對啊，我可是神奇動物專家。",
  ui_story_5029_50290004_7_dialog_content = "愈是這種時候，就愈應該保持專家的風範！",
  ui_story_5029_50290004_8_dialog_content = "我記得師父給我的本子上有記載喚醒陸生神奇動物的藥方。",
  ui_story_5029_50290004_8X1_dialog_content = "對空裔應該也能用吧？",
  ui_story_5029_50290004_9_dialog_content = "啊，找到了！需要的是......凱羅的人工呼吸？",
  ui_story_5029_50290004_10_dialog_content = "囉？",
  ui_story_5029_50290004_11_dialog_content = "咳咳……",
  ui_story_5029_50290004_12_dialog_content = "天哪，你終於醒了？！",
  ui_story_5029_50290004_13_option_content = "多虧有妳，菲雅",
  ui_story_5029_50290004_14_dialog_content = "哼，不用客氣～",
  ui_story_5029_50290004_15_dialog_content = "你可是我好不容易抓到的神奇動物，照顧好你也是我的職責嘛。",
  ui_story_5029_50290004_16_dialog_content = "啊，對了，凱羅也有幫忙喔！",
  ui_story_5029_50290004_17_dialog_content = "囉～",
  ui_story_5029_50290004_18_option_content = "我覺得好多了",
  ui_story_5029_50290004_19_dialog_content = "那是當然。",
  ui_story_5029_50290004_20_dialog_content = "有我和凱羅在，你不會出什麼大問題的！",
  ui_story_5029_50290004_21_dialog_content = "囉！",
  ui_story_5029_50290004_22_option_content = "妳想害死我嗎",
  ui_story_5029_50290004_23_dialog_content = "PlayerName，你......",
  ui_story_5029_50290004_24_dialog_content = "我和凱羅明明是好心想要把你救過來，你有沒有搞清楚哇？",
  ui_story_5029_50290004_25_dialog_content = "哼，看來空裔也沒有那麼大的收養價值，還不如養一隻暗鬼呢。",
  ui_story_5029_50290004_26_dialog_content = "囉！",
  ui_story_5029_50290004_27_option_content = "凱羅不要過來！",
  ui_story_5029_50290004_28_dialog_content = "不要就不要囉，幹嘛這麼大聲嘛。",
  ui_story_5029_50290004_29_dialog_content = "不過看你這麼精神，確實輪不到凱羅出場了。",
  ui_story_5029_50290004_30_dialog_content = "囉囉囉～",
  ui_story_5029_50290004_31_dialog_content = "剛才......那些都是夢嗎？",
  ui_story_5029_50290004_32_dialog_content = "從你摔倒到現在，這麼短的時間裡你都能做夢嗎？",
  ui_story_5029_50290004_33_dialog_content = "空裔有愛做白日夢的特點？嗯......這一點很重要，要好好記錄下來。",
  ui_story_5029_50290004_34_dialog_content = "喂，這個就不用記了吧......",
  ui_story_5029_50290004_35_dialog_content = "欸，PlayerName？",
  ui_story_5029_50290004_36_dialog_content = "你躺在地上幹什麼，小心著涼拉肚子！",
  ui_story_5029_50290004_37_dialog_content = "來，我拉你起來。",
  ui_story_5029_50290004_38_option_content = "多，多謝！",
  ui_story_5029_50290004_39_dialog_content = "不就是拉你一把嗎，不用客氣喔。",
  ui_story_5029_50290004_40_option_content = "我自己來就好",
  ui_story_5029_50290004_41_dialog_content = "嗯……好吧。",
  ui_story_5029_50290004_41X1_dialog_content = "嗚啊......！好像抽筋了......",
  ui_story_5029_50290004_42_dialog_content = "所以說就不要逞強啦......",
  ui_story_5029_50290004_43_dialog_content = "「空裔見到女生會緊張......」",
  ui_story_5029_50290004_44_dialog_content = "欸？菲雅在記錄PlayerName的行為習慣嗎？",
  ui_story_5029_50290004_45_dialog_content = "嗯！摸清神奇動物的生活習慣和表達方式，才能更好地與牠們溝通。",
  ui_story_5029_50290004_46_dialog_content = "但我真的沒有緊張啊！",
  ui_story_5029_50290004_47_dialog_content = "是嗎？話說......你手裡死死攥住的是什麼東西？",
  ui_story_5029_50290004_48_dialog_content = "嗯？妳不說我都沒注意自己手裡有一張紙......這是什麼？",
  ui_story_5029_50290004_49_dialog_content = "哈！PlayerName剛剛想從牆上撕下這張紙。",
  ui_story_5029_50290004_49X1_dialog_content = "用力過猛所以才摔倒的。",
  ui_story_5029_50290004_50_dialog_content = "到底是什麼對空裔有這麼大吸引力？",
  ui_story_5029_50290004_51_dialog_content = "快讓我瞧瞧那張紙！",
  ui_story_5029_50290004_52_dialog_content = "小心一點啊，紙會被撕壞的......",
  ui_story_5029_50290004_53_dialog_content = "<color=#828282>呼——</color>",
  ui_story_5029_50290004_54_dialog_content = "啊啊啊......那張紙被風吹跑了。",
  ui_story_5029_50290004_55_dialog_content = "凱羅，Plan A，立刻行動！",
  ui_story_5029_50290004_56_dialog_content = "囉！",
  ui_story_5029_50290004_57_dialog_content = "等一下，看起來不用凱羅行動了喔。已經有人幫我們撿起來了。",
  ui_story_5029_50290004_58_dialog_content = "是你們幾個？",
  ui_story_5029_50290004_59_dialog_content = "我剛才撿到了一張紙，是你們丟的？",
  ui_story_5029_50290004_60_dialog_content = "是的！那張紙上面有PlayerName的祕密！",
  ui_story_5029_50290004_61_dialog_content = "卡蓮，那張紙......",
  ui_story_5029_50290004_62_option_content = "謝謝妳幫我撿起來",
  ui_story_5029_50290004_63_dialog_content = "不必客氣。",
  ui_story_5029_50290004_64_dialog_content = "雖然，我也不知道上面的內容。",
  ui_story_5029_50290004_65_option_content = "快給我！",
  ui_story_5029_50290004_65X1_dialog_content = "你已經加入紅油扳手了嗎？",
  ui_story_5029_50290004_65X2_dialog_content = "為何說話方式和他們如出一轍，沒有教養......",
  ui_story_5029_50290004_66_dialog_content = "因，因為我不知道那上面的內容......",
  ui_story_5029_50290004_67_dialog_content = "說不定又是什麼空穴來風的誹謗。",
  ui_story_5029_50290004_68_dialog_content = "給，你自己看看就知道了。",
  ui_story_5029_50290004_69_dialog_content = "家中珍寶失竊，願出高額賞金聘請偵探。",
  ui_story_5029_50290004_70_dialog_content = "有意者請撕下此單，聯絡人自會出現。",
  ui_story_5029_50290004_71_dialog_content = "哇，是<color=#793f76>懸賞任務</color>欸！",
  ui_story_5029_50290004_72_dialog_content = "一直聽說好泊城治安良好，人民富足，竟然也有這種惡劣的盜竊事件？",
  ui_story_5029_50290004_73_dialog_content = "......這，這真的是我自己撕下來的嗎？怎麼一點印象都沒有。",
  ui_story_5029_50290004_74_dialog_content = "PlayerName，我非常能理解。",
  ui_story_5029_50290004_74X1_dialog_content = "你一定是被「高額賞金」這幾個字衝昏了頭！",
  ui_story_5029_50290004_75_dialog_content = "可我只是看過一些不入流的偵探小說而已，根本沒有當過偵探啊。",
  ui_story_5029_50290004_76_dialog_content = "真不知道當時我是怎麼想的。",
  ui_story_5029_50290004_77_dialog_content = "PlayerName，你該不會是害怕了吧？",
  ui_story_5029_50290004_78_dialog_content = "那這件事就交給菲雅好了！我和凱羅正愁沒錢花呢。",
  ui_story_5029_50290004_79_dialog_content = "囉囉囉！",
  ui_story_5029_50290004_80_dialog_content = "妳的師父沒給妳旅費嗎？",
  ui_story_5029_50290004_81_dialog_content = "臭師父，壞師父，派我來這麼遠的地方，結果只給了一點點旅費。",
  ui_story_5029_50290004_82_dialog_content = "根本不夠我買好吃的、玩好玩的嘛。哼，要讓師父看看......",
  ui_story_5029_50290004_83_dialog_content = "菲雅不僅能完成師父給的任務，還能順便賺大錢呢。",
  ui_story_5029_50290004_84_dialog_content = "奇怪……",
  ui_story_5029_50290004_85_dialog_content = "為什麼這戶人家不去找領主解決問題？",
  ui_story_5029_50290004_86_dialog_content = "可能是領主解決不了這個問題吧......",
  ui_story_5029_50290004_87_dialog_content = "哈哈，那我可要讓這裡的領主看看菲雅有多厲害了！",
  ui_story_5029_50290004_88_dialog_content = "妳想清楚，這可不是扮家家酒。",
  ui_story_5029_50290004_89_dialog_content = "接下任務，就意味著要和貨真價實的罪犯打交道。",
  ui_story_5029_50290004_90_dialog_content = "我、我……",
  ui_story_5029_50290004_91_dialog_content = "哼，妳們不要太小瞧我喔。",
  ui_story_5029_50290004_92_dialog_content = "菲雅能讓最兇猛最暴躁的動物變得溫順平靜，還會怕罪犯嗎？",
  ui_story_5029_50290004_93_dialog_content = "菲雅，罪犯和神奇動物還是很不一樣的。",
  ui_story_5029_50290004_94_dialog_content = "連PlayerName都不幫我說話？",
  ui_story_5029_50290004_95_dialog_content = "無論如何，這件事發生在白夜城的屬地之上，我不能置之不理。",
  ui_story_5029_50290004_96_dialog_content = "我想以白夜城衛隊的名義，用白夜城的律法去懲罰罪犯。",
  ui_story_5029_50290004_97_dialog_content = "那樣的話......是不是就賺不到賞金了？",
  ui_story_5029_50290004_98_dialog_content = "喔～我知道了，你們一個個的不讓菲雅管這件事......",
  ui_story_5029_50290004_99_dialog_content = "其實是因為你們都想自己接下這個任務吧？",
  ui_story_5029_50290004_100_dialog_content = "大不了，我們就<color=#793f76>公平競爭</color>呀。",
  ui_story_5029_50290004_101_dialog_content = "誰找到犯人，賞金就歸誰嗎？感覺是個好主意欸！",
  ui_story_5029_50290004_102_dialog_content = "這樣的話，妳們可要做好心理準備。",
  ui_story_5029_50290004_103_dialog_content = "我在白夜城衛隊待了這麼多年，多少還是有點經驗的。",
  ui_story_5029_50290004_104_dialog_content = "大家......那我......？",
  ui_story_5029_50290004_105_dialog_content = "抱歉，讓各位久等了。",
  ui_story_5029_50290004_106_dialog_content = "我是懸賞任務上提到的聯絡人，贊恩。",
  ui_story_5029_50290004_107_dialog_content = "如果四位決定接下任務的話，就請隨我來吧。",
  ui_story_5029_50290005_1_dialog_content = "等等，這裡不就是......",
  ui_story_5029_50290005_2_dialog_content = "我沒看錯吧？",
  ui_story_5029_50290005_3_dialog_content = "這麼說，發布任務的人是<color=#793f76>他</color>？",
  ui_story_5029_50290005_4_dialog_content = "你們在說什麼謎語啊，可以說點通用語嗎？",
  ui_story_5029_50290005_5_dialog_content = "各位不必在門口停留，請進吧。",
  ui_story_5029_50290005_6_dialog_content = "家主已經在屋內等候各位偵探大人了。",
  ui_story_5029_50290005_7_dialog_content = "「偵探大人」，聽見了嗎？那個大叔喊我們偵探大人欸！",
  ui_story_5029_50290005_8_dialog_content = "噓，偵探大人這種時候應該保持低調。",
  ui_story_5029_50290005_9_dialog_content = "略略略，PlayerName愈來愈像臭師父了。",
  ui_story_5029_50290005_10_dialog_content = "歡迎各位偵探......",
  ui_story_5029_50290005_11_dialog_content = "<color=#793f76>艾維斯</color>大人，我們又見面了。",
  ui_story_5029_50290005_12_dialog_content = "卡蓮大人？！",
  ui_story_5029_50290005_13_dialog_content = "沒想到......您，還有這幾位朋友怎麼都來了？",
  ui_story_5029_50290005_14_dialog_content = "贊恩，這是怎麼回事？我明明讓你找偵探。",
  ui_story_5029_50290005_15_dialog_content = "這……",
  ui_story_5029_50290005_16_dialog_content = "我們就是看到了你發布的懸賞任務，才過來應聘的。",
  ui_story_5029_50290005_17_dialog_content = "各位本就是好泊城的客人，哪有讓客人為我工作的道理？",
  ui_story_5029_50290005_18_dialog_content = "客人不可以接懸賞任務嗎？",
  ui_story_5029_50290005_19_dialog_content = "嘿嘿嘿，好像只有我不是你招待的客人呢。",
  ui_story_5029_50290005_20_dialog_content = "那這個任務交給菲雅一個人就好啦！",
  ui_story_5029_50290005_21_dialog_content = "抱歉......我不是這個意思。",
  ui_story_5029_50290005_22_dialog_content = "只要來到好泊城，便都是我們的客人。",
  ui_story_5029_50290005_23_dialog_content = "我只是擔心，各位不想在好泊城內多遊覽觀光一下嗎？",
  ui_story_5029_50290005_24_dialog_content = "解決任務的過程，也算是一種別樣的體驗。",
  ui_story_5029_50290005_25_dialog_content = "比單純的觀光更能深入地瞭解這座城市呢。",
  ui_story_5029_50290005_26_dialog_content = "哈哈哈，早就覺得各位身手敏捷，氣度非凡......",
  ui_story_5029_50290005_27_dialog_content = "有大家的幫助，我這件遺失的寶物應該也能被順利尋回吧。",
  ui_story_5029_50290005_28_dialog_content = "好了好了，快說說看你究竟丟了什麼好東西？",
  ui_story_5029_50290005_29_dialog_content = "我丟的，是一個<color=#793f76>銀質盒子</color>。",
  ui_story_5029_50290005_30_dialog_content = "那個盒子是白夜城最著名的藝術家李奧納多親自設計、打磨的藝術珍品。",
  ui_story_5029_50290005_31_dialog_content = "李奧納多......好像在......在哪裡聽過？",
  ui_story_5029_50290005_32_dialog_content = "李奧納多在白夜城的藝術史上出現過很多次，是一位非常有才華的藝術家。",
  ui_story_5029_50290005_33_dialog_content = "他留下的作品，現在都還受到收藏家們的追捧。",
  ui_story_5029_50290005_34_dialog_content = "沒想到，你竟然有一個。",
  ui_story_5029_50290005_35_dialog_content = "不愧是卡蓮殿下，我應該早點和您切磋一下。",
  ui_story_5029_50290005_36_dialog_content = "可惜這個盒子已經......",
  ui_story_5029_50290005_37_dialog_content = "別說那些亂七八糟的東西了，這個盒子究竟長什麼樣子嘛？",
  ui_story_5029_50290005_38_dialog_content = "對，我們需要更精確的描述，比如它的質量、大小。",
  ui_story_5029_50290005_39_dialog_content = "當然，如果有示意圖就更好了。",
  ui_story_5029_50290005_40_dialog_content = "大家請看。",
  ui_story_5029_50290005_41_dialog_content = "這是我匆匆繪製的示意圖，希望能夠派上用場。",
  ui_story_5029_50290005_42_dialog_content = "這畫得也太好了，很像工程製圖，又兼具藝術的美感。",
  ui_story_5029_50290005_43_dialog_content = "艾斯特拉大陸上是不是只有我不會畫畫......",
  ui_story_5029_50290005_44_dialog_content = "凱羅，來看清楚，我們找到這個東西就有飯吃啦。",
  ui_story_5029_50290005_45_dialog_content = "囉！",
  ui_story_5029_50290005_46_dialog_content = "這個銀盒平時都放在哪裡？又是什麼時候發現丟失的呢？",
  ui_story_5029_50290005_47_dialog_content = "銀盒一直被我放在書房的<color=#793f76>矮櫃</color>裡。",
  ui_story_5029_50290005_48_dialog_content = "昨天午飯前，我還拿出來看了一眼，但是晚飯後我就發現它不見了。",
  ui_story_5029_50290005_49_dialog_content = "也就是說，盒子是在<color=#793f76>昨天中午到傍晚</color>的這段時間裡丟失的。",
  ui_story_5029_50290005_50_dialog_content = "這段時間裡，都有哪些人進出過這棟房子？",
  ui_story_5029_50290005_51_dialog_content = "只有三個人。",
  ui_story_5029_50290005_52_dialog_content = "第一個，是中午來打掃衛生的<color=#793f76>女僕</color>。",
  ui_story_5029_50290005_53_dialog_content = "第二個，是下午來好泊城拜訪的<color=#793f76>白夜城公爵</color>。",
  ui_story_5029_50290005_54_dialog_content = "第三個，是傍晚來洽談投資項目的<color=#793f76>商人</color>。",
  ui_story_5029_50290005_55_dialog_content = "只有三個人......可以肯定嗎？",
  ui_story_5029_50290005_56_dialog_content = "這一點我可以肯定。",
  ui_story_5029_50290005_56X1_dialog_content = "從中午到傍晚時分，我一直守在門口，確實只有這三個人進出。",
  ui_story_5029_50290005_57_dialog_content = "昨日領主事務繁忙，所以幾位客人都在屋內獨自等待過一段時間。",
  ui_story_5029_50290005_58_dialog_content = "嗯，而且接待完最後一位客人後，我就鎖上門去吃晚飯了。",
  ui_story_5029_50290005_59_dialog_content = "你再回來時，有沒有發現門鎖被人破壞的痕跡？",
  ui_story_5029_50290005_60_dialog_content = "沒有。而且所有的窗戶也都是<color=#793f76>從內部鎖好</color>的。",
  ui_story_5029_50290005_61_dialog_content = "所以，我才會懷疑是曾經出入過這棟房子的三個人。",
  ui_story_5029_50290005_62_dialog_content = "只有三個嫌疑人？那想要解決這個案子豈不是很簡單？",
  ui_story_5029_50290005_63_dialog_content = "直接把那三個人抓過來問問不就行了。",
  ui_story_5029_50290005_64_dialog_content = "我猜，這個案子恐怕有什麼不能那麼做的理由。",
  ui_story_5029_50290005_65_dialog_content = "咳咳......又被卡蓮大人說中了。",
  ui_story_5029_50290005_66_dialog_content = "幾個人之中既有尊貴的白夜城貴族，又有影鎮商會推薦的女僕。",
  ui_story_5029_50290005_67_dialog_content = "還有一位是有意來投資的商人......我不想傷了大家的和氣。",
  ui_story_5029_50290005_68_dialog_content = "另外，大家都知道，這幾天城裡正在舉辦慶典。",
  ui_story_5029_50290005_69_dialog_content = "作為領主，我不想因為自己家裡的事，破壞了大家的好心情。",
  ui_story_5029_50290005_70_dialog_content = "所以這件事在告訴大家之前，除了贊恩，並沒有其他人知道。",
  ui_story_5029_50290005_71_dialog_content = "也就是說，你希望我們可以<color=#793f76>祕密地調查</color>？",
  ui_story_5029_50290005_72_dialog_content = "祕密調查......難度一下子就高了許多。",
  ui_story_5029_50290005_73_dialog_content = "我也知道有些勉強，所以大家<color=#793f76>只要幫我找回銀盒即可</color>。",
  ui_story_5029_50290005_74_dialog_content = "如果犯人真的是三人中的某一個......",
  ui_story_5029_50290005_75_dialog_content = "我會想辦法讓他們主動離開。",
  ui_story_5029_50290006_1_dialog_content = "領主去處理慶典相關的事情了。",
  ui_story_5029_50290006_2_dialog_content = "接下來，各位偵探大人可以在這棟房子裡自由調查。",
  ui_story_5029_50290006_3_dialog_content = "有什麼問題可以隨時來問我，我就在大廳待命。",
  ui_story_5029_50290006_4_dialog_content = "如果您有什麼問題想問領主，我也可以代為轉達。",
  ui_story_5029_50290006_5_option_content = "找贊恩",
  ui_story_5029_50290006_6_dialog_content = "您有什麼問題嗎？",
  ui_story_5029_50290006_7_option_content = "房子的用途",
  ui_story_5029_50290006_8_dialog_content = "這棟房子是領主的<color=#793f76>書樓</color>，也是領主平時辦公的地方。",
  ui_story_5029_50290006_9_dialog_content = "領主大部分時間都會獨自待在這棟房子裡。",
  ui_story_5029_50290006_10_dialog_content = "偶爾也會在這裡會見一些親密的朋友。",
  ui_story_5029_50290006_11_dialog_content = "鑰匙也由領主自己親自保管。",
  ui_story_5029_50290006_12_dialog_content = "您還有什麼問題嗎？",
  ui_story_5029_50290006_13_option_content = "房子的布局",
  ui_story_5029_50290006_14_dialog_content = "房子一共有兩層。",
  ui_story_5029_50290006_15_dialog_content = "一樓是大廳，還有一個小型咖啡廳。",
  ui_story_5029_50290006_16_dialog_content = "二樓是領主的書房。",
  ui_story_5029_50290006_17_dialog_content = "您還有什麼問題嗎？",
  ui_story_5029_50290006_18_option_content = "你是誰",
  ui_story_5029_50290006_19_dialog_content = "我是贊恩，是領主的貼身護衛。",
  ui_story_5029_50290006_20_dialog_content = "以前我只是普通的碼頭搬運工人。",
  ui_story_5029_50290006_21_dialog_content = "多虧領主重用，我才能有今天。",
  ui_story_5029_50290006_22_dialog_content = "您還有什麼問題嗎？",
  ui_story_5029_50290006_23_option_content = "沒有問題",
  ui_story_5029_50290006_24_dialog_content = "沒關係，如果您有問題可以隨時來問我。",
  ui_story_5029_50290006_25_dialog_content = "好的，多謝。",
  ui_story_5029_50290006_26_option_content = "隨便逛逛",
  ui_story_5029_50290006_27_dialog_content = "大家都開始搜查了嗎？",
  ui_story_5029_50290006_28_dialog_content = "哼。",
  ui_story_5029_50290006_29_dialog_content = "……",
  ui_story_5029_50290006_30_dialog_content = "……",
  ui_story_5029_50290006_31_dialog_content = "（氣氛好像有點尷尬......）",
  ui_story_5029_50290006_32_dialog_content = "（三個人還真的競爭起來了嗎？）",
  ui_story_5029_50290006_33_dialog_content = "（不會吧......我也要和她們競爭嗎？）",
  ui_story_5029_50290006_34_dialog_content = "我該怎麼辦......",
  ui_story_5029_50290006_35_option_content = "找卡蓮",
  ui_story_5029_50290006_36_dialog_content = "卡蓮……",
  ui_story_5029_50290006_37_dialog_content = "什麼事？",
  ui_story_5029_50290006_38_option_content = "我和妳一起吧",
  ui_story_5029_50290006_39_dialog_content = "想和我一起嗎......好。",
  ui_story_5029_50290006_40_dialog_content = "不過我要考考你。",
  ui_story_5029_50290006_41_option_content = "加油！",
  ui_story_5029_50290006_42_dialog_content = "謝謝。",
  ui_story_5029_50290006_43_dialog_content = "我不會讓白夜城衛隊蒙羞的。",
  ui_story_5029_50290006_44_dialog_content = "（欸，就這麼走了嗎？）",
  ui_story_5029_50290006_45_dialog_content = "（我是不是說錯話了......）",
  ui_story_5029_50290006_46_option_content = "啊，沒事",
  ui_story_5029_50290006_47_dialog_content = "那我繼續搜查了。",
  ui_story_5029_50290006_48_dialog_content = "（卡蓮的眼神是怎麼回事......差點以為要被她的眼神凍僵了。）",
  ui_story_5029_50290006_49_dialog_content = "（我還是繼續忙我的吧。）",
  ui_story_5029_50290006_50_dialog_content = "（要去哪裡看看呢？）",
  ui_story_5029_50290006_51_option_content = "找薇絲",
  ui_story_5029_50290006_52_dialog_content = "薇絲……",
  ui_story_5029_50290006_53_dialog_content = "PlayerName，怎麼了？",
  ui_story_5029_50290006_54_option_content = "我和妳一起吧",
  ui_story_5029_50290006_55_dialog_content = "我一直在等你找我一起呢。",
  ui_story_5029_50290006_56_dialog_content = "不過還有一個問題......",
  ui_story_5029_50290006_57_option_content = "加油！",
  ui_story_5029_50290006_58_dialog_content = "放心，我當然會加油的。",
  ui_story_5029_50290006_59_dialog_content = "保證贏得賞金！",
  ui_story_5029_50290006_60_dialog_content = "（欸，也不用走得那麼快吧？）",
  ui_story_5029_50290006_61_option_content = "啊，沒事",
  ui_story_5029_50290006_62_dialog_content = "好吧。",
  ui_story_5029_50290006_63_dialog_content = "（薇絲今天變得好奇怪......）",
  ui_story_5029_50290006_64_dialog_content = "（我還是繼續忙我的吧。）",
  ui_story_5029_50290006_65_dialog_content = "（要去哪裡看看呢？）",
  ui_story_5029_50290006_66_option_content = "找菲雅",
  ui_story_5029_50290006_67_dialog_content = "菲雅......",
  ui_story_5029_50290006_68_dialog_content = "幹什麼？",
  ui_story_5029_50290006_69_option_content = "我和妳一起吧",
  ui_story_5029_50290006_70_dialog_content = "真的嗎～？",
  ui_story_5029_50290006_71_dialog_content = "咳，雖然我已經有凱羅了，不過多一個人也不壞。",
  ui_story_5029_50290006_72_option_content = "加油！",
  ui_story_5029_50290006_73_dialog_content = "哼，不用你說。",
  ui_story_5029_50290006_74_dialog_content = "菲雅和凱羅當然會加油的。",
  ui_story_5029_50290006_75_dialog_content = "（這孩子是把我也當成競爭對手了嗎？）",
  ui_story_5029_50290006_76_option_content = "啊，沒事",
  ui_story_5029_50290006_77_dialog_content = "哼，那就不要干擾我斷案的靈感。",
  ui_story_5029_50290006_78_dialog_content = "（菲雅今天看起來好難接近啊......）",
  ui_story_5029_50290006_79_dialog_content = "（我還是繼續忙我的吧。）",
  ui_story_5029_50290006_80_dialog_content = "（要去哪裡看看呢？）",
  ui_story_5029_50290006_81_option_content = "獨自搜查",
  ui_story_5029_50290006_82_dialog_content = "（她們看起來都很忙的樣子。）",
  ui_story_5029_50290006_83_dialog_content = "（要不還是我自己搜查吧......）",
  ui_story_5029_50290007_1_dialog_content = "這房子這麼大，我們應該去哪裡搜查？",
  ui_story_5029_50290007_2_dialog_content = "我想想……",
  ui_story_5029_50290007_3_option_content = "去書房",
  ui_story_5029_50290007_4_dialog_content = "好多書架......這完全就是圖書館吧？",
  ui_story_5029_50290007_5_dialog_content = "聽說艾維斯在黎明學院的時候就很愛讀書，成績名列前茅。",
  ui_story_5029_50290007_6_dialog_content = "我不相信會有人成績比妳還好。",
  ui_story_5029_50290007_7_dialog_content = "……",
  ui_story_5029_50290007_8_dialog_content = "按理來說，我還要叫他一聲學長。",
  ui_story_5029_50290007_9_dialog_content = "不過還是別想這些了，我們開始搜查吧。",
  ui_story_5029_50290007_10_dialog_content = "你有什麼比較在意的地方嗎？",
  ui_story_5029_50290007_11_dialog_content = "我想想！",
  ui_story_5029_50290007_12_option_content = "第一排書架",
  ui_story_5029_50290007_13_dialog_content = "這書架上有一本書好眼熟，好像在別的地方也見過。",
  ui_story_5029_50290007_14_dialog_content = "《赤浪醒之助傳·第一輯》？",
  ui_story_5029_50290007_15_dialog_content = "我記得這本書......總是會在最關鍵的地方結束，讓人欲罷不能。",
  ui_story_5029_50290007_16_dialog_content = "這種通俗小說看起來並不像是領主的品味......",
  ui_story_5029_50290007_17_dialog_content = "我倒是覺得書籍沒有貴賤之分，只要好看就會受讀者喜歡。",
  ui_story_5029_50290007_18_dialog_content = "......看來在這件事上，是我的眼光太過狹隘。",
  ui_story_5029_50290007_19_dialog_content = "但是為什麼這裡只有第一輯，領主居然能忍得住不買全套嗎？",
  ui_story_5029_50290007_20_dialog_content = "這的確是個疑點，稍後我去問問贊恩究竟是怎麼回事。",
  ui_story_5029_50290007_21_dialog_content = "還有其他在意的地方嗎？",
  ui_story_5029_50290007_22_option_content = "書桌",
  ui_story_5029_50290007_23_dialog_content = "書桌上的那本書......感覺和其他書都不太一樣。",
  ui_story_5029_50290007_24_dialog_content = "是嗎？拿過來看看好了。",
  ui_story_5029_50290007_25_dialog_content = "<color=#828282>啪！</color>",
  ui_story_5029_50290007_26_dialog_content = "糟了……",
  ui_story_5029_50290007_27_dialog_content = "發生什麼了？啊......竟然把領主最重要的古籍撕毀了？！",
  ui_story_5029_50290007_28_dialog_content = "我要趕快將此事稟告領主！",
  ui_story_5029_50290007_29_dialog_content = "我......我不是故意的啊。",
  ui_story_5029_50290007_30_dialog_content = "領主是個通情達理的人，我會向他解釋的，別太擔心。",
  ui_story_5029_50290007_31_dialog_content = "比起這個，你還有其他在意的地方嗎？",
  ui_story_5029_50290007_32_option_content = "矮櫃",
  ui_story_5029_50290007_33_dialog_content = "領主說，他一直把銀盒放在這個矮櫃裡。",
  ui_story_5029_50290007_34_dialog_content = "嗯......周圍沒有什麼奇怪的痕跡，窗戶也如領主所說沒有被撬開的痕跡。",
  ui_story_5029_50290007_35_dialog_content = "可是這個領主也太大意了吧？放了這麼貴重的東西，櫃子居然沒有鎖起來嗎？",
  ui_story_5029_50290007_36_dialog_content = "但領主的示意圖上顯示，那個銀盒本身有鎖。",
  ui_story_5029_50290007_37_dialog_content = "這也太奇怪了吧......",
  ui_story_5029_50290007_38_dialog_content = "也許銀盒裡面放了什麼更加貴重的東西。",
  ui_story_5029_50290007_39_dialog_content = "有點好奇。",
  ui_story_5029_50290007_40_dialog_content = "比起這個，還有其他在意的地方嗎？",
  ui_story_5029_50290007_41_option_content = "沒有了",
  ui_story_5029_50290007_42_dialog_content = "好像沒有什麼特別的地方了。",
  ui_story_5029_50290007_43_dialog_content = "要不要去看看別的房間？",
  ui_story_5029_50290007_44_option_content = "去大廳",
  ui_story_5029_50290007_45_dialog_content = "大廳可以通向各個房間，也許能找到有價值的線索。",
  ui_story_5029_50290007_46_dialog_content = "你有什麼比較在意的地方嗎？",
  ui_story_5029_50290007_47_dialog_content = "我想想！",
  ui_story_5029_50290007_48_option_content = "花盆",
  ui_story_5029_50290007_49_dialog_content = "你在幹什麼？",
  ui_story_5029_50290007_50_dialog_content = "我在看窗邊的花盆裡會不會有什麼線索......",
  ui_story_5029_50290007_51_dialog_content = "你搜查得倒是仔細。",
  ui_story_5029_50290007_52_dialog_content = "嗯？艾維斯竟然還養了沙漠植物嗎。",
  ui_story_5029_50290007_53_dialog_content = "這種植物身上有刺，要小心一點。",
  ui_story_5029_50290007_54_dialog_content = "你看，這盆植物好像有碰撞的痕跡？",
  ui_story_5029_50290007_55_dialog_content = "好多刺都掉了，碰到它的人一定很痛吧......",
  ui_story_5029_50290007_56_dialog_content = "你還有什麼其他在意的地方嗎？",
  ui_story_5029_50290007_57_option_content = "茶几",
  ui_story_5029_50290007_58_dialog_content = "茶几上有一本書好眼熟，好像在別的地方也見過。",
  ui_story_5029_50290007_59_dialog_content = "《赤浪醒之助傳·第一輯》？",
  ui_story_5029_50290007_60_dialog_content = "我記得這本書......總是會在最關鍵的地方結束，讓人欲罷不能。",
  ui_story_5029_50290007_61_dialog_content = "這種通俗小說看起來並不像是領主的品味......",
  ui_story_5029_50290007_62_dialog_content = "我倒是覺得書籍沒有貴賤之分，只要好看就會受讀者喜歡。",
  ui_story_5029_50290007_63_dialog_content = "......看來在這件事上，是我的眼光太過狹隘。",
  ui_story_5029_50290007_64_dialog_content = "但是為什麼這裡只有第一輯，領主居然能忍得住不買全套嗎？",
  ui_story_5029_50290007_65_dialog_content = "這的確是個疑點，稍後我去問問贊恩究竟是怎麼回事。",
  ui_story_5029_50290007_66_dialog_content = "你還有什麼其他在意的地方嗎？",
  ui_story_5029_50290007_67_option_content = "裝飾物",
  ui_story_5029_50290007_68_dialog_content = "好漂亮的海螺......",
  ui_story_5029_50290007_69_dialog_content = "我聽說，如果把願望說給海螺聽，妳的......",
  ui_story_5029_50290007_70_dialog_content = "你的願望就能實現？",
  ui_story_5029_50290007_71_dialog_content = "原來卡蓮也知道這個傳說！",
  ui_story_5029_50290007_72_dialog_content = "我們要不要趁機向這隻海螺許個願？",
  ui_story_5029_50290007_73_dialog_content = "沒想到你還滿有童心，到現在還相信這種童話。",
  ui_story_5029_50290007_74_dialog_content = "也不是......我只是覺得，把願望說出來的話實現的可能性更大。",
  ui_story_5029_50290007_75_dialog_content = "感覺，這算是一種心理暗示吧。",
  ui_story_5029_50290007_76_dialog_content = "心理暗示嗎......",
  ui_story_5029_50290007_77_dialog_content = "咳咳，如果妳覺得對著海螺許願太幼稚，也可以把願望告訴我。",
  ui_story_5029_50290007_78_dialog_content = "這樣，說不定我就可以幫妳實現。",
  ui_story_5029_50290007_79_dialog_content = "嗯，是這樣嗎？那我希望我們可以快點找到有價值的線索。",
  ui_story_5029_50290007_80_dialog_content = "我這就去搜查下一個地方！",
  ui_story_5029_50290007_81_option_content = "沒有了",
  ui_story_5029_50290007_82_dialog_content = "好像沒有什麼特別的地方了。",
  ui_story_5029_50290007_83_dialog_content = "要不要去看看別的房間？",
  ui_story_5029_50290007_84_option_content = "去咖啡廳",
  ui_story_5029_50290007_85_dialog_content = "兩位要去咖啡廳嗎？請這邊走。",
  ui_story_5029_50290007_86_dialog_content = "領主工作的時候不喜歡有人打擾，所以就在這裡建了一個咖啡廳。",
  ui_story_5029_50290007_87_dialog_content = "他有時候還會親自給客人做咖啡喝。",
  ui_story_5029_50290007_88_dialog_content = "PlayerName，怎麼樣？你有什麼比較在意的地方嗎？",
  ui_story_5029_50290007_89_dialog_content = "我想想！",
  ui_story_5029_50290007_90_option_content = "座椅",
  ui_story_5029_50290007_91_dialog_content = "要不要坐下休息一會？",
  ui_story_5029_50290007_92_dialog_content = "沒關係，我還不累。",
  ui_story_5029_50290007_93_dialog_content = "好吧......那我也能繼續搜！",
  ui_story_5029_50290007_94_dialog_content = "欸，這把椅子上有一份報紙？",
  ui_story_5029_50290007_95_dialog_content = "這是影鎮昨天才出版的報紙......",
  ui_story_5029_50290007_96_dialog_content = "艾維斯竟然這麼快就能拿到手。",
  ui_story_5029_50290007_97_dialog_content = "「空裔多日未現影鎮，空心粉高價求空裔私人行程，意欲追隨......」",
  ui_story_5029_50290007_98_dialog_content = "這是什麼報道？",
  ui_story_5029_50290007_99_dialog_content = "咳咳，肯定和案子沒什麼關係。",
  ui_story_5029_50290007_100_dialog_content = "好吧。那你還有什麼在意的地方嗎？",
  ui_story_5029_50290007_101_option_content = "吧台",
  ui_story_5029_50290007_102_dialog_content = "吧台上有一本書好眼熟，好像在別的地方也見過。",
  ui_story_5029_50290007_103_dialog_content = "《赤浪醒之助傳·第一輯》？",
  ui_story_5029_50290007_104_dialog_content = "我記得這本書......總是會在最關鍵的地方結束，讓人欲罷不能。",
  ui_story_5029_50290007_105_dialog_content = "這種通俗小說看起來並不像是領主的品味......",
  ui_story_5029_50290007_106_dialog_content = "我倒是覺得書籍沒有貴賤之分，只要好看就會受讀者喜歡。",
  ui_story_5029_50290007_107_dialog_content = "......看來在這件事上，是我的眼光太過狹隘。",
  ui_story_5029_50290007_108_dialog_content = "但是為什麼這裡只有第一輯，領主居然能忍得住不買全套嗎？",
  ui_story_5029_50290007_109_dialog_content = "這的確是個疑點，稍後我去問問贊恩究竟是怎麼回事。",
  ui_story_5029_50290007_110_dialog_content = "你還有什麼在意的地方嗎？",
  ui_story_5029_50290007_111_option_content = "牆壁",
  ui_story_5029_50290007_112_dialog_content = "牆上掛著好多漂亮的油畫啊。",
  ui_story_5029_50290007_113_dialog_content = "這些油畫筆觸誇張，但卻能給人一種極強的衝擊力和壓迫感。",
  ui_story_5029_50290007_114_dialog_content = "艾維斯的內心世界，絕對不像看起來那麼柔弱。",
  ui_story_5029_50290007_115_dialog_content = "欸？這張畫像看起來有點眼熟......",
  ui_story_5029_50290007_116_dialog_content = "這是？！",
  ui_story_5029_50290007_117_dialog_content = "欸......我想起來了。",
  ui_story_5029_50290007_118_dialog_content = "這是卡蓮父親年輕時的畫像吧？",
  ui_story_5029_50290007_119_dialog_content = "艾維斯怎麼連這種畫像的複製品都有。",
  ui_story_5029_50290007_120_dialog_content = "為了表示對白夜城的忠誠吧，哈哈哈。",
  ui_story_5029_50290007_121_dialog_content = "說不定他還藏著卡蓮的畫像呢。",
  ui_story_5029_50290007_122_dialog_content = "最好不要讓我看到......",
  ui_story_5029_50290007_123_dialog_content = "別說這個了。你還有什麼其他在意的地方嗎？",
  ui_story_5029_50290007_124_option_content = "沒有了",
  ui_story_5029_50290007_125_dialog_content = "好像沒有什麼特別的地方了。",
  ui_story_5029_50290007_126_dialog_content = "要不要去看看別的房間？",
  ui_story_5029_50290007_127_option_content = "沒什麼可搜的了",
  ui_story_5029_50290007_128_dialog_content = "感覺能搜的地方我們都已經搜查過了。",
  ui_story_5029_50290007_129_dialog_content = "是嗎？",
  ui_story_5029_50290007_130_dialog_content = "有個地方我覺得很奇怪......我再去確認一下！",
  ui_story_5029_50290007_131_dialog_content = "那我就坐在沙發上休息一下好了。",
  ui_story_5029_50290008_1_dialog_content = "那接下來我們去哪裡搜查？",
  ui_story_5029_50290008_2_dialog_content = "我想想……",
  ui_story_5029_50290008_3_option_content = "去書房",
  ui_story_5029_50290008_4_dialog_content = "好多書架......這完全就是圖書館吧？",
  ui_story_5029_50290008_5_dialog_content = "你要是喜歡的話，完全可以在巨像上也建一個圖書室嘛。",
  ui_story_5029_50290008_6_dialog_content = "欸，有了！如果這次能贏得賞金，把這筆錢當作購買圖書的資金也不錯喔～",
  ui_story_5029_50290008_7_dialog_content = "這樣想想感覺更有動力了！我們快繼續搜證吧。",
  ui_story_5029_50290008_8_dialog_content = "要搜哪裡呢......",
  ui_story_5029_50290008_9_option_content = "第一排書架",
  ui_story_5029_50290008_10_dialog_content = "領主涉獵的範圍也太廣了吧？",
  ui_story_5029_50290008_11_dialog_content = "有好多書我連名字都讀不懂......",
  ui_story_5029_50290008_12_dialog_content = "啟光也有大型的圖書館，你要是想學習的話，跟我回啟光就行......",
  ui_story_5029_50290008_13_dialog_content = "欸？等等！《亞人的社會分工探究——以「失落的祕境」為例》......",
  ui_story_5029_50290008_14_dialog_content = "這本書是關於亞人社會的最新研究成果吧？",
  ui_story_5029_50290008_15_dialog_content = "我都還沒有看過！",
  ui_story_5029_50290008_16_dialog_content = "我......我還是看看旁邊的通俗小說吧。",
  ui_story_5029_50290008_17_dialog_content = "不對，我還是繼續搜證吧！",
  ui_story_5029_50290008_18_option_content = "第二排書架",
  ui_story_5029_50290008_19_dialog_content = "薇絲，妳看這本書上面竟然還鑲嵌著寶石！",
  ui_story_5029_50290008_20_dialog_content = "這本好像是領主的家族族譜欸。",
  ui_story_5029_50290008_21_dialog_content = "不過這書裝飾得也太豪華了，單單這本書的造價就夠買好幾天的糧食吧。",
  ui_story_5029_50290008_22_dialog_content = "如果，如果我能找到所有族人的名字，也會想辦法做一本這樣的書吧。",
  ui_story_5029_50290008_23_dialog_content = "PlayerName……",
  ui_story_5029_50290008_24_dialog_content = "那你只好從現在就開始攢錢囉。",
  ui_story_5029_50290008_25_dialog_content = "......哈、哈哈哈。",
  ui_story_5029_50290008_26_dialog_content = "我，我還是繼續搜證吧！",
  ui_story_5029_50290008_27_option_content = "矮櫃",
  ui_story_5029_50290008_28_dialog_content = "領主說，他一直把銀盒放在這個矮櫃裡。",
  ui_story_5029_50290008_29_dialog_content = "這個矮櫃，沒有掛鎖欸。",
  ui_story_5029_50290008_30_dialog_content = "裡面空空如也，什麼東西都沒有。",
  ui_story_5029_50290008_31_dialog_content = "如果是我的話，一定會準備好幾把鎖把櫃子給鎖住。",
  ui_story_5029_50290008_32_dialog_content = "就算睡覺也要把鑰匙放在枕頭下面！",
  ui_story_5029_50290008_33_dialog_content = "喔～我知道了！",
  ui_story_5029_50290008_34_dialog_content = "下次去你的枕頭下面找找有沒有什麼寶藏的鑰匙好了。",
  ui_story_5029_50290008_35_dialog_content = "這……",
  ui_story_5029_50290008_36_dialog_content = "我還是繼續搜證吧！",
  ui_story_5029_50290008_37_option_content = "好像都搜完了",
  ui_story_5029_50290008_38_dialog_content = "我們換個房間搜吧？",
  ui_story_5029_50290008_39_dialog_content = "好呀，你想去哪裡？",
  ui_story_5029_50290008_40_option_content = "去大廳",
  ui_story_5029_50290008_41_dialog_content = "這麼大的房子，領主平時只用它來工作嗎？",
  ui_story_5029_50290008_42_dialog_content = "感覺完全可以住在這裡面啊......",
  ui_story_5029_50290008_43_dialog_content = "你都有巨像了，還羨慕這個嗎？",
  ui_story_5029_50290008_44_dialog_content = "嘿嘿，就是單純好奇而已。",
  ui_story_5029_50290008_45_dialog_content = "開玩笑的啦，我們快搜證吧。",
  ui_story_5029_50290008_46_dialog_content = "要搜哪裡呢......",
  ui_story_5029_50290008_47_option_content = "花盆",
  ui_story_5029_50290008_48_dialog_content = "花盆裡面會不會藏著什麼機關？",
  ui_story_5029_50290008_49_dialog_content = "你的想像力可真夠豐富。",
  ui_story_5029_50290008_50_dialog_content = "嗯......可惜什麼都沒有。",
  ui_story_5029_50290008_51_dialog_content = "這花倒是滿漂亮，好像還有種清香？嗅嗅～",
  ui_story_5029_50290008_52_dialog_content = "怎麼感覺頭有點暈。",
  ui_story_5029_50290008_53_dialog_content = "難道是這花有問題......",
  ui_story_5029_50290008_54_dialog_content = "贊恩，你快來看看......這裡的花是不是被人下了毒？",
  ui_story_5029_50290008_55_dialog_content = "不是的，這種花叫夾竹仙，本身就有一點毒性。",
  ui_story_5029_50290008_56_dialog_content = "不過只要不吃下去，就不會有事。",
  ui_story_5029_50290008_57_dialog_content = "為什麼要在屋子裡種有毒的花草......真搞不懂這些貴族的審美。",
  ui_story_5029_50290008_58_dialog_content = "PlayerName，我扶你去沙發上休息一下再說吧。",
  ui_story_5029_50290008_59_dialog_content = "沒關係，我還能繼續！",
  ui_story_5029_50290008_60_option_content = "沙發",
  ui_story_5029_50290008_61_dialog_content = "這張沙發坐起來真舒服......",
  ui_story_5029_50290008_62_dialog_content = "巨像裡如果也有這樣的沙發就好了。",
  ui_story_5029_50290008_63_dialog_content = "咳咳，我想你一定不想知道這張沙發的價格。",
  ui_story_5029_50290008_64_dialog_content = "……",
  ui_story_5029_50290008_65_dialog_content = "那我還是站起來吧。",
  ui_story_5029_50290008_66_dialog_content = "怎麼了？",
  ui_story_5029_50290008_67_dialog_content = "其實......我覺得坐在草垛上也滿舒服！",
  ui_story_5029_50290008_68_dialog_content = "呼～今天開源節流的任務又達成一項。",
  ui_story_5029_50290008_69_dialog_content = "咳咳，那我們繼續搜查吧。",
  ui_story_5029_50290008_70_option_content = "裝飾物",
  ui_story_5029_50290008_71_dialog_content = "PlayerName，快看，這裡有一隻海螺欸！",
  ui_story_5029_50290008_72_dialog_content = "好漂亮，這麼大的海螺應該很少見吧。",
  ui_story_5029_50290008_73_dialog_content = "我聽人說，有些偏僻的小島上流通的貨幣就是貝殼和海螺。",
  ui_story_5029_50290008_74_dialog_content = "那這隻海螺豈不是很值錢？",
  ui_story_5029_50290008_75_dialog_content = "可惜我們在這裡只能用白夜幣。",
  ui_story_5029_50290008_76_dialog_content = "不過如果妳喜歡的話，我們可以去海邊逛逛......",
  ui_story_5029_50290008_77_dialog_content = "說不定可以撿到比這個更大更好看的海螺。",
  ui_story_5029_50290008_78_dialog_content = "嗯，你說話可要作數喔～",
  ui_story_5029_50290008_79_dialog_content = "沒問題！我們繼續搜查吧。",
  ui_story_5029_50290008_80_option_content = "好像都搜完了",
  ui_story_5029_50290008_81_dialog_content = "我們換個房間搜吧？",
  ui_story_5029_50290008_82_dialog_content = "好呀，你想去哪裡？",
  ui_story_5029_50290008_83_option_content = "去咖啡廳",
  ui_story_5029_50290008_84_dialog_content = "兩位要去咖啡廳嗎？請這邊走。",
  ui_story_5029_50290008_85_dialog_content = "領主工作的時候不喜歡有人打擾，所以就在這裡建了一個咖啡廳。",
  ui_story_5029_50290008_86_dialog_content = "他有時候還會親自給客人做咖啡喝。",
  ui_story_5029_50290008_87_dialog_content = "沒想到，這裡可真是別有洞天呢。",
  ui_story_5029_50290008_88_dialog_content = "這麼多東西，要搜哪裡呢......",
  ui_story_5029_50290008_89_option_content = "咖啡杯",
  ui_story_5029_50290008_90_dialog_content = "這些杯子的花紋和款式竟然都不一樣！",
  ui_story_5029_50290008_91_dialog_content = "光是這些杯子就可以開個展覽了。",
  ui_story_5029_50290008_92_dialog_content = "欸，奇怪，這杯子裡為什麼還有咖啡？",
  ui_story_5029_50290008_93_dialog_content = "應該是昨天的哪位客人沒喝完的咖啡吧。",
  ui_story_5029_50290008_94_dialog_content = "<color=#828282>叮鈴......</color>",
  ui_story_5029_50290008_95_dialog_content = "裡面好像有什麼東西？",
  ui_story_5029_50290008_96_dialog_content = "倒出來看看......",
  ui_story_5029_50290008_97_dialog_content = "欸，是個徽章......好像在哪裡見過？",
  ui_story_5029_50290008_98_dialog_content = "這是白夜城騎士團的徽章！",
  ui_story_5029_50290008_99_dialog_content = "怎麼會出現在這裡？難道說昨天來的那位公爵......？",
  ui_story_5029_50290008_100_dialog_content = "一會要找贊恩好好問問。",
  ui_story_5029_50290008_101_dialog_content = "嗯！我們繼續搜查吧。",
  ui_story_5029_50290008_102_option_content = "座椅",
  ui_story_5029_50290008_103_dialog_content = "PlayerName，你拉一下那把椅子好嗎？",
  ui_story_5029_50290008_104_dialog_content = "沒問題，妳累了嗎？",
  ui_story_5029_50290008_105_dialog_content = "不是啦，我覺得那椅子上面好像有什麼東西。",
  ui_story_5029_50290008_106_dialog_content = "還真是......這有一份報紙！",
  ui_story_5029_50290008_107_dialog_content = "「安德森家族力挺妮娜大小姐操盤大型商業活動......」",
  ui_story_5029_50290008_108_dialog_content = "「知情人士稱後者曾因空裔而離家出走？」",
  ui_story_5029_50290008_109_dialog_content = "這，這樣的報道很容易被人誤會的吧？",
  ui_story_5029_50290008_110_dialog_content = "不過人家也沒寫錯，不是嗎？",
  ui_story_5029_50290008_111_dialog_content = "咳咳……",
  ui_story_5029_50290008_112_dialog_content = "我們還是繼續搜查吧。",
  ui_story_5029_50290008_113_option_content = "牆壁",
  ui_story_5029_50290008_114_dialog_content = "感覺這牆上掛著的畫都價值不菲呢。",
  ui_story_5029_50290008_115_dialog_content = "那犯人為什麼不偷這些畫呢？",
  ui_story_5029_50290008_116_dialog_content = "也許這些畫不是出自什麼大師之手吧。",
  ui_story_5029_50290008_117_dialog_content = "角落裡好像有一幅很奇怪的畫......",
  ui_story_5029_50290008_118_dialog_content = "這，這不是你送給我的畫嗎？怎麼會在這裡？",
  ui_story_5029_50290008_119_dialog_content = "......畫附近有沒有寫經銷商的名字？",
  ui_story_5029_50290008_120_dialog_content = "蜂、銀城？！",
  ui_story_5029_50290008_121_dialog_content = "他們竟然能把我的仿作都賣到好泊城來？",
  ui_story_5029_50290008_122_dialog_content = "從這個角度來看，他們兩個還真是厲害......",
  ui_story_5029_50290008_123_dialog_content = "不過我們還是繼續搜查吧。",
  ui_story_5029_50290008_124_option_content = "好像都搜完了",
  ui_story_5029_50290008_125_dialog_content = "我們換個房間搜吧？",
  ui_story_5029_50290008_126_dialog_content = "好呀，你想去哪裡？",
  ui_story_5029_50290008_127_option_content = "沒什麼可搜的了",
  ui_story_5029_50290008_128_dialog_content = "感覺能搜的地方我們都已經搜查過了。",
  ui_story_5029_50290008_129_dialog_content = "有個地方我還是覺得很奇怪......",
  ui_story_5029_50290008_130_dialog_content = "我再去確認一下！",
  ui_story_5029_50290008_131_dialog_content = "我在沙發這裡等妳。",
  ui_story_5029_50290009_1_dialog_content = "所以現在......我們該幹什麼呀？",
  ui_story_5029_50290009_2_dialog_content = "我想想……",
  ui_story_5029_50290009_3_option_content = "去書房",
  ui_story_5029_50290009_4_dialog_content = "凱羅，保持隊形，保持警惕！",
  ui_story_5029_50290009_5_dialog_content = "囉！",
  ui_story_5029_50290009_6_dialog_content = "我們還有隊形？",
  ui_story_5029_50290009_7_dialog_content = "PlayerName在前，凱羅在後，菲雅在中間。",
  ui_story_5029_50290009_7X1_dialog_content = "這就是我們的一條龍隊形！",
  ui_story_5029_50290009_8_dialog_content = "好吧......不過這房間還滿大。",
  ui_story_5029_50290009_9_dialog_content = "我們要調查哪裡呀？",
  ui_story_5029_50290009_10_option_content = "第一排書架",
  ui_story_5029_50290009_11_dialog_content = "這裡有一本書佔據了好大的空間啊。",
  ui_story_5029_50290009_12_dialog_content = "這麼浮誇的封面......",
  ui_story_5029_50290009_13_dialog_content = "不會就是傳說中鼓吹大家盜獵神奇動物的書吧？！",
  ui_story_5029_50290009_14_dialog_content = "呃，裡面的內容居然是師父的《千奇百怪小動物》？",
  ui_story_5029_50290009_15_dialog_content = "看來是領主為這本書重新做了封皮。",
  ui_story_5029_50290009_16_dialog_content = "沒想到領主大叔還讀過師父的書啊？",
  ui_story_5029_50290009_17_dialog_content = "那他一定也會喜歡菲雅的書吧？",
  ui_story_5029_50290009_18_dialog_content = "妳的書已經出版了嗎？",
  ui_story_5029_50290009_19_dialog_content = "還沒有……",
  ui_story_5029_50290009_20_dialog_content = "不過再過幾年，菲雅的書一定會比師父的更受歡迎的！",
  ui_story_5029_50290009_21_dialog_content = "好好好，但現在我們還是繼續調查吧。",
  ui_story_5029_50290009_22_option_content = "牆壁",
  ui_story_5029_50290009_23_dialog_content = "囉......",
  ui_story_5029_50290009_24_dialog_content = "凱羅，不用怕。",
  ui_story_5029_50290009_25_dialog_content = "這只是個小鹿頭骨而已。",
  ui_story_5029_50290009_26_dialog_content = "囉嗚......",
  ui_story_5029_50290009_27_dialog_content = "我怎麼覺得妳愈是解釋，凱羅愈是害怕？",
  ui_story_5029_50290009_28_dialog_content = "可能是凱羅又回想起被小鹿撞飛的那次經歷了吧。",
  ui_story_5029_50290009_29_dialog_content = "囉！！！",
  ui_story_5029_50290009_30_dialog_content = "凱羅，別走遠。我們還要繼續調查呢！",
  ui_story_5029_50290009_31_option_content = "矮櫃",
  ui_story_5029_50290009_32_dialog_content = "領主說，他一直把銀盒放在這個矮櫃裡。",
  ui_story_5029_50290009_33_dialog_content = "裡面已經空蕩蕩的了......",
  ui_story_5029_50290009_34_dialog_content = "奇怪，這個櫃子居然沒有掛鎖。",
  ui_story_5029_50290009_35_dialog_content = "可能是領主大叔覺得房門外面有鎖，所以櫃子不用鎖也沒關係吧？",
  ui_story_5029_50290009_36_dialog_content = "不過那個那個銀盒本身倒是有一把鎖呢。",
  ui_story_5029_50290009_37_dialog_content = "喔～銀盒裡面說不定放了什麼更貴重的東西呀！",
  ui_story_5029_50290009_38_dialog_content = "妳可真是個小機靈。",
  ui_story_5029_50290009_39_dialog_content = "請叫我「神奇動物專家兼機靈大偵探」！",
  ui_story_5029_50290009_40_dialog_content = "好的，「神奇動物專家兼機靈大偵探」，讓我們繼續調查吧。",
  ui_story_5029_50290009_41_option_content = "好像都搜完了",
  ui_story_5029_50290009_42_dialog_content = "那現在怎麼辦......",
  ui_story_5029_50290009_43_dialog_content = "可以換個房間接著搜！",
  ui_story_5029_50290009_44_dialog_content = "那接下來是去......？",
  ui_story_5029_50290009_45_option_content = "去大廳",
  ui_story_5029_50290009_46_dialog_content = "大廳可以通向每個房間，我們要好好搜查。",
  ui_story_5029_50290009_47_dialog_content = "這種常識問題，就不用講解啦。",
  ui_story_5029_50290009_48_dialog_content = "現在的問題是......",
  ui_story_5029_50290009_49_dialog_content = "我們要調查哪裡呀？",
  ui_story_5029_50290009_50_option_content = "花盆",
  ui_story_5029_50290009_51_dialog_content = "花盆裡面會不會藏著什麼機關？",
  ui_story_5029_50290009_52_dialog_content = "等一下！！！",
  ui_story_5029_50290009_53_dialog_content = "怎，怎麼了？忽然這麼大聲？",
  ui_story_5029_50290009_54_dialog_content = "菲雅在師父的筆記裡見過這種花，好像有劇毒！",
  ui_story_5029_50290009_55_dialog_content = "多謝菲雅提醒......還好我沒有碰到！",
  ui_story_5029_50290009_56_dialog_content = "欸？凱羅，不要再去聞那朵花啦！",
  ui_story_5029_50290009_57_dialog_content = "凱羅，快回來。我們要繼續調查了。",
  ui_story_5029_50290009_58_option_content = "沙發",
  ui_story_5029_50290009_59_dialog_content = "怎麼了，有什麼發現嗎？",
  ui_story_5029_50290009_60_dialog_content = "按照一般的故事套路，沙發底下也許會隱藏著什麼見不得人的祕密。",
  ui_story_5029_50290009_61_dialog_content = "可是這麼窄的縫隙，連凱羅的腦袋都進不去，應該不會藏著銀盒吧？",
  ui_story_5029_50290009_62_dialog_content = "藏不了銀盒，但也許可以藏得下其他東西。",
  ui_story_5029_50290009_63_dialog_content = "比如……",
  ui_story_5029_50290009_64_dialog_content = "欸，妳還真的從沙發底下掏出東西來了？",
  ui_story_5029_50290009_65_dialog_content = "可我不知道這是什麼啊？",
  ui_story_5029_50290009_66_dialog_content = "是什麼東西碎掉的殘渣吧。",
  ui_story_5029_50290009_67_dialog_content = "天哪！這個是重要線索吧？",
  ui_story_5029_50290009_68_dialog_content = "領主大叔不是說，中午有女僕打掃過衛生嗎？",
  ui_story_5029_50290009_69_dialog_content = "也許是她沒有打掃乾淨吧。",
  ui_story_5029_50290009_70_dialog_content = "不對！「神奇動物專家兼大偵探」的直覺告訴我，沒有那麼簡單！",
  ui_story_5029_50290009_71_dialog_content = "一會我要找贊恩好好問問關於這個女僕的資訊。",
  ui_story_5029_50290009_72_dialog_content = "嗯，那我們繼續調查吧。",
  ui_story_5029_50290009_73_option_content = "裝飾物",
  ui_story_5029_50290009_74_dialog_content = "天哪！這裡有一隻神奇動物，PlayerName快來看！",
  ui_story_5029_50290009_75_dialog_content = "呃，妳不會沒有見過海螺吧？",
  ui_story_5029_50290009_76_dialog_content = "我可是神奇動物專家欸，什麼動物沒見過！",
  ui_story_5029_50290009_77_dialog_content = "只，只是我的確是第一次親眼見到這種顏色的海螺......",
  ui_story_5029_50290009_78_dialog_content = "據說把願望說給海螺聽，願望就會實現。",
  ui_story_5029_50290009_79_dialog_content = "喂，你這種說法都是騙小孩子的吧？",
  ui_story_5029_50290009_80_dialog_content = "我已經不是小孩子了！才不會上你的當呢。",
  ui_story_5029_50290009_81_dialog_content = "海螺海螺，希望我能幫領主找到遺失之物。",
  ui_story_5029_50290009_82_dialog_content = "你怎麼一個人許願呀？既然這樣......",
  ui_story_5029_50290009_83_dialog_content = "海螺海螺，菲雅才是幫領主大叔找到遺失之物的人。",
  ui_story_5029_50290009_84_dialog_content = "咳咳，我們快繼續調查吧。",
  ui_story_5029_50290009_85_option_content = "好像都搜完了",
  ui_story_5029_50290009_86_dialog_content = "那現在怎麼辦......",
  ui_story_5029_50290009_87_dialog_content = "可以換個房間接著搜！",
  ui_story_5029_50290009_88_dialog_content = "那接下來是去......？",
  ui_story_5029_50290009_89_option_content = "去咖啡廳",
  ui_story_5029_50290009_90_dialog_content = "兩位要去咖啡廳嗎？請這邊走。",
  ui_story_5029_50290009_91_dialog_content = "領主工作的時候不喜歡有人打擾，所以就在這裡建了一個咖啡廳。",
  ui_story_5029_50290009_92_dialog_content = "他有時候還會親自給客人做咖啡喝。",
  ui_story_5029_50290009_93_dialog_content = "哇哦，我好像聞到了香香的味道！",
  ui_story_5029_50290009_94_dialog_content = "囉！",
  ui_story_5029_50290009_95_dialog_content = "還要調查哪裡呀？",
  ui_story_5029_50290009_96_option_content = "操作間",
  ui_story_5029_50290009_97_dialog_content = "這裡居然有......",
  ui_story_5029_50290009_98_dialog_content = "蜂蜜蛋糕？",
  ui_story_5029_50290009_99_dialog_content = "沒想到在好泊城還能吃到北境特產。",
  ui_story_5029_50290009_100_dialog_content = "我在影鎮都沒吃過這個欸。",
  ui_story_5029_50290009_101_dialog_content = "好吃嗎？",
  ui_story_5029_50290009_102_dialog_content = "好吃是好吃，但是放在這裡的東西我們最好不要碰。",
  ui_story_5029_50290009_103_dialog_content = "哼，菲雅當然知道。",
  ui_story_5029_50290009_104_dialog_content = "听說好泊城有很多好吃的美食。",
  ui_story_5029_50290009_105_dialog_content = "等菲雅找回銀盒，贏了賞金......我們想吃多少就吃多少！",
  ui_story_5029_50290009_106_dialog_content = "囉！",
  ui_story_5029_50290009_107_dialog_content = "咳咳，我們快繼續調查吧。",
  ui_story_5029_50290009_108_option_content = "地板",
  ui_story_5029_50290009_109_dialog_content = "凱羅，你怎麼忽然躲在我身後發抖？",
  ui_story_5029_50290009_110_dialog_content = "那邊有什麼東西嗎？",
  ui_story_5029_50290009_111_dialog_content = "啊！！！PlayerName，這裡有一把沾著血的水果刀！",
  ui_story_5029_50290009_112_dialog_content = "盜竊案不會升級成兇殺案了吧？",
  ui_story_5029_50290009_113_dialog_content = "唔……",
  ui_story_5029_50290009_114_dialog_content = "咳咳，我去看看。",
  ui_story_5029_50290009_115_dialog_content = "哈哈哈，沒事啦。那些只是草莓醬。",
  ui_story_5029_50290009_116_dialog_content = "我，我本來也沒有害怕！",
  ui_story_5029_50290009_117_dialog_content = "哎唷！",
  ui_story_5029_50290009_118_dialog_content = "PlayerName，你手上沾了好多草莓醬呀。",
  ui_story_5029_50290009_119_dialog_content = "不是草莓醬。我不小心割傷了自己的手指，這次是真的流血了......",
  ui_story_5029_50290009_120_dialog_content = "啊啊啊啊怎麼辦？",
  ui_story_5029_50290009_121_dialog_content = "有了！凱羅的唾液可以消毒殺菌！凱羅，快幫幫PlayerName吧。",
  ui_story_5029_50290009_122_dialog_content = "囉！",
  ui_story_5029_50290009_123_dialog_content = "沒，沒關係，問題不嚴重......我們還是繼續調查吧。",
  ui_story_5029_50290009_124_option_content = "吧台",
  ui_story_5029_50290009_125_dialog_content = "吧台上那本書妳檢查過了嗎？",
  ui_story_5029_50290009_126_dialog_content = "我看看......《赤浪醒之助傳·第一輯》？",
  ui_story_5029_50290009_127_dialog_content = "哼，不過是一些虛構的故事嘛。",
  ui_story_5029_50290009_128_dialog_content = "我還是更喜歡師父寫的《千奇百怪的小動物》！",
  ui_story_5029_50290009_129_dialog_content = "是嗎？",
  ui_story_5029_50290009_130_dialog_content = "怎、怎麼了？",
  ui_story_5029_50290009_131_dialog_content = "雖然妳嘴上一直嫌棄妳師父，但其實妳還是很崇敬他的嘛！",
  ui_story_5029_50290009_132_dialog_content = "要不然也不會把「師父」掛在嘴邊。",
  ui_story_5029_50290009_133_dialog_content = "巧合，只是巧合！",
  ui_story_5029_50290009_134_dialog_content = "好啦，那我們繼續調查吧。",
  ui_story_5029_50290009_135_option_content = "好像都調查過了",
  ui_story_5029_50290009_136_dialog_content = "那現在怎麼辦......",
  ui_story_5029_50290009_137_dialog_content = "可以換個房間接著搜！",
  ui_story_5029_50290009_138_dialog_content = "那接下來是去......？",
  ui_story_5029_50290009_139_option_content = "沒什麼可搜的了",
  ui_story_5029_50290009_140_dialog_content = "感覺能搜的地方我們都已經搜查過了。",
  ui_story_5029_50290009_141_dialog_content = "喔～終於可以休息了......",
  ui_story_5029_50290009_142_dialog_content = "欸，等等。凱羅又跑去哪裡了？",
  ui_story_5029_50290009_143_dialog_content = "PlayerName，我去找凱羅了！",
  ui_story_5029_50290009_144_dialog_content = "好，妳自己也小心點。",
  ui_story_5029_50290010_1_dialog_content = "（這房子真是有夠大......）",
  ui_story_5029_50290010_2_dialog_content = "（要去哪個房間看看呢？）",
  ui_story_5029_50290010_3_option_content = "去書房",
  ui_story_5029_50290010_4_dialog_content = "隨便逛逛吧......",
  ui_story_5029_50290010_5_option_content = "第一排書架",
  ui_story_5029_50290010_6_dialog_content = "這裡有一本書好眼熟。",
  ui_story_5029_50290010_7_dialog_content = "《赤浪醒之助傳·第一輯》？",
  ui_story_5029_50290010_8_dialog_content = "為什麼只有第一輯？",
  ui_story_5029_50290010_9_option_content = "書桌",
  ui_story_5029_50290010_10_dialog_content = "書桌上也有一本書......好破啊。",
  ui_story_5029_50290010_11_dialog_content = "<color=#828282>啪！</color>",
  ui_story_5029_50290010_12_dialog_content = "啊，書被我撕壞了？",
  ui_story_5029_50290010_13_dialog_content = "這下可糟糕了......找個機會向領主道歉吧。",
  ui_story_5029_50290010_14_dialog_content = "為什麼感覺今天諸事不順。",
  ui_story_5029_50290010_15_option_content = "矮櫃",
  ui_story_5029_50290010_16_dialog_content = "領主說，他一直把銀盒放在這個矮櫃裡。",
  ui_story_5029_50290010_17_dialog_content = "櫃子倒是滿好看，可惜裡面的東西已經不見了。",
  ui_story_5029_50290010_18_option_content = "好像都逛完了",
  ui_story_5029_50290010_19_dialog_content = "換個房間接著逛吧。",
  ui_story_5029_50290010_20_option_content = "去大廳",
  ui_story_5029_50290010_21_dialog_content = "大廳，空蕩蕩的。",
  ui_story_5029_50290010_22_dialog_content = "隨便逛逛吧......",
  ui_story_5029_50290010_23_option_content = "花盆",
  ui_story_5029_50290010_24_dialog_content = "花盆裡面會不會藏著什麼機關？",
  ui_story_5029_50290010_25_dialog_content = "嗅嗅～",
  ui_story_5029_50290010_26_dialog_content = "小心！這花有毒，不能與皮膚接觸！",
  ui_story_5029_50290010_27_dialog_content = "怎麼辦......感覺頭好像有點暈。",
  ui_story_5029_50290010_28_dialog_content = "看您的樣子應該沒有中毒，稍微休息一下也許會好些。",
  ui_story_5029_50290010_29_dialog_content = "謝謝，我應該還能繼續......",
  ui_story_5029_50290010_30_option_content = "沙發",
  ui_story_5029_50290010_31_dialog_content = "在沙發上坐著，看她們幾個忙忙碌碌的，心裡有點不是滋味......",
  ui_story_5029_50290010_32_dialog_content = "嗯？我好像踩到了什麼東西？",
  ui_story_5029_50290010_33_dialog_content = "是什麼東西碎掉的殘渣......？",
  ui_story_5029_50290010_34_dialog_content = "還以為女僕打掃過的房子會很乾淨呢。",
  ui_story_5029_50290010_35_option_content = "裝飾物",
  ui_story_5029_50290010_36_dialog_content = "這隻海螺好漂亮。",
  ui_story_5029_50290010_37_dialog_content = "不過和這個案子也沒什麼關係。",
  ui_story_5029_50290010_38_option_content = "好像都逛完了",
  ui_story_5029_50290010_39_dialog_content = "換個房間接著逛吧。",
  ui_story_5029_50290010_40_option_content = "去咖啡廳",
  ui_story_5029_50290010_41_dialog_content = "您要去咖啡廳嗎？請這邊走。",
  ui_story_5029_50290010_42_dialog_content = "領主工作的時候不喜歡有人打擾，所以就在這裡建了一個咖啡廳。",
  ui_story_5029_50290010_43_dialog_content = "他有時候還會親自給客人做咖啡喝。",
  ui_story_5029_50290010_44_dialog_content = "隨便逛逛吧......",
  ui_story_5029_50290010_45_option_content = "咖啡杯",
  ui_story_5029_50290010_46_dialog_content = "領主的審美確實很不錯，連杯子都這麼好看。",
  ui_story_5029_50290010_47_dialog_content = "這杯子裡還有咖啡？",
  ui_story_5029_50290010_48_dialog_content = "<color=#828282>叮咚！</color>",
  ui_story_5029_50290010_49_dialog_content = "欸，咖啡裡有什麼東西？",
  ui_story_5029_50290010_50_dialog_content = "......一枚徽章？",
  ui_story_5029_50290010_51_dialog_content = "幸好我沒喝，要不然會被噎死的吧......",
  ui_story_5029_50290010_52_option_content = "地板",
  ui_story_5029_50290010_53_dialog_content = "那裡有個什麼東西，看不太清楚......",
  ui_story_5029_50290010_54_dialog_content = "沾了血的水果刀？",
  ui_story_5029_50290010_55_dialog_content = "救命！",
  ui_story_5029_50290010_56_dialog_content = "抱歉，忘了告訴您......",
  ui_story_5029_50290010_57_dialog_content = "這只是沾了果醬的水果刀。",
  ui_story_5029_50290010_58_dialog_content = "您還好吧，要休息一下嗎？",
  ui_story_5029_50290010_59_dialog_content = "沒，沒關係......我平復一下心情就好。",
  ui_story_5029_50290010_60_option_content = "牆壁",
  ui_story_5029_50290010_61_dialog_content = "牆上掛著好多漂亮的油畫啊。",
  ui_story_5029_50290010_62_dialog_content = "不過現在我也沒有心情欣賞。",
  ui_story_5029_50290010_63_option_content = "好像都逛完了",
  ui_story_5029_50290010_64_dialog_content = "換個房間接著逛吧。",
  ui_story_5029_50290010_65_option_content = "不想逛了",
  ui_story_5029_50290010_66_dialog_content = "逛了這麼多地方，都沒什麼收穫......",
  ui_story_5029_50290010_67_dialog_content = "呼，大家好像還在忙碌。",
  ui_story_5029_50290010_68_dialog_content = "我先休息一下吧。",
  ui_story_5029_50290011_1_dialog_content = "這沙發還真是舒服啊。",
  ui_story_5029_50290011_2_dialog_content = "不知不覺睡著了，時間應該沒有過去太久吧？",
  ui_story_5029_50290011_3_dialog_content = "接下來該怎麼辦呢......",
  ui_story_5029_50290011_4_dialog_content = "其他幾位偵探好像準備出去調查嫌疑人了，您也要一起嗎？",
  ui_story_5029_50290011_5_dialog_content = "欸，是嗎？",
  ui_story_5029_50290011_6_dialog_content = "啊，大家等等我！",
  ui_story_5029_50290011_7_option_content = "詢問卡蓮",
  ui_story_5029_50290011_8_dialog_content = "卡蓮，妳準備去哪裡啊？",
  ui_story_5029_50290011_9_dialog_content = "你有沒有發現，這屋子裡有一本很奇怪的書。",
  ui_story_5029_50290011_10_dialog_content = "奇怪的書嗎......這裡的書大部分我都沒有見過。",
  ui_story_5029_50290011_11_dialog_content = "只有那本<color=#793f76>《赤浪醒之助傳》</color>我讀過一些。",
  ui_story_5029_50290011_12_dialog_content = "對，就是那本。",
  ui_story_5029_50290011_13_dialog_content = "起初我只是覺得奇怪，這種通俗小說不像是艾維斯喜歡讀的。",
  ui_story_5029_50290011_14_dialog_content = "但四處搜查後發現，這間屋子裡到處都有這本小說。",
  ui_story_5029_50290011_15_dialog_content = "原來領主和我一樣，這麼愛讀《赤浪醒之助傳》？！",
  ui_story_5029_50290011_16_dialog_content = "等等......不對啊。如果愛看的話，也要買全套才對嘛。",
  ui_story_5029_50290011_17_dialog_content = "可是剛剛我找來找去，只有《赤浪醒之助傳·第一輯》。",
  ui_story_5029_50290011_18_dialog_content = "我剛才問了贊恩，他說領主從來都沒有買過這種通俗小說。",
  ui_story_5029_50290011_19_dialog_content = "巧的是，昨天的那位商人就是來向領主推銷通俗小說的出版業務的。",
  ui_story_5029_50290011_20_dialog_content = "但這和失竊案有什麼關係呢？",
  ui_story_5029_50290011_21_dialog_content = "或許，你聽到這位商人的名字就會明白了。",
  ui_story_5029_50290011_22_dialog_content = "我......我認識嗎？",
  ui_story_5029_50290011_23_dialog_content = "贊恩說，那位商人名叫<color=#793f76>狡木一郎</color>。",
  ui_story_5029_50290011_24_dialog_content = "沒聽說過，但感覺很像雲島那邊的人......",
  ui_story_5029_50290011_25_dialog_content = "等等！狡木一郎......狡木？！",
  ui_story_5029_50290011_26_dialog_content = "這個人真是大膽，以為用這麼拙劣的化名就能瞞天過海嗎？",
  ui_story_5029_50290011_27_dialog_content = "不過就算這個人真的是狡木，也不一定是他偷走了銀盒吧？",
  ui_story_5029_50290011_28_dialog_content = "紅油扳手本來就是一群無惡不作的強盜。",
  ui_story_5029_50290011_28X1_dialog_content = "這種偷盜行為對他們而言就像家常便飯。",
  ui_story_5029_50290011_29_dialog_content = "這群傢伙，竟敢把髒手伸到白夜城的領地之上。",
  ui_story_5029_50290011_30_dialog_content = "我定將用手中的長槍，親自將他驅逐出境！",
  ui_story_5029_50290011_31_dialog_content = "要不然......還是親自去問問他吧。",
  ui_story_5029_50290011_32_dialog_content = "我也正有此意。",
  ui_story_5029_50290011_33_dialog_content = "我正準備去狡木住的地方找他一探究竟。",
  ui_story_5029_50290011_34_option_content = "我想和妳一起去",
  ui_story_5029_50290011_35_dialog_content = "好，我們走。",
  ui_story_5029_50290011_36_option_content = "祝妳好運",
  ui_story_5029_50290011_37_dialog_content = "多謝。",
  ui_story_5029_50290011_38_option_content = "詢問薇絲",
  ui_story_5029_50290011_39_dialog_content = "薇絲，妳準備去哪裡啊？",
  ui_story_5029_50290011_40_dialog_content = "你還記不記得，咖啡廳裡出現了一件不屬於這裡的東西？",
  ui_story_5029_50290011_41_dialog_content = "一件不屬於這裡的東西？",
  ui_story_5029_50290011_42_dialog_content = "妳是說那個藏在咖啡杯裡的<color=#793f76>白夜城騎士徽章</color>吧。",
  ui_story_5029_50290011_43_dialog_content = "對，就是那枚徽章。",
  ui_story_5029_50290011_44_dialog_content = "起初我想，這也許是領主自己的收藏。",
  ui_story_5029_50290011_45_dialog_content = "嗯，有道理。畢竟好泊城是白夜城的領土，領主有一枚騎士徽章也很正常。",
  ui_story_5029_50290011_46_dialog_content = "可如果是自己的收藏品，應該會好好保管起來吧。",
  ui_story_5029_50290011_47_dialog_content = "再怎麼說，也不能出現在給客人喝的咖啡裡......",
  ui_story_5029_50290011_48_dialog_content = "對，所以只有一個可能。",
  ui_story_5029_50290011_49_dialog_content = "這枚徽章是某位客人的東西。",
  ui_story_5029_50290011_50_dialog_content = "而昨天有一個人恰好來自白夜城。",
  ui_story_5029_50290011_51_dialog_content = "妳是說那位來自白夜城的公爵？",
  ui_story_5029_50290011_52_dialog_content = "剛才我好像聽到領主說那位公爵叫什麼......伊斯庫公爵。",
  ui_story_5029_50290011_53_dialog_content = "你知道這位伊斯庫公爵的全名是什麼嗎？",
  ui_story_5029_50290011_54_dialog_content = "<color=#793f76>貝芙麗·伊斯庫</color>！",
  ui_story_5029_50290011_55_dialog_content = "妳是說......貝芙麗？",
  ui_story_5029_50290011_56_dialog_content = "就算真的是她的徽章，也不能證明她和失竊案有什麼關係吧？",
  ui_story_5029_50290011_57_dialog_content = "我剛才問了贊恩，他說昨天貝芙麗和領主發生過一些爭吵。",
  ui_story_5029_50290011_58_dialog_content = "妳是覺得，貝芙麗懷恨在心，所以故意偷走了領主的銀盒？",
  ui_story_5029_50290011_59_dialog_content = "我覺得她不至於做出這種事吧。",
  ui_story_5029_50290011_60_dialog_content = "我在白夜城留學的時候就發現了。",
  ui_story_5029_50290011_61_dialog_content = "愈是自詡高貴的貴族，背地裡愈是會做出一些匪夷所思的事。",
  ui_story_5029_50290011_62_dialog_content = "而貝芙麗就總是愛把「貴族」二字掛在嘴邊......",
  ui_story_5029_50290011_63_dialog_content = "唉，懷疑她也讓我覺得很痛苦，所以我打算找她問清楚。",
  ui_story_5029_50290011_64_option_content = "我和妳一起去",
  ui_story_5029_50290011_65_dialog_content = "就知道你會這麼說，走吧！",
  ui_story_5029_50290011_66_option_content = "祝妳好運",
  ui_story_5029_50290011_67_dialog_content = "這句話你還是送給別人吧。",
  ui_story_5029_50290011_68_option_content = "詢問菲雅",
  ui_story_5029_50290011_69_dialog_content = "菲雅，妳要去幹什麼？",
  ui_story_5029_50290011_70_dialog_content = "PlayerName，噓......小聲點。",
  ui_story_5029_50290011_71_dialog_content = "我發現了重大的線索，不要讓其他人知道！",
  ui_story_5029_50290011_72_dialog_content = "妳說的，不就是從沙發底下掏出來的<color=#793f76>碎片</color>嗎？",
  ui_story_5029_50290011_73_dialog_content = "別小瞧這些碎片！我問過那個叫贊恩的大叔了。",
  ui_story_5029_50290011_74_dialog_content = "按理來說，女僕清掃的範圍應該包括沙發底下才對。",
  ui_story_5029_50290011_75_dialog_content = "可能只是這個女僕打掃得不夠仔細？",
  ui_story_5029_50290011_76_dialog_content = "哼，如果只是這樣，菲雅才不會懷疑她呢。",
  ui_story_5029_50290011_77_dialog_content = "關鍵就在於......這個女僕的來歷很可疑！",
  ui_story_5029_50290011_78_dialog_content = "來歷可疑？我記得領主說這個女僕是影鎮商會推薦來的。",
  ui_story_5029_50290011_79_dialog_content = "在我心裡，影鎮的商會還是比較靠譜的。",
  ui_story_5029_50290011_80_dialog_content = "唉，PlayerName，你已經不小了！怎麼頭腦還是這麼簡單？",
  ui_story_5029_50290011_81_dialog_content = "還是讓神奇動物專家·影鎮居民·空裔主人·新晉偵探·菲雅告訴你吧。",
  ui_story_5029_50290011_82_dialog_content = "影鎮和好泊城都是靠貿易發展起來的城市。",
  ui_story_5029_50290011_83_dialog_content = "本來呢，影鎮是最大最繁華的自由貿易流通地。",
  ui_story_5029_50290011_84_dialog_content = "但據我觀察，好泊城最近發展的勢頭很快就要超過影鎮了！",
  ui_story_5029_50290011_85_dialog_content = "你覺得這種時候，影鎮商會為什麼要推薦女僕過來？",
  ui_story_5029_50290011_86_dialog_content = "為什麼？",
  ui_story_5029_50290011_87_dialog_content = "真相只有一個——女僕是為了盜取商業機密。",
  ui_story_5029_50290011_88_dialog_content = "而那個機密，一定就藏在銀盒子裡面！",
  ui_story_5029_50290011_89_dialog_content = "聽起來很不靠譜，但好像又找不到反駁的理由......",
  ui_story_5029_50290011_90_dialog_content = "那個叫真枝的女僕現在就在別的屋子裡工作，我這就去把她捉拿歸案！",
  ui_story_5029_50290011_91_dialog_content = "等等......那個女僕叫什麼？",
  ui_story_5029_50290011_92_dialog_content = "<color=#793f76>真枝</color>，怎麼了？",
  ui_story_5029_50290011_93_dialog_content = "嘶......好像有點耳熟？",
  ui_story_5029_50290011_94_option_content = "我和妳一起去吧",
  ui_story_5029_50290011_95_dialog_content = "噓，我們悄悄地，別讓那兩個人發現！",
  ui_story_5029_50290011_96_option_content = "總之，祝妳好運",
  ui_story_5029_50290011_97_dialog_content = "你最好不要把我發現的線索告訴別人。",
  ui_story_5029_50290011_98_dialog_content = "否則我會放出凱羅去找你的！",
  ui_story_5029_50290011_99_dialog_content = "囉！",
  ui_story_5029_50290011_100_option_content = "自己留下",
  ui_story_5029_50290011_101_dialog_content = "怎麼回事？",
  ui_story_5029_50290011_102_dialog_content = "為什麼只剩下我一個人了......",
  ui_story_5029_50290012_1_dialog_content = "狡木這傢伙，竟然有錢住這麼豪華的酒店嗎？",
  ui_story_5029_50290012_2_dialog_content = "現在我也開始有點懷疑他了......一定要找他問清楚！",
  ui_story_5029_50290012_3_dialog_content = "但是還有一個問題擺在我們面前。",
  ui_story_5029_50290012_4_dialog_content = "艾維斯讓我們祕密調查，所以我們不方便直接去詢問狡木的房間在哪裡。",
  ui_story_5029_50290012_5_dialog_content = "我們可以......裝作住店的客人。",
  ui_story_5029_50290012_6_dialog_content = "然後大大方方地走進去，就說是想要考察環境。",
  ui_story_5029_50290012_7_dialog_content = "進去之後就能慢慢找狡木了。",
  ui_story_5029_50290012_8_dialog_content = "辦法是個好辦法......但我不忍欺騙無辜之人。",
  ui_story_5029_50290012_9_dialog_content = "我們只是為了查案子，不會傷害任何人。",
  ui_story_5029_50290012_10_dialog_content = "我想這種情況下應該算是善意的謊言吧？",
  ui_story_5029_50290012_11_dialog_content = "不過這些話讓我來說就好了，卡蓮只要站在我的身邊就可以。",
  ui_story_5029_50290012_12_dialog_content = "不妥，我不想成為那種把責任都推到夥伴身上的人。我也會盡力而為。",
  ui_story_5029_50290012_13_dialog_content = "歡迎光臨，請問兩位有預約嗎？",
  ui_story_5029_50290012_14_dialog_content = "咳咳......我們沒有，沒有預約。",
  ui_story_5029_50290012_15_dialog_content = "（卡蓮真是不擅長說謊呢......）",
  ui_story_5029_50290012_16_dialog_content = "對，因為......",
  ui_story_5029_50290012_17_option_content = "我對環境很挑剔",
  ui_story_5029_50290012_18_dialog_content = "嗯？",
  ui_story_5029_50290012_19_option_content = "她對環境很挑剔",
  ui_story_5029_50290012_20_dialog_content = "嗯？",
  ui_story_5029_50290012_21_dialog_content = "所以想要先來考察一下再決定。",
  ui_story_5029_50290012_22_dialog_content = "好的，沒問題。先生您怎麼稱呼？",
  ui_story_5029_50290012_23_dialog_content = "我叫PlayerName。",
  ui_story_5029_50290012_24_dialog_content = "PlayerName先生，PlayerName太太，這邊請。",
  ui_story_5029_50290012_25_dialog_content = "我帶兩位去參觀本店最豪華的房間，保證兩位可以擁有最甜蜜的蜜月之旅。",
  ui_story_5029_50290012_26_dialog_content = "……？！",
  ui_story_5029_50290012_27_dialog_content = "那個，我們不是......",
  ui_story_5029_50290012_28_dialog_content = "原來兩位不是新婚嗎？",
  ui_story_5029_50290012_29_dialog_content = "是！",
  ui_story_5029_50290012_30_dialog_content = "不是！",
  ui_story_5029_50290012_31_dialog_content = "欸？兩位怎麼同時說出了不同的回答？",
  ui_story_5029_50290012_32_dialog_content = "（糟了，她已經開始懷疑我和卡蓮了！怎麼辦？）",
  ui_story_5029_50290012_33_dialog_content = "（可是剛才卡蓮居然斬釘截鐵地承認......）",
  ui_story_5029_50290012_34_dialog_content = "（啊啊啊，現在不是胡思亂想的時候，快想想該怎麼辦啊。）",
  ui_story_5029_50290012_35_dialog_content = "兩位客人，真的是來住店的嗎？",
  ui_story_5029_50290012_36_dialog_content = "當然是......",
  ui_story_5029_50290012_37_dialog_content = "抱歉，我們......我們剛訂婚。",
  ui_story_5029_50290012_38_dialog_content = "對我而言，訂婚已經算是新婚了。",
  ui_story_5029_50290012_39_dialog_content = "但是對於他來說，沒有舉辦過盛大的婚禮就還不能算是新婚。",
  ui_story_5029_50290012_40_dialog_content = "我懂，真是太懂了！誰不希望擁有一場獨一無二的婚禮呢～",
  ui_story_5029_50290012_41_dialog_content = "我沒有看錯吧？",
  ui_story_5029_50290012_42_dialog_content = "狡木......哈哈哈，好，好巧啊。",
  ui_story_5029_50290012_43_dialog_content = "老闆，真的是您？！您居然和白夜城的......唔，幹嘛捂我的嘴啊？",
  ui_story_5029_50290012_44_dialog_content = "啊，那個，我們正好遇到一個老朋友，一會我們再來參觀。",
  ui_story_5029_50290012_45_dialog_content = "隨時恭候您的光臨！",
  ui_story_5029_50290012_46_dialog_content = "您二位在做祕密調查？原來如此，所以剛才才會隱瞞身分啊。",
  ui_story_5029_50290012_47_dialog_content = "哈哈，要是空裔真的和白夜城聯姻，真不知道我們老大會做出什麼事來。",
  ui_story_5029_50290012_48_dialog_content = "畢竟我們老大可是天天盼著PlayerName加入我們紅油扳手呢。",
  ui_story_5029_50290012_49_dialog_content = "哦？他能做出什麼事來？",
  ui_story_5029_50290012_50_dialog_content = "咳咳，先別提這些了。狡木，你怎麼會出現在好泊城？",
  ui_story_5029_50290012_51_dialog_content = "我當然是來做生意的囉。",
  ui_story_5029_50290012_52_dialog_content = "又在做那種騙人的勾當嗎？",
  ui_story_5029_50290012_53_dialog_content = "冤枉啊，冤枉！",
  ui_story_5029_50290012_54_dialog_content = "就算是白夜城的公主，也不能血口噴人啊。",
  ui_story_5029_50290012_55_dialog_content = "我可是來做正經生意的，昨天還跟好泊城的領主進行了一番商業洽談呢。",
  ui_story_5029_50290012_56_dialog_content = "是嗎，我怎麼聽說昨天去見領主的商人是從雲島來的？",
  ui_story_5029_50290012_57_dialog_content = "狡木一郎，雲島出版行業世家，來艾斯特拉大陸尋找合作夥伴。",
  ui_story_5029_50290012_58_dialog_content = "致力於推廣遠東風格的傳記小說......",
  ui_story_5029_50290012_59_dialog_content = "你真的就是那個所謂的狡木一郎？",
  ui_story_5029_50290012_60_dialog_content = "老闆，這些都是必要的商業包裝。不這麼說，人家領主怎麼肯見我呢？",
  ui_story_5029_50290012_61_dialog_content = "又怎麼肯出錢、出地、出人力幫我印刷書籍呢？",
  ui_story_5029_50290012_62_dialog_content = "可我聽說，因為你的要求太過無理，領主並沒有答應與你合作。",
  ui_story_5029_50290012_63_dialog_content = "那只是暫時的，我相信他一定會回心轉意......",
  ui_story_5029_50290012_64_dialog_content = "嗯？不對啊，兩位怎麼一直在問我問題？",
  ui_story_5029_50290012_65_dialog_content = "你們該不會是來調查我的吧？",
  ui_story_5029_50290012_66_option_content = "並不是。",
  ui_story_5029_50290012_67_dialog_content = "別誤會，只是想關心一下老朋友嘛。",
  ui_story_5029_50290012_68_dialog_content = "老闆，原來你心裡還有我......太感動了！",
  ui_story_5029_50290012_69_dialog_content = "等這單生意做成了，一定請您二位吃頓好的！",
  ui_story_5029_50290012_70_dialog_content = "多謝你的好意，只是......",
  ui_story_5029_50290012_71_option_content = "沒錯",
  ui_story_5029_50290012_72_dialog_content = "噓......別忘了我們要祕密調查。",
  ui_story_5029_50290012_73_dialog_content = "咳咳，沒錯。",
  ui_story_5029_50290012_74_dialog_content = "我們只是想替領主考察某個滿嘴跑火車的商人究竟是什麼來歷罷了。",
  ui_story_5029_50290012_75_dialog_content = "聽完你的解釋，我大概明白了。",
  ui_story_5029_50290012_76_dialog_content = "領主的確不該推進這項合作。",
  ui_story_5029_50290012_77_dialog_content = "......沒錯，我確實是對自己的身世進行了適當的包裝。",
  ui_story_5029_50290012_78_dialog_content = "但我是誠心誠意來尋求合作機會的。",
  ui_story_5029_50290012_79_dialog_content = "《赤浪醒之助傳》這本書值得擁有更廣闊的市場。",
  ui_story_5029_50290012_80_dialog_content = "自從有了這個信念，我就覺得人生充滿了光明！",
  ui_story_5029_50290012_81_dialog_content = "我不惜千里迢迢來到這片文化之港......",
  ui_story_5029_50290012_81X1_dialog_content = "只求能找到可以大規模出版書籍的合作夥伴。",
  ui_story_5029_50290012_82_dialog_content = "我狡木早就不是你們所認識的那個黑心商人了。",
  ui_story_5029_50290012_83_dialog_content = "也請你們不要再戴著有色眼鏡看我。",
  ui_story_5029_50290012_84_dialog_content = "PlayerName，你怎麼看？",
  ui_story_5029_50290012_85_dialog_content = "狡木剛才說的話，聽起來不像是假的。",
  ui_story_5029_50290012_86_dialog_content = "如果狡木真的只是為了尋找合作機會，他應該沒有心思偷東西吧。",
  ui_story_5029_50290012_87_dialog_content = "狡木剛才的發言確實讓我覺得有些慚愧。",
  ui_story_5029_50290012_88_dialog_content = "我不該平白無故地懷疑他的動機。但......",
  ui_story_5029_50290012_89_dialog_content = "但我還是覺得，有些事我們沒有問清楚。",
  ui_story_5029_50290012_90_dialog_content = "比如為什麼艾維斯的那棟房子裡會有那麼多本《赤浪醒之助傳》。",
  ui_story_5029_50290012_91_dialog_content = "可能就是狡木昨天隨手留在房子裡的......？",
  ui_story_5029_50290012_92_dialog_content = "兩位也是領主家族的人嗎？給您問安了！",
  ui_story_5029_50290012_93_dialog_content = "妳是......？",
  ui_story_5029_50290012_94_dialog_content = "我是珊妮，來酒店修剪庭院雜草的園丁。昨天領主家的草坪就是我修剪的～",
  ui_story_5029_50290012_95_dialog_content = "妳為什麼覺得我們是領主家的人？",
  ui_story_5029_50290012_96_dialog_content = "啊，我說錯了嗎？對不起！",
  ui_story_5029_50290012_97_dialog_content = "因為剛才那位綠頭髮的哥哥是領主家的人，所以我就以為兩位也是......",
  ui_story_5029_50290012_98_dialog_content = "妳在領主家見過他？",
  ui_story_5029_50290012_99_dialog_content = "對呀！就是昨天晚上，我不會記錯的。",
  ui_story_5029_50290012_100_dialog_content = "我修剪完草坪躺在地上休息的時候，看見領主和他一起從房子裡走出來。",
  ui_story_5029_50290012_101_dialog_content = "沒過一會，他就好像忘了什麼似的，又回來打開門鎖走進去，過了一會才出來。",
  ui_story_5029_50290012_102_dialog_content = "……",
  ui_story_5029_50290012_103_dialog_content = "PlayerName，現在你還相信狡木嗎？",
  ui_story_5029_50290012_104_dialog_content = "真的是他......？",
  ui_story_5029_50290012_105_dialog_content = "我，我是不是說錯什麼話了？",
  ui_story_5029_50290012_106_dialog_content = "珊妮，妳幫了我們一個大忙。",
  ui_story_5029_50290012_107_dialog_content = "妳修剪的草坪也很漂亮。",
  ui_story_5029_50290012_108_dialog_content = "您已經成功辦理退房，期待您的下次光臨！",
  ui_story_5029_50290012_109_dialog_content = "如果想讓我下次光臨的話......不如買幾本《赤浪醒之助傳》看看呀？",
  ui_story_5029_50290012_110_dialog_content = "這……",
  ui_story_5029_50290012_111_dialog_content = "狡木。",
  ui_story_5029_50290012_112_dialog_content = "......兩位老闆啊，為什麼還不肯放過我？我正在做生意呢。",
  ui_story_5029_50290012_113_dialog_content = "我們有幾個問題，還是想再諮詢一下。",
  ui_story_5029_50290012_114_dialog_content = "昨天晚上你和領主見過面之後，是不是又私自闖進了領主的書房？",
  ui_story_5029_50290012_115_dialog_content = "喔～是不是領主讓你們來悄悄找我的？",
  ui_story_5029_50290012_116_dialog_content = "怎麼樣？領主看完了第一輯是不是不可自拔地愛上了這本書？",
  ui_story_5029_50290012_117_dialog_content = "他現在是不是急著找我給他第二輯？",
  ui_story_5029_50290012_118_dialog_content = "然後繼續洽談我們的出版大業？",
  ui_story_5029_50290012_119_dialog_content = "這麼說，你承認你曾經私闖領主書房？",
  ui_story_5029_50290012_120_dialog_content = "既然領主已經愛上了我這套書，我也就不瞞著各位了。",
  ui_story_5029_50290012_121_dialog_content = "昨天，領主沒有同意我提出的合作項目。",
  ui_story_5029_50290012_122_dialog_content = "我想這一定是因為領主沒有親自領略過我們這套書的精彩。",
  ui_story_5029_50290012_123_dialog_content = "只要他看過第一輯，就知道這套書有多麼值得投資！",
  ui_story_5029_50290012_124_dialog_content = "於是我就折返回去，故意把這套書的第一輯放在領主可以看到的任何地方。",
  ui_story_5029_50290012_125_dialog_content = "足足放了五本呢！不過捨不得孩子套不住狼。",
  ui_story_5029_50290012_126_dialog_content = "現在領主終於肯回心轉意了，哈哈哈哈。",
  ui_story_5029_50290012_127_dialog_content = "看來我搜查得還不夠徹底，竟然一共放了五本之多。",
  ui_story_5029_50290012_128_dialog_content = "你真的只是因為這個，才私闖領主書房的？",
  ui_story_5029_50290012_129_dialog_content = "對啊。領主在哪裡，我現在就給他送第二輯！",
  ui_story_5029_50290012_130_dialog_content = "他現在公務繁忙，如果你可以多住幾日，我會再替你安排與領主見面。",
  ui_story_5029_50290012_131_dialog_content = "唉，那花光積蓄的我只能換個便宜點的住處了。",
  ui_story_5029_50290012_132_dialog_content = "正經生意可真難做啊......",
  ui_story_5029_50290013_1_dialog_content = "還是來晚了......戲劇已經開始了。",
  ui_story_5029_50290013_2_dialog_content = "妳確定貝芙麗就在這家劇院裡面嗎？",
  ui_story_5029_50290013_3_dialog_content = "不會有錯。",
  ui_story_5029_50290013_4_dialog_content = "貝芙麗這次來好泊城最主要的目的，就是來看這場演出。",
  ui_story_5029_50290013_5_dialog_content = "今天那麼多演出，妳怎麼知道就是這場？",
  ui_story_5029_50290013_6_dialog_content = "贊恩也不知道貝芙麗要去看哪一場演出吧？",
  ui_story_5029_50290013_7_dialog_content = "但他透露過，貝芙麗這次是專門來看今天某場戲劇的首演！",
  ui_story_5029_50290013_8_dialog_content = "我看過了告示欄裡所有今天會上演的戲劇。",
  ui_story_5029_50290013_9_dialog_content = "只有三場在今天首演。",
  ui_story_5029_50290013_10_dialog_content = "其中一場是現代戲劇，不是貝芙麗喜歡的風格。",
  ui_story_5029_50290013_11_dialog_content = "還有一場在白夜城經常上演，不值得貝芙麗跑這麼遠來好泊城觀看。",
  ui_story_5029_50290013_12_dialog_content = "剩下的一場，就是這齣《羅米與朱麗》啦。",
  ui_story_5029_50290013_13_dialog_content = "薇絲，妳……",
  ui_story_5029_50290013_14_option_content = "就是貨真價實的偵探吧",
  ui_story_5029_50290013_15_dialog_content = "可以開偵探事務所的程度！",
  ui_story_5029_50290013_16_dialog_content = "嘿嘿……",
  ui_story_5029_50290013_17_option_content = "讓我覺得有點恐怖了",
  ui_story_5029_50290013_18_dialog_content = "好像什麼都逃不過妳的眼睛......",
  ui_story_5029_50290013_19_dialog_content = "咳咳……",
  ui_story_5029_50290013_20_dialog_content = "哪有這麼誇張？",
  ui_story_5029_50290013_21_dialog_content = "我們都認識這麼久了，你還不瞭解我嗎？",
  ui_story_5029_50290013_22_dialog_content = "只不過是行動力比較強而已啦。",
  ui_story_5029_50290013_23_dialog_content = "不過現在我們也不好直接衝進去找貝芙麗，只能等著戲劇散場了。",
  ui_story_5029_50290013_24_dialog_content = "現在已經開始暖場表演了，兩位觀眾還不進去嗎？",
  ui_story_5029_50290013_25_dialog_content = "謝謝提醒。不過我們其實沒有門票......",
  ui_story_5029_50290013_26_dialog_content = "欸？兩位不知道我們今天的戲劇活動嗎？",
  ui_story_5029_50290013_27_dialog_content = "《羅米與朱麗》首演大酬賓——雙人同行，門票半價！",
  ui_story_5029_50290013_28_dialog_content = "這種機會是非常難得的喔。",
  ui_story_5029_50290013_29_dialog_content = "雙人同行......還有這種好事？",
  ui_story_5029_50290013_30_dialog_content = "但是我看你們的門票已經售罄了。",
  ui_story_5029_50290013_31_dialog_content = "是的，不過剛剛有一對情侶鬧分手，所以正好空出兩張門票。",
  ui_story_5029_50290013_32_dialog_content = "鬧分手？",
  ui_story_5029_50290013_33_dialog_content = "雖然說鬧分手的情侶留下的門票可能不太吉利。",
  ui_story_5029_50290013_34_dialog_content = "但我看您二位感情這麼好，肯定不會輕易分手的！",
  ui_story_5029_50290013_35_dialog_content = "我們不是......",
  ui_story_5029_50290013_36_dialog_content = "所以如果您二位不介意的話，我們願意一折出售。",
  ui_story_5029_50290013_37_dialog_content = "咦？！",
  ui_story_5029_50290013_38_dialog_content = "薇絲，妳是不是有點想看？",
  ui_story_5029_50290013_39_dialog_content = "反正我們都要等到戲劇結束，不如就進去欣賞一下。",
  ui_story_5029_50290013_40_dialog_content = "謝謝PlayerName，我還害怕你會心疼門票錢呢。",
  ui_story_5029_50290013_41_dialog_content = "多謝兩位惠顧，祝兩位感情甜蜜，天長地久！",
  ui_story_5029_50290013_42_dialog_content = "……",
  ui_story_5029_50290013_43_dialog_content = "啊啊啊......嗯！",
  ui_story_5029_50290013_44_dialog_content = "（這位售票員一定是誤會我和薇絲的關係了......）",
  ui_story_5029_50290013_45_dialog_content = "（但是看在她這麼熱情的份上，我也不好意思糾正。）",
  ui_story_5029_50290013_46_dialog_content = "（薇絲......應該也是這麼想的吧？）",
  ui_story_5029_50290013_47_dialog_content = "我，我們快進去吧。",
  ui_story_5029_50290013_48_dialog_content = "嗯！",
  ui_story_5029_50290013_49_dialog_content = "<color=#828282>一段時間後</color>",
  ui_story_5029_50290013_50_dialog_content = "嗚嗚……",
  ui_story_5029_50290013_51_dialog_content = "真沒想到這齣戲劇這麼感人！",
  ui_story_5029_50290013_52_dialog_content = "前半部分，男主角與女主角在花田裡相遇的橋段太浪漫了！",
  ui_story_5029_50290013_53_dialog_content = "是啊。",
  ui_story_5029_50290013_54_dialog_content = "貝芙麗？！",
  ui_story_5029_50290013_55_dialog_content = "（光顧著看戲，差點忘了正事！）",
  ui_story_5029_50290013_56_dialog_content = "可惜戲劇的前半部分有多唯美，後半部分就有多悲慘。",
  ui_story_5029_50290013_57_dialog_content = "最後他們因為種種阻礙和誤會，相繼死在最初相遇的花田裡。",
  ui_story_5029_50290013_58_dialog_content = "那一幕前後呼應，達到了一種悲劇美學的巔峰。",
  ui_story_5029_50290013_59_dialog_content = "想不到悲劇也這麼好看嗚嗚嗚......",
  ui_story_5029_50290013_60_dialog_content = "我也沒想到，PlayerName和薇絲小姐也來看這場首演了。",
  ui_story_5029_50290013_61_dialog_content = "咳咳，可不是嘛......真巧！",
  ui_story_5029_50290013_62_dialog_content = "這齣戲劇雖然披著傳統戲劇的外衣，但故事內核卻十分先進呢。",
  ui_story_5029_50290013_63_dialog_content = "沒錯。這齣戲確實是近年來唯一的一部新作。",
  ui_story_5029_50290013_64_dialog_content = "不過男女主角的悲劇，說到底是因為身分懸殊造成的。",
  ui_story_5029_50290013_65_dialog_content = "如果兩個人能在相遇時，就問清楚彼此的身分，劃清界限......",
  ui_story_5029_50290013_65X1_dialog_content = "或許可以有另一種結局。",
  ui_story_5029_50290013_66_dialog_content = "我......我不這麼認為。",
  ui_story_5029_50290013_67_dialog_content = "男女主角的死亡，是為了給世人敲響警鐘。",
  ui_story_5029_50290013_68_dialog_content = "這齣戲劇其實是想鼓勵大家解放自我，衝破身分的牢籠，自由地去戀愛。",
  ui_story_5029_50290013_69_dialog_content = "哦？原來還有這一層深意......",
  ui_story_5029_50290013_70_dialog_content = "艾維斯竟然會同意讓這種類型的戲劇在好泊城上演。",
  ui_story_5029_50290013_71_dialog_content = "貝芙麗也認識這裡的領主嗎？",
  ui_story_5029_50290013_72_dialog_content = "對，我昨天還專程去拜訪過他，可惜我們最後不歡而散。",
  ui_story_5029_50290013_73_dialog_content = "為什麼？我看領主他人滿不錯啊。",
  ui_story_5029_50290013_74_dialog_content = "可惜，他的祖先是藉由歸順白夜城的方式成為貴族的。",
  ui_story_5029_50290013_75_dialog_content = "他雖然有白夜城貴族的稱號，但其實完全沒有貴族的血脈。",
  ui_story_5029_50290013_76_dialog_content = "我不小心脫口說出了這個事實，他便面露不悅。",
  ui_story_5029_50290013_77_dialog_content = "暗諷我伊斯庫家族的領地衰敗，比不過這偌大的好泊城。",
  ui_story_5029_50290013_78_dialog_content = "我也是一時氣不過，就轉身離開了。",
  ui_story_5029_50290013_79_dialog_content = "不過現在想想，我昨日也是有些失禮，做出了有違貴族風範的舉動。",
  ui_story_5029_50290013_80_dialog_content = "妳能這樣去批評自我，就已經邁出了很重要的一步。",
  ui_story_5029_50290013_81_dialog_content = "如果《羅米與朱麗》裡主角的親人也能這樣去思考，做出讓步的話......",
  ui_story_5029_50290013_82_dialog_content = "他們的悲劇就不會發生了。",
  ui_story_5029_50290013_83_dialog_content = "謝謝妳，薇絲小姐。",
  ui_story_5029_50290013_84_dialog_content = "看來我還需要再看一遍，才能體會到妳所說的那些深層的內涵。",
  ui_story_5029_50290013_85_dialog_content = "我這就去買下一場演出的門票。",
  ui_story_5029_50290013_86_dialog_content = "我現在覺得貝芙麗她滿誠實，想到什麼就說什麼......不像是會偷東西的人。",
  ui_story_5029_50290013_87_dialog_content = "是啊，一般那種傲慢的大貴族才不會反思自己的行為呢。",
  ui_story_5029_50290013_88_dialog_content = "只是她一直待在白夜城，被那種根深蒂固的貴族思想洗腦了。",
  ui_story_5029_50290013_89_dialog_content = "所以才會在乎「貴族的血脈」那種東西吧。",
  ui_story_5029_50290013_90_dialog_content = "相信她多看幾遍《羅米與朱麗》，一定能夠參透其中的道理。",
  ui_story_5029_50290013_90X1_dialog_content = "擺脫這種思維的影響！",
  ui_story_5029_50290013_91_dialog_content = "總覺得我們好像忘了問她什麼事......？",
  ui_story_5029_50290013_92_dialog_content = "打擾兩位了，請問您兩位是不是和領主大人認識啊？",
  ui_story_5029_50290013_93_dialog_content = "有什麼事嗎？",
  ui_story_5029_50290013_94_dialog_content = "我是汪達，如果方便的話，可以請兩位代我向領主大人道一聲謝嗎？",
  ui_story_5029_50290013_95_dialog_content = "昨天晚上，我本來想去應聘領主家的廚師。",
  ui_story_5029_50290013_96_dialog_content = "結果領主品嚐過我做的菜之後連連稱讚，卻沒有答應讓我留下。",
  ui_story_5029_50290013_97_dialog_content = "本來以為自己沒機會了，誰知道今天早上收到了一筆來自領主的「開店資金」。",
  ui_story_5029_50290013_98_dialog_content = "我這才發現，領主是希望我能在好泊城開一家餐廳，讓更多人品嚐到我的手藝......",
  ui_story_5029_50290013_99_dialog_content = "哎呀，這種事我以前想都不敢想。我想去道謝，結果被侍衛攔了下來。",
  ui_story_5029_50290013_100_dialog_content = "正巧在這裡遇見二位，所以就冒昧請二位幫我轉達一下謝意！",
  ui_story_5029_50290013_101_dialog_content = "領主真的好為大家著想啊......沒問題！我們會找機會幫妳轉達的。",
  ui_story_5029_50290013_102_dialog_content = "不過......妳是怎麼知道我們認識領主的？",
  ui_story_5029_50290013_103_dialog_content = "昨天晚上，我在領主家見過剛才和您二位說話的那位貴族大人。",
  ui_story_5029_50290013_104_dialog_content = "恰巧您幾位一直在說領主的事，所以我才來冒昧打擾。",
  ui_story_5029_50290013_105_dialog_content = "妳是說晚上見過剛才那位貴族大人？",
  ui_story_5029_50290013_106_dialog_content = "對呀，我在領主家院子裡等最後的錄用消息時......",
  ui_story_5029_50290013_107_dialog_content = "看見那位漂亮的貴族小姐從房子裡走出來......",
  ui_story_5029_50290013_107X1_dialog_content = "那房子裡有很多書架，應該是書房吧。",
  ui_story_5029_50290013_108_dialog_content = "總之......拜託二位了！等我的餐廳開業了，還請各位大人前來品嚐！",
  ui_story_5029_50290013_109_dialog_content = "這……",
  ui_story_5029_50290013_110_dialog_content = "我記得領主是在下午和貝芙麗見面的，她怎麼又在晚上出現了？",
  ui_story_5029_50290013_111_dialog_content = "她應該還在買票，我們再去問問！",
  ui_story_5029_50290013_112_dialog_content = "昨天晚上我去過哪裡？",
  ui_story_5029_50290013_113_dialog_content = "哼，你們就直說吧，是不是艾維斯讓你們過來調查我的？",
  ui_story_5029_50290013_114_option_content = "並不是。",
  ui_story_5029_50290013_115_dialog_content = "我們只是想問問妳都逛過什麼地方，想參考一下，哈哈哈。",
  ui_story_5029_50290013_116_dialog_content = "不是？",
  ui_story_5029_50290013_117_dialog_content = "我還以為他讓你們來調查我，昨晚為什麼要去他的書房。",
  ui_story_5029_50290013_118_option_content = "是的",
  ui_story_5029_50290013_119_dialog_content = "噓......我們要保密呀，PlayerName！",
  ui_story_5029_50290013_120_dialog_content = "別在那裡嘀嘀咕咕了，我都聽見了。",
  ui_story_5029_50290013_121_dialog_content = "你們是不是在調查，我昨天為什麼去了他的書房？",
  ui_story_5029_50290013_122_dialog_content = "什麼？！",
  ui_story_5029_50290013_123_dialog_content = "妳昨天晚上真的去過領主的書房？",
  ui_story_5029_50290013_124_dialog_content = "嗯。這件事對你們也沒什麼好隱瞞的。",
  ui_story_5029_50290013_125_dialog_content = "昨天我與他不歡而散後，發現自己的騎士徽章不見了。",
  ui_story_5029_50290013_126_dialog_content = "這枚徽章對我來說有很重要的意義......",
  ui_story_5029_50290013_127_dialog_content = "但我正和他生氣，不方便低頭請他幫我尋找。",
  ui_story_5029_50290013_128_dialog_content = "只好自己去他書房裡找了一圈，可惜還是沒找到。",
  ui_story_5029_50290013_129_dialog_content = "真的只是為了找徽章嗎？",
  ui_story_5029_50290013_130_dialog_content = "聽著，不管你們是不是艾維斯派來的。",
  ui_story_5029_50290013_130X1_dialog_content = "也不管他有沒有發現我去過他書房的事......",
  ui_story_5029_50290013_131_dialog_content = "都麻煩幫我轉達一下，我對他和他的書房沒興趣。",
  ui_story_5029_50290013_132_dialog_content = "我只想拿回我的騎士徽章。",
  ui_story_5029_50290014_1_dialog_content = "PlayerName，你往哪邊走呢？",
  ui_story_5029_50290014_2_dialog_content = "女僕的休息室在這邊！",
  ui_story_5029_50290014_3_dialog_content = "來了來了。",
  ui_story_5029_50290014_4_dialog_content = "是什麼人在這裡大呼小叫的？",
  ui_story_5029_50290014_5_dialog_content = "這裡是休息室，懂不懂規矩？",
  ui_story_5029_50290014_6_dialog_content = "咦，這個大嬸是誰？",
  ui_story_5029_50290014_7_dialog_content = "大嬸？？？",
  ui_story_5029_50290014_8_dialog_content = "妳這種不懂禮貌的野丫頭是從哪裡冒出來的？",
  ui_story_5029_50290014_9_dialog_content = "要叫我女僕長大人！",
  ui_story_5029_50290014_10_dialog_content = "哼，有什麼了不起的嘛。",
  ui_story_5029_50290014_11_dialog_content = "你……！",
  ui_story_5029_50290014_12_dialog_content = "女僕長大人請息怒。",
  ui_story_5029_50290014_13_option_content = "她還小不懂事",
  ui_story_5029_50290014_14_dialog_content = "女僕長大人別跟她一般見識。",
  ui_story_5029_50290014_15_dialog_content = "什麼啊？",
  ui_story_5029_50290014_16_option_content = "她是個好孩子",
  ui_story_5029_50290014_17_dialog_content = "只是有時候說話比較直接，還請多多包涵。",
  ui_story_5029_50290014_18_dialog_content = "哼。",
  ui_story_5029_50290014_19_dialog_content = "嗯，你們有事嗎？",
  ui_story_5029_50290014_20_dialog_content = "我們是聽贊恩說，來這裡可以找到......",
  ui_story_5029_50290014_21_dialog_content = "哦，原來是贊恩介紹過來的啊。",
  ui_story_5029_50290014_22_dialog_content = "贊恩可是最受領主大人信賴的人之一了。",
  ui_story_5029_50290014_23_dialog_content = "既然是他推薦過來的人，我還是給你們一個機會吧。",
  ui_story_5029_50290014_24_dialog_content = "介紹......推薦？",
  ui_story_5029_50290014_25_dialog_content = "什麼嘛......",
  ui_story_5029_50290014_26_dialog_content = "說吧，妳叫什麼名字？",
  ui_story_5029_50290014_27_dialog_content = "我叫PlayerName，我們是來......",
  ui_story_5029_50290014_28_dialog_content = "我沒有問她哥哥，這丫頭自己不會說話嗎？",
  ui_story_5029_50290014_29_dialog_content = "PlayerName才不是我哥哥呢。",
  ui_story_5029_50290014_29X1_dialog_content = "我沒有哥哥，只有爸爸、媽媽、師父和師姐！",
  ui_story_5029_50290014_30_dialog_content = "行了，我不關心這個。",
  ui_story_5029_50290014_31_dialog_content = "說說妳都會做點什麼吧？",
  ui_story_5029_50290014_32_dialog_content = "我，我會的事情可多了。",
  ui_story_5029_50290014_33_dialog_content = "我可是神奇動物專家，會幫助神奇動物成長、進化、繁育！",
  ui_story_5029_50290014_34_dialog_content = "飼養技術是門好手藝，可惜我們這裡不是農場。",
  ui_story_5029_50290014_35_dialog_content = "不過我倒是可以把妳安排到廚房。",
  ui_story_5029_50290014_36_dialog_content = "把我安排到廚房？",
  ui_story_5029_50290014_37_dialog_content = "怎麼？不滿意嗎？",
  ui_story_5029_50290014_38_dialog_content = "看妳的樣子就沒有當過女僕吧。",
  ui_story_5029_50290014_39_dialog_content = "能夠成為領主家的女僕，這個起點已經夠不錯的了。",
  ui_story_5029_50290014_40_dialog_content = "女僕長大人好像誤會了......",
  ui_story_5029_50290014_41_dialog_content = "女，女僕長大人。",
  ui_story_5029_50290014_42_dialog_content = "今天來應聘的女僕已經在外面了。",
  ui_story_5029_50290014_43_dialog_content = "在外面？那我面前的這兩位是......？",
  ui_story_5029_50290014_44_dialog_content = "PlayerName先生？",
  ui_story_5029_50290014_45_dialog_content = "是妳？妳怎麼會在這裡？",
  ui_story_5029_50290014_46_dialog_content = "這個......說來話長。您怎麼也在好泊城呀？",
  ui_story_5029_50290014_47_dialog_content = "我和PlayerName來找一個叫真枝的女僕，妳認識嗎？",
  ui_story_5029_50290014_48_dialog_content = "這......這個......",
  ui_story_5029_50290014_49_dialog_content = "原來是贊恩讓兩位來找真枝的？",
  ui_story_5029_50290014_50_dialog_content = "剛才我誤以為兩位是來應聘的，實在是抱歉！",
  ui_story_5029_50290014_51_dialog_content = "真枝。",
  ui_story_5029_50290014_52_dialog_content = "在，我在！",
  ui_story_5029_50290014_53_dialog_content = "好好招待兩位客人，我先去面試新來的女僕了。",
  ui_story_5029_50290014_54_dialog_content = "是！",
  ui_story_5029_50290014_55_dialog_content = "妳就是真枝？！",
  ui_story_5029_50290014_56_dialog_content = "從實招來！妳是不是做了什麼見不得人的事情？",
  ui_story_5029_50290014_57_dialog_content = "我，我我我我......",
  ui_story_5029_50290014_58_dialog_content = "早苗......我怎麼記得真枝是妳「姐姐」的名字？",
  ui_story_5029_50290014_59_dialog_content = "原來名字也是假冒的？",
  ui_story_5029_50290014_60_dialog_content = "菲雅果然沒有看錯，妳真的非常可疑！",
  ui_story_5029_50290014_61_dialog_content = "菲雅，我認識的早苗不是妳想像中的可疑角色。",
  ui_story_5029_50290014_62_dialog_content = "讓我們先聽她把話說完，好嗎？",
  ui_story_5029_50290014_63_dialog_content = "謝謝，謝謝PlayerName先生......",
  ui_story_5029_50290014_64_dialog_content = "妳怎麼沒有在影鎮跟著妮娜，反而到好泊城來了？",
  ui_story_5029_50290014_65_dialog_content = "我......我被安德森家開除了。",
  ui_story_5029_50290014_66_dialog_content = "所以就拜託商會把我介紹到好泊城來當女僕了。",
  ui_story_5029_50290014_67_dialog_content = "......妮娜竟然捨得讓妳離開？",
  ui_story_5029_50290014_68_dialog_content = "妮娜小姐她......她和我本來就身分不同。",
  ui_story_5029_50290014_69_dialog_content = "我只是一個女僕而已，她沒有什麼捨不得的。",
  ui_story_5029_50290014_70_dialog_content = "我也早就開始新的生活了，所以......",
  ui_story_5029_50290014_71_dialog_content = "那也解釋不通啊，妳為什麼要換個名字？",
  ui_story_5029_50290014_72_dialog_content = "欸......那是因為，我不想被人知道自己曾經被開除過。",
  ui_story_5029_50290014_73_dialog_content = "啊啊啊啊對了，我還要去打掃庭院！",
  ui_story_5029_50290014_74_dialog_content = "快要來不及了，再不去我又要被開除了。",
  ui_story_5029_50290014_75_dialog_content = "凱羅，不要讓這個綠頭髮的女孩逃跑。",
  ui_story_5029_50290014_76_dialog_content = "囉！",
  ui_story_5029_50290014_77_dialog_content = "啊啊啊真枝姐姐......",
  ui_story_5029_50290014_78_dialog_content = "哪來的野狗，滾一邊去！",
  ui_story_5029_50290014_79_dialog_content = "囉......",
  ui_story_5029_50290014_80_dialog_content = "早苗要去工作了，你們幾個看不見嗎？",
  ui_story_5029_50290014_81_dialog_content = "她要是丟了工作，你能負得起這個責任嗎？",
  ui_story_5029_50290014_82_dialog_content = "早苗，我們走，別管他們。",
  ui_story_5029_50290014_83_dialog_content = "囉......",
  ui_story_5029_50290014_84_dialog_content = "凱羅，好啦好啦。不用害怕啦，她已經走了。",
  ui_story_5029_50290014_85_dialog_content = "囉！",
  ui_story_5029_50290014_86_dialog_content = "PlayerName，這就是你說的值得相信的老朋友嗎？",
  ui_story_5029_50290014_87_dialog_content = "剛才她很明顯就是在轉移話題吧！",
  ui_story_5029_50290014_88_dialog_content = "不得不說......她剛才的樣子確實很可疑。",
  ui_story_5029_50290014_89_dialog_content = "我認識的早苗以前不會這樣對人有所隱瞞。",
  ui_story_5029_50290014_90_dialog_content = "幾位貴客是在調查那個女僕吧？我也一直覺得她非常可疑。",
  ui_story_5029_50290014_91_dialog_content = "這位拄著柺杖的大叔又是誰？",
  ui_story_5029_50290014_92_dialog_content = "抱歉，忘了介紹自己。",
  ui_story_5029_50290014_93_dialog_content = "我是庫克。從我爺爺輩起，我家就開始為領主一族做事了。",
  ui_story_5029_50290014_94_dialog_content = "去年我腿腳負傷，就幫著女僕長做些雜務。所以和這些女僕都有些交集。",
  ui_story_5029_50290014_95_dialog_content = "但我真心覺得這個真枝，很不簡單。",
  ui_story_5029_50290014_96_dialog_content = "為什麼會這麼覺得呢？",
  ui_story_5029_50290014_97_dialog_content = "我聽說她是影鎮商會介紹來的，領主不好推辭就把她留了下來。",
  ui_story_5029_50290014_98_dialog_content = "結果這個女僕來了之後盡是添亂，摔盤子砸碗的，已經被扣了好幾個月的工錢了。",
  ui_story_5029_50290014_99_dialog_content = "但她似乎毫不在意這些，還總是找機會去領主身邊轉悠。",
  ui_story_5029_50290014_100_dialog_content = "所以我總覺得她別有用心。",
  ui_story_5029_50290014_101_dialog_content = "說起來，我昨天晚上還看見她悄悄去了領主的書房。",
  ui_story_5029_50290014_102_dialog_content = "昨天晚上？！",
  ui_story_5029_50290014_103_dialog_content = "她應該中午就已經打掃完那裡的衛生了吧？",
  ui_story_5029_50290014_104_dialog_content = "我也覺得奇怪啊......可人家是影鎮商會介紹來的，我也不敢多問。",
  ui_story_5029_50290014_105_dialog_content = "但我還是很害怕她會做出什麼對領主不利的事情。",
  ui_story_5029_50290014_106_dialog_content = "......這件事，還請兩位多費心了。",
  ui_story_5029_50290014_107_dialog_content = "PlayerName，這次可不能放過你的老朋友了吧？",
  ui_story_5029_50290014_108_dialog_content = "先找她問問再說。",
  ui_story_5029_50290014_109_dialog_content = "欸？......是領主大人讓您來調查我的嗎？",
  ui_story_5029_50290014_110_option_content = "並不是。",
  ui_story_5029_50290014_111_dialog_content = "這件事領主大人不知道。",
  ui_story_5029_50290014_112_dialog_content = "我們只是聽庫克說......",
  ui_story_5029_50290014_113_option_content = "是的",
  ui_story_5029_50290014_114_dialog_content = "（糟了，忘記我們要保密調查了！）",
  ui_story_5029_50290014_115_dialog_content = "咳咳，總之我們聽庫克說......",
  ui_story_5029_50290014_116_dialog_content = "妳昨晚未經允許去過領主的書房。",
  ui_story_5029_50290014_117_dialog_content = "庫克先生他竟然告訴你們了？",
  ui_story_5029_50290014_118_dialog_content = "他，他明明說過，不會告訴別人的......",
  ui_story_5029_50290014_119_dialog_content = "原來妳還想收買庫克大叔？",
  ui_story_5029_50290014_120_dialog_content = "不，不是的......我沒有收買任何人！",
  ui_story_5029_50290014_121_dialog_content = "妳昨天晚上到底為什麼趁沒人的時候去領主的書房？",
  ui_story_5029_50290014_122_dialog_content = "我......我中午打掃衛生的時候，不小心打碎了大廳桌子上的小花瓶。",
  ui_story_5029_50290014_123_dialog_content = "那時候贊恩先生來催我，說客人就快來了，讓我趕快離開。",
  ui_story_5029_50290014_124_dialog_content = "我怕打碎花瓶的事被人發現後自己會被開除。",
  ui_story_5029_50290014_125_dialog_content = "所以就把花瓶的碎渣藏在了沙發下面......想著晚上沒人的時候再去撿回來。",
  ui_story_5029_50290014_126_dialog_content = "哈，沒想到吧。那些碎渣還是被菲雅發現了！",
  ui_story_5029_50290014_127_dialog_content = "看來我打掃得還是不夠仔細嗚嗚嗚......",
  ui_story_5029_50290014_128_dialog_content = "可是大廳桌子上的小花瓶還在啊。",
  ui_story_5029_50290014_129_dialog_content = "那個，那個是因為我買了一個一模一樣的。",
  ui_story_5029_50290014_130_dialog_content = "我聽說妳未來幾個月的工錢都快被扣光了，怎麼有錢買這麼高級的花瓶？",
  ui_story_5029_50290014_131_dialog_content = "......嗚啊啊啊啊！",
  ui_story_5029_50290014_132_dialog_content = "這錢，是從哪裡來的？",
  ui_story_5029_50290014_133_dialog_content = "是......是妮娜小姐給我的。",
  ui_story_5029_50290014_134_dialog_content = "PlayerName先生，早苗也覺得自己做不來這件事。",
  ui_story_5029_50290014_135_dialog_content = "可是妮娜小姐派早苗過來，早苗不想讓妮娜小姐傷心......",
  ui_story_5029_50290014_136_dialog_content = "所以，妳並沒有被妮娜開除？",
  ui_story_5029_50290014_137_dialog_content = "唔唔......嗯。",
  ui_story_5029_50290014_138_dialog_content = "妮娜派妳來是為了偷東西？",
  ui_story_5029_50290014_139_dialog_content = "偷東西......偷，偷什麼東西？",
  ui_story_5029_50290014_140_dialog_content = "我只是來替妮娜小姐偷偷調查領主的為人和喜好......",
  ui_story_5029_50290014_141_dialog_content = "好讓妮娜小姐能知己知彼，和好泊城做貿易談判什麼的。",
  ui_story_5029_50290014_142_dialog_content = "我就知道自己遲早會露陷，現在果然還是被PlayerName先生發現了。",
  ui_story_5029_50290014_143_dialog_content = "這下該怎麼和妮娜小姐交代啊......嗚嗚嗚。",
  ui_story_5029_50290015_1_dialog_content = "今天大家看起來都好難接近的樣子。",
  ui_story_5029_50290015_2_dialog_content = "只能任由她們競爭出個高地了嗎？",
  ui_story_5029_50290015_3_dialog_content = "不對啊，我也有一個腦袋兩條腿，我也可以自己去搜查。",
  ui_story_5029_50290015_4_dialog_content = "如果最後我比她們更快找出犯人，也許她們就不會彼此較勁了吧？",
  ui_story_5029_50290015_5_dialog_content = "嗯！說幹就幹！",
  ui_story_5029_50290015_6_dialog_content = "這屋子裡已經搜得差不多了......",
  ui_story_5029_50290015_7_dialog_content = "屋子外面會不會有什麼線索呢？",
  ui_story_5029_50290015_8_dialog_content = "領主這棟房子可真不錯。",
  ui_story_5029_50290015_9_dialog_content = "一面可以眺望大海，另一面可以看見森林。",
  ui_story_5029_50290015_10_dialog_content = "雖然贊恩說，這片森林只是領主家的後花園而已......",
  ui_story_5029_50290015_11_dialog_content = "<color=#828282>窸窸窣窣......</color>",
  ui_story_5029_50290015_12_dialog_content = "嗯？",
  ui_story_5029_50290015_13_dialog_content = "剛才是有誰經過了嗎......",
  ui_story_5029_50290015_14_dialog_content = "果然有人！看來不是錯覺。",
  ui_story_5029_50290015_15_dialog_content = "喂！你在這裡幹什麼呢？",
  ui_story_5029_50290015_16_dialog_content = "你，你為什麼不說話？",
  ui_story_5029_50290015_17_dialog_content = "你想幹什麼？！",
  ui_story_5029_50290015_18_dialog_content = "有話好好說，舉著鐵鍬多嚇人啊......",
  ui_story_5029_50290015_19_dialog_content = "<color=#828282>咚！</color>",
  ui_story_5029_50290015_20_dialog_content = "妳……",
  ui_story_5029_50290015_21_dialog_content = "你究竟......",
  ui_story_5029_50290015_22_dialog_content = "<color=#828282>叮鈴——</color>",
  ui_story_5029_50290015_23_dialog_content = "歡迎回來，我親愛的客人。",
  ui_story_5029_50290015_24_dialog_content = "很抱歉我們的占卜被打斷......",
  ui_story_5029_50290015_25_dialog_content = "不穩妥的選擇，只能讓您迎來這樣尷尬的結局。",
  ui_story_5029_50290015_26_dialog_content = "不如讓我們換個角度想想。",
  ui_story_5029_50290015_27_dialog_content = "剛剛這只是一個......不那麼美好的夢境。",
  ui_story_5029_50290015_28_dialog_content = "完全不會影響到您在現實世界中的安危。",
  ui_story_5029_50290015_29_dialog_content = "怎麼？這樣想也無法消除您臉上遺憾的神色嗎？",
  ui_story_5029_50290015_30_dialog_content = "好消息是......我們還有時間。",
  ui_story_5029_50290015_31_dialog_content = "您大可以重新來過。",
  ui_story_5029_50290015_32_dialog_content = "這就是夢境的好處，不是嗎？",
  ui_story_5029_50290016_1_dialog_content = "看來狡木真的洗心革面，開始做正經生意了。",
  ui_story_5029_50290016_2_dialog_content = "只是沒想到他連住宿的錢都沒有了。",
  ui_story_5029_50290016_3_dialog_content = "我看他只是住不起豪華酒店，普通旅店還是住得起的。",
  ui_story_5029_50290016_4_dialog_content = "既然這樣，妳為什麼後來又給他介紹了一個免費的住處？",
  ui_story_5029_50290016_5_dialog_content = "我告訴他的住處是領主的一處私人財產，附近有私兵把守。",
  ui_story_5029_50290016_6_dialog_content = "如果狡木有什麼風吹草動，我們可以第一時間知道。",
  ui_story_5029_50290016_7_dialog_content = "原來妳還是沒有完全相信狡木的說法？",
  ui_story_5029_50290016_8_dialog_content = "看他的樣子，應該是真的不知道銀盒的事情。",
  ui_story_5029_50290016_9_dialog_content = "嗯，我也覺得。他既然敢留下來，就說明他沒有做什麼別的虧心事。",
  ui_story_5029_50290016_10_dialog_content = "我這麼做只是以防萬一罷了。",
  ui_story_5029_50290016_11_dialog_content = "而且，我也答應過狡木，會安排他與領主見面。",
  ui_story_5029_50290016_12_dialog_content = "我以為妳只是為了先穩住狡木，所以才隨口那麼一說的。",
  ui_story_5029_50290016_13_dialog_content = "是這樣沒錯，但是已經說出口的話，我還是希望可以做到。",
  ui_story_5029_50290016_14_dialog_content = "否則我會覺得對不起自己作為騎士的榮耀，也對不起人們對我的尊重和信任。",
  ui_story_5029_50290016_15_dialog_content = "（那剛才在酒店說的訂婚的事......也是嗎？）",
  ui_story_5029_50290016_16_dialog_content = "哦吼～我全都聽見了！",
  ui_story_5029_50290016_17_dialog_content = "啊？我剛才把想法說出口了嗎？",
  ui_story_5029_50290016_18_dialog_content = "你們已經排除掉狡木了嗎？",
  ui_story_5029_50290016_19_dialog_content = "（聽見的原來是這個啊。）",
  ui_story_5029_50290016_20_dialog_content = "薇絲、菲雅，妳們什麼時候......",
  ui_story_5029_50290016_21_dialog_content = "不行，我要抓緊時間繼續調查了。",
  ui_story_5029_50290016_22_dialog_content = "這麼說的話，菲雅追查的嫌疑人也許是真的犯人？",
  ui_story_5029_50290016_23_dialog_content = "凱羅，我們走！",
  ui_story_5029_50290016_24_dialog_content = "囉！",
  ui_story_5029_50290016_25_dialog_content = "妳們兩個，倒是把話說完啊......",
  ui_story_5029_50290016_26_dialog_content = "呼呼呼......這兩個人跑到哪裡去了？",
  ui_story_5029_50290016_27_dialog_content = "PlayerName，別追她們了。",
  ui_story_5029_50290016_28_dialog_content = "我們還是回去重新搜查一下房間，看看有沒有別的線索吧。",
  ui_story_5029_50290016_29_dialog_content = "好吧……",
  ui_story_5029_50290016_30_dialog_content = "唉，真希望我下一秒就能抓住犯人。",
  ui_story_5029_50290016_31_dialog_content = "<color=#828282>咚！</color>",
  ui_story_5029_50290016_32_dialog_content = "喂，你這傢伙不長眼睛嗎？！",
  ui_story_5029_50290016_33_dialog_content = "……",
  ui_story_5029_50290016_34_dialog_content = "別走啊你，撞翻我的東西連一句抱歉都不會說嗎？",
  ui_story_5029_50290016_35_dialog_content = "呿，倒楣！",
  ui_story_5029_50290016_36_dialog_content = "那個穿長袍的人好奇怪，這麼熱的天氣把自己捂得那麼嚴實。",
  ui_story_5029_50290016_37_dialog_content = "這種把臉擋住、行色匆忙的人，十有八九是犯了什麼事。",
  ui_story_5029_50290016_38_dialog_content = "犯了事......？",
  ui_story_5029_50290016_39_dialog_content = "我剛才瞥見，那個人在長袍之下好像抱著一個很大的東西......",
  ui_story_5029_50290016_40_dialog_content = "……",
  ui_story_5029_50290016_41_dialog_content = "銀盒？！",
  ui_story_5029_50290016_42_dialog_content = "前面那個人，站住！",
  ui_story_5029_50290016_43_dialog_content = "不好，他聽見我們的聲音拔腿就跑了！",
  ui_story_5029_50290016_44_dialog_content = "果然有問題，我們追！",
  ui_story_5029_50290017_1_dialog_content = "要不是我們去問貝芙麗，真不知道她要把丟了徽章這件事在心裡憋多久。",
  ui_story_5029_50290017_2_dialog_content = "貝芙麗的說法和領主的說法大致相同，只不過......",
  ui_story_5029_50290017_3_dialog_content = "我記得領主說他當時只是提出可以幫忙發展一下貝芙麗的家族領地。",
  ui_story_5029_50290017_4_dialog_content = "貝芙麗一定是誤解了領主的意思，才會那麼生氣。",
  ui_story_5029_50290017_5_dialog_content = "有時候真的覺得白夜城的貴族和我不是同樣物種......",
  ui_story_5029_50290017_6_dialog_content = "明明說清楚、握個手就能解決的事情，非要搞得那麼複雜。",
  ui_story_5029_50290017_7_dialog_content = "可我不明白，我們不是知道貝芙麗的徽章在哪裡嗎？",
  ui_story_5029_50290017_8_dialog_content = "妳為什麼不讓我告訴她呢？",
  ui_story_5029_50290017_9_dialog_content = "你想想，如果我們告訴貝芙麗徽章就在領主的咖啡廳......",
  ui_story_5029_50290017_10_dialog_content = "她是不是找到之後就會轉身就走？",
  ui_story_5029_50290017_11_dialog_content = "嗯，很有可能。",
  ui_story_5029_50290017_12_dialog_content = "這樣貝芙麗可能永遠都不會再跟領主有任何交流了。",
  ui_story_5029_50290017_13_dialog_content = "妳的意思是......我們可以故意讓領主意識到咖啡廳裡有一枚貝芙麗遺失的徽章。",
  ui_story_5029_50290017_14_dialog_content = "然後讓領主去還給貝芙麗？",
  ui_story_5029_50290017_15_dialog_content = "這樣一來，兩個人都有了一個台階可下，應該會握手言和了吧？",
  ui_story_5029_50290017_16_dialog_content = "薇絲，妳真的好為大家操心啊......",
  ui_story_5029_50290017_17_dialog_content = "唉，我也知道自己有點多管閒事。",
  ui_story_5029_50290017_18_dialog_content = "貝芙麗和領主雖然都有點貴族架子，但是他們人還是挺好的。",
  ui_story_5029_50290017_19_dialog_content = "既然我知道了他們之間的誤會，就沒有辦法坐視不理。",
  ui_story_5029_50290017_20_dialog_content = "我真的不想看到身邊有《羅米與朱麗》那樣的悲劇發生。",
  ui_story_5029_50290017_21_dialog_content = "看樣子妳現在一點都不懷疑貝芙麗了？",
  ui_story_5029_50290017_22_dialog_content = "嗯！",
  ui_story_5029_50290017_23_dialog_content = "不過......我們又要重新開始搜查線索了。",
  ui_story_5029_50290017_24_dialog_content = "哦吼，菲雅聽到了什麼好消息？",
  ui_story_5029_50290017_25_dialog_content = "你們已經洗清貝芙麗的嫌疑了嗎？",
  ui_story_5029_50290017_26_dialog_content = "卡蓮、菲雅？妳們什麼時候......",
  ui_story_5029_50290017_27_dialog_content = "多有打擾，我繼續調查去了。",
  ui_story_5029_50290017_28_dialog_content = "看來菲雅追查的嫌疑人很可能就是真的犯人啊！",
  ui_story_5029_50290017_29_dialog_content = "凱羅，我們走！",
  ui_story_5029_50290017_30_dialog_content = "妳們兩個，有什麼進展嗎......別跑啊！",
  ui_story_5029_50290017_31_dialog_content = "呼呼呼......這兩個人跑到哪裡去了？",
  ui_story_5029_50290017_32_dialog_content = "PlayerName，不然就算了吧。",
  ui_story_5029_50290017_33_dialog_content = "我們還是回去再調查一下其他疑點好了。",
  ui_story_5029_50290017_34_dialog_content = "我也是這麼想的，可是......",
  ui_story_5029_50290017_35_dialog_content = "妳知道我們回去的路嗎？",
  ui_story_5029_50290017_36_dialog_content = "欸？",
  ui_story_5029_50290017_37_dialog_content = "我剛才只顧著找菲雅和卡蓮，沒顧上看路。",
  ui_story_5029_50290017_38_dialog_content = "回過神來才發現走到這條偏僻的小路上了......",
  ui_story_5029_50290017_39_dialog_content = "沒關係，那邊有個路人。我們去問問他好了～",
  ui_story_5029_50290017_40_dialog_content = "打擾了，請問......",
  ui_story_5029_50290017_41_dialog_content = "……",
  ui_story_5029_50290017_42_dialog_content = "請等等，我們沒有惡意的，只是想問問怎麼去領主的宅邸而已！",
  ui_story_5029_50290017_43_dialog_content = "……！",
  ui_story_5029_50290017_44_dialog_content = "這個路人好奇怪啊，為什麼不肯聽我們講完話就跑掉了。",
  ui_story_5029_50290017_45_dialog_content = "而且這麼熱的天，他穿著長袍，還把臉擋住......不覺得熱嗎？",
  ui_story_5029_50290017_46_dialog_content = "如果我沒有看錯的話......",
  ui_story_5029_50290017_47_dialog_content = "那個人在長袍之下好像抱著一個閃著銀光的東西。",
  ui_story_5029_50290017_48_dialog_content = "……",
  ui_story_5029_50290017_49_dialog_content = "銀盒？！",
  ui_story_5029_50290017_50_dialog_content = "走，我們快追上去！",
  ui_story_5029_50290018_1_dialog_content = "PlayerName，你真的不打算告訴領主這件事嗎？",
  ui_story_5029_50290018_2_dialog_content = "早苗已經答應我這幾天會主動辭職。",
  ui_story_5029_50290018_3_dialog_content = "就讓妮娜和領主進行貿易談判的時候，主動向領主道歉好了。",
  ui_story_5029_50290018_4_dialog_content = "妮娜應該是因為太重視和領主的談判......",
  ui_story_5029_50290018_5_dialog_content = "才會想方設法瞭解領主的喜好，以便提前做好準備吧。",
  ui_story_5029_50290018_6_dialog_content = "安德森家的妮娜小姐明明在影鎮有很多店舖，她還不滿足嗎？",
  ui_story_5029_50290018_7_dialog_content = "菲雅不也是嗎？",
  ui_story_5029_50290018_8_dialog_content = "明明已經是很厲害的神奇動物專家，還是在不停努力。",
  ui_story_5029_50290018_9_dialog_content = "哼，那是當然啦。",
  ui_story_5029_50290018_10_dialog_content = "菲雅要成為比師父還厲害的神奇動物專家，寫出最厲害的神奇動物著作！",
  ui_story_5029_50290018_11_dialog_content = "......這麼說的話，我好像有點明白妮娜小姐的想法了。",
  ui_story_5029_50290018_12_dialog_content = "話說回來，你真的能完全排除掉早苗的嫌疑嗎？",
  ui_story_5029_50290018_13_dialog_content = "也許是她自己鬼迷心竅，偷走了領主的寶貝呢？",
  ui_story_5029_50290018_14_dialog_content = "以我對早苗的瞭解，她應該沒有那種心思和......膽子。",
  ui_story_5029_50290018_15_dialog_content = "但是我們也得到了一個很重要的線索，不是嗎？",
  ui_story_5029_50290018_16_dialog_content = "嗯，如果她真的值得相信的話......",
  ui_story_5029_50290018_17_dialog_content = "她進書房之前，門鎖就已經被打開了。",
  ui_story_5029_50290018_18_dialog_content = "原來這位商會推薦過來的女僕就是那位妮娜小姐身邊的早苗？",
  ui_story_5029_50290018_19_dialog_content = "這麼說，你們已經排除掉早苗的嫌疑了？",
  ui_story_5029_50290018_20_dialog_content = "啊哇哇哇哇！",
  ui_story_5029_50290018_21_dialog_content = "怎麼可以偷聽我們找到的重要線索呢？",
  ui_story_5029_50290018_22_dialog_content = "抱歉，我只是想要回來再找些線索，偶然聽到了你們的對話。",
  ui_story_5029_50290018_23_dialog_content = "既然是祕密對話，我就不打擾了。",
  ui_story_5029_50290018_24_dialog_content = "不行，我也要抓緊時間繼續調查了。",
  ui_story_5029_50290018_25_dialog_content = "妳們兩個，有什麼進展嗎......",
  ui_story_5029_50290018_26_dialog_content = "欸，別跑啊！",
  ui_story_5029_50290018_27_dialog_content = "哎呀大意了，菲雅的賞金要被人搶先了！",
  ui_story_5029_50290018_28_dialog_content = "凱羅，我們快跟上！",
  ui_story_5029_50290018_29_dialog_content = "囉囉囉......",
  ui_story_5029_50290018_30_dialog_content = "嗯？凱羅？你在窗邊看什麼呢，快過來啊。",
  ui_story_5029_50290018_31_dialog_content = "外面只有一堆樹而已啦......",
  ui_story_5029_50290018_32_dialog_content = "領主的這片後花園倒是很幽靜呢。",
  ui_story_5029_50290018_33_dialog_content = "欸？樹叢裡還有......一個人？",
  ui_story_5029_50290018_34_dialog_content = "PlayerName，你快看外面那個人好奇怪啊！",
  ui_story_5029_50290018_35_dialog_content = "這麼熱的天氣，把自己捂得嚴嚴實實的。",
  ui_story_5029_50290018_36_dialog_content = "要不是我眼神好，還以為那是隻暗鬼，或者是什麼沒見過的神奇動物呢。",
  ui_story_5029_50290018_37_dialog_content = "那個人在幹什麼？",
  ui_story_5029_50290018_38_dialog_content = "好像是在把什麼東西放進懷裡？",
  ui_story_5029_50290018_39_dialog_content = "那個東西滿大，還泛著銀光呢。",
  ui_story_5029_50290018_40_dialog_content = "……",
  ui_story_5029_50290018_41_dialog_content = "銀盒？！",
  ui_story_5029_50290018_42_dialog_content = "不會吧？犯人竟然就在領主的後花園？",
  ui_story_5029_50290018_43_dialog_content = "……",
  ui_story_5029_50290018_44_dialog_content = "糟了，他好像發現我們了。",
  ui_story_5029_50290018_45_dialog_content = "凱羅，我們快追！",
  ui_story_5029_50290018_46_dialog_content = "囉！",
  ui_story_5029_50290019_1_dialog_content = "站住！",
  ui_story_5029_50290019_2_dialog_content = "……",
  ui_story_5029_50290019_3_dialog_content = "聽著，現在你還有自首的機會。",
  ui_story_5029_50290019_4_dialog_content = "如果讓我抓住你，性質就完全不一樣了！",
  ui_story_5029_50290019_5_dialog_content = "呼哧......呼哧......",
  ui_story_5029_50290019_6_dialog_content = "這個人完全不聽我們的勸告，往山上跑得更快了。",
  ui_story_5029_50290019_7_dialog_content = "我本來不想讓我的長槍指向任何一個民眾......",
  ui_story_5029_50290019_8_dialog_content = "既然對方是不聽勸告的宵小之徒，就別怪我不客氣了！",
  ui_story_5029_50290019_9_dialog_content = "卡蓮，我們出來的時候好像沒有帶武器。",
  ui_story_5029_50290019_10_dialog_content = "噓，兵不厭詐。",
  ui_story_5029_50290019_11_dialog_content = "（欸，明明之前在酒店的時候那麼不擅長說謊......）",
  ui_story_5029_50290019_12_dialog_content = "（沒想到在戰鬥的時候，她竟然深諳「說謊」的兵法？）",
  ui_story_5029_50290019_13_dialog_content = "（嗯？什麼東西朝卡蓮飛過來了？）",
  ui_story_5029_50290019_14_dialog_content = "卡蓮！小心——！",
  ui_story_5029_50290019_15_dialog_content = "<color=#828282>咚！</color>",
  ui_story_5029_50290019_16_dialog_content = "PlayerName，你還能聽見我說話嗎？",
  ui_story_5029_50290019_17_dialog_content = "嗯……",
  ui_story_5029_50290019_18_dialog_content = "妳，妳還好嗎？",
  ui_story_5029_50290019_19_dialog_content = "PlayerName，你是不是傻？",
  ui_story_5029_50290019_20_dialog_content = "你替我擋住了犯人的攻擊，還問我怎麼樣？",
  ui_story_5029_50290019_21_dialog_content = "我是害怕......害怕妳的新裙子被弄壞，就不好看了。",
  ui_story_5029_50290019_22_dialog_content = "都什麼時候了，你還擔心什麼裙子？",
  ui_story_5029_50290019_23_dialog_content = "你被砸到哪裡了，快讓我看看！",
  ui_story_5029_50290019_24_dialog_content = "我沒事的，休息一下就好。",
  ui_story_5029_50290019_25_dialog_content = "你剛剛差點失去意識，還說沒事？",
  ui_story_5029_50290019_26_dialog_content = "你愈是這樣，我就愈自責......",
  ui_story_5029_50290019_27_dialog_content = "我不希望我的隊友因為我而受傷，永遠都不希望！",
  ui_story_5029_50290019_28_dialog_content = "卡蓮，之前都是我被大家營救。",
  ui_story_5029_50290019_29_dialog_content = "這次我終於有機會當了一次騎士，而且還救到了真正的公主。",
  ui_story_5029_50290019_30_dialog_content = "我覺得，滿榮幸的。",
  ui_story_5029_50290019_31_dialog_content = "......我看你是真的不覺得疼了。",
  ui_story_5029_50290019_32_dialog_content = "妳看這是什麼？",
  ui_story_5029_50290019_33_dialog_content = "銀盒？這是領主的銀盒？",
  ui_story_5029_50290019_34_dialog_content = "犯人剛才一定是害怕被我們制服，所以就把銀盒扔給我們逃跑了。",
  ui_story_5029_50290019_35_dialog_content = "他應該還沒有走遠，我們繼續追......疼疼疼。",
  ui_story_5029_50290019_36_dialog_content = "你這副模樣還怎麼追？",
  ui_story_5029_50290019_37_dialog_content = "別看你現在還有說有笑，萬一傷到內臟的話，後果不堪設想。",
  ui_story_5029_50290019_38_dialog_content = "我不想世上唯一的空裔因為我而有什麼三長兩短。",
  ui_story_5029_50290019_39_dialog_content = "那樣的話，恐怕我會成為史書上的罪人。",
  ui_story_5029_50290019_40_dialog_content = "不行......要趕緊帶你下山去看醫生。",
  ui_story_5029_50290019_41_dialog_content = "我……",
  ui_story_5029_50290019_42_option_content = "同意下山",
  ui_story_5029_50290019_43_dialog_content = "領主說過，找到銀盒就好。",
  ui_story_5029_50290019_44_dialog_content = "雖然不知道犯人究竟是誰，但是希望他只是一時貪念，以後不會再犯......",
  ui_story_5029_50290019_45_dialog_content = "起了一次歹心的人，就會忍不住犯第二次、第三次。",
  ui_story_5029_50290019_46_dialog_content = "那妳為什麼還要堅持和我一起下山？",
  ui_story_5029_50290019_47_dialog_content = "與邪惡抗爭的道路，不該是隊友的性命鋪就的。",
  ui_story_5029_50290019_48_dialog_content = "我不希望你有事，就這麼簡單。",
  ui_story_5029_50290019_49_dialog_content = "只是「隊友」嗎......",
  ui_story_5029_50290019_50_dialog_content = "你說什麼？",
  ui_story_5029_50290019_51_dialog_content = "沒……沒什麼！",
  ui_story_5029_50290019_52_dialog_content = "多謝卡蓮殿下和PlayerName！",
  ui_story_5029_50290019_53_dialog_content = "竟然在這麼短的時間內就找回了我的遺失之物。",
  ui_story_5029_50290019_54_dialog_content = "不愧是白夜城的公主殿下、衛隊的隊長大人！",
  ui_story_5029_50290019_55_dialog_content = "白夜城在您的治理下，必將更加安穩、昌盛！",
  ui_story_5029_50290019_56_dialog_content = "免禮，只是舉手之勞罷了。",
  ui_story_5029_50290019_57_dialog_content = "領主看起來是個好人，沒想到拍起馬屁來也是一套一套的......",
  ui_story_5029_50290019_58_dialog_content = "明明PlayerName都受傷了。",
  ui_story_5029_50290019_59_dialog_content = "醫生說我沒什麼事，不用擔心。",
  ui_story_5029_50290019_60_dialog_content = "欸？領主大叔身旁放著的就是那個丟失的銀盒子嗎？",
  ui_story_5029_50290019_61_dialog_content = "哼，看起來也滿普通嘛。",
  ui_story_5029_50290019_62_dialog_content = "如果我也有在街上碰見犯人的運氣就好了。",
  ui_story_5029_50290019_63_dialog_content = "薇絲和菲雅兩位偵探也辛苦了。",
  ui_story_5029_50290019_64_dialog_content = "我為大家準備了一些辛苦費，還安排了好泊城的特色晚宴。",
  ui_story_5029_50290019_65_dialog_content = "大家這邊請。",
  ui_story_5029_50290019_66_option_content = "堅持追擊",
  ui_story_5029_50290019_67_dialog_content = "雖然領主說過，找到銀盒就好。",
  ui_story_5029_50290019_68_dialog_content = "但我還是希望我們能抓住犯人。",
  ui_story_5029_50290019_69_dialog_content = "卡蓮，我知道妳比誰都熱愛白夜城和白夜城統治下的土地。",
  ui_story_5029_50290019_70_dialog_content = "妳也一定不希望那個人再出來做壞事吧？",
  ui_story_5029_50290019_71_dialog_content = "可是你......",
  ui_story_5029_50290019_72_dialog_content = "我可是空裔，和暗鬼作戰的大風大浪都挺過來了，還會害怕這點小傷？",
  ui_story_5029_50290019_73_dialog_content = "放心，我的命很硬的。",
  ui_story_5029_50290019_74_dialog_content = "PlayerName......好。",
  ui_story_5029_50290019_75_dialog_content = "你能感應到他逃跑的方向嗎？",
  ui_story_5029_50290019_76_dialog_content = "嗯！",
  ui_story_5029_50290020_1_dialog_content = "呼哧......呼哧......我們已經跑到好泊城外面的荒野上了吧。",
  ui_story_5029_50290020_2_dialog_content = "跑了這麼久，他都不覺得累嗎？",
  ui_story_5029_50290020_3_dialog_content = "就在前面，我已經看到他的背影了！",
  ui_story_5029_50290020_4_dialog_content = "可是我們和他之間的距離......還是有好遠。",
  ui_story_5029_50290020_5_dialog_content = "早知道這樣，我就應該隨身帶著我的長弓。",
  ui_story_5029_50290020_6_dialog_content = "我也想不到在祕密調查的途中，就遇到了犯人......",
  ui_story_5029_50290020_7_dialog_content = "呼哧......呼哧......可是對方的體力很好，我們可能追不上。",
  ui_story_5029_50290020_8_dialog_content = "……",
  ui_story_5029_50290020_9_dialog_content = "薇絲？妳，妳怎麼停下來了？",
  ui_story_5029_50290020_10_dialog_content = "現在只能試試這個了。",
  ui_story_5029_50290020_11_dialog_content = "為什麼忽然舉起一塊石頭看著我？",
  ui_story_5029_50290020_12_dialog_content = "就，就算威脅我，我也沒法跑得更快了啊......",
  ui_story_5029_50290020_13_dialog_content = "我記得你頭上的綁帶有一些彈性，可以借我用一下嗎？",
  ui_story_5029_50290020_14_dialog_content = "難道妳可以用綁帶做一把弓？",
  ui_story_5029_50290020_15_dialog_content = "怎麼可能......我是想用綁帶包住石頭，然後甩出去。",
  ui_story_5029_50290020_16_dialog_content = "原來如此......請用！",
  ui_story_5029_50290020_17_dialog_content = "多謝，成敗在此一舉。",
  ui_story_5029_50290020_18_dialog_content = "目標追蹤！",
  ui_story_5029_50290020_19_dialog_content = "擊中了......他倒在地上了！",
  ui_story_5029_50290020_20_dialog_content = "當年在課堂上學到的小技巧，沒想到真的能派上用場。",
  ui_story_5029_50290020_21_dialog_content = "薇絲妳也太厲害了！",
  ui_story_5029_50290020_22_dialog_content = "不過這一招威力有限，我們快趁機追上他！",
  ui_story_5029_50290020_23_dialog_content = "嗯！",
  ui_story_5029_50290020_24_dialog_content = "快，馬上就到了！",
  ui_story_5029_50290020_25_dialog_content = "……",
  ui_story_5029_50290020_26_dialog_content = "糟了，犯人已經站起來了！",
  ui_story_5029_50290020_27_dialog_content = "他好像把什麼東西扔掉了？",
  ui_story_5029_50290020_28_dialog_content = "是銀盒？！",
  ui_story_5029_50290020_29_dialog_content = "銀盒好像快要滾進旁邊的山谷了。",
  ui_story_5029_50290020_30_dialog_content = "滾進山谷深處再找回來就難了......",
  ui_story_5029_50290020_31_dialog_content = "我去撿！",
  ui_story_5029_50290020_32_dialog_content = "薇絲？小心啊——！",
  ui_story_5029_50290020_33_dialog_content = "咳咳……",
  ui_story_5029_50290020_34_dialog_content = "薇絲？薇絲，妳還好嗎？",
  ui_story_5029_50290020_35_dialog_content = "我......沒事。",
  ui_story_5029_50290020_36_dialog_content = "妳怎麼不和我商量一下就衝進山谷裡去了？",
  ui_story_5029_50290020_37_dialog_content = "那樣太危險了！",
  ui_story_5029_50290020_38_dialog_content = "PlayerName，你會不會有點太小看我了？",
  ui_story_5029_50290020_39_dialog_content = "咳咳......我這不是好好地爬上來了嗎。",
  ui_story_5029_50290020_40_dialog_content = "我還以為，還以為妳真的掉下去回不來了......",
  ui_story_5029_50290020_41_dialog_content = "放心啦。",
  ui_story_5029_50290020_42_dialog_content = "我在啟光接受了那麼多年的訓練，這個小山坡還能困住我嗎？",
  ui_story_5029_50290020_43_dialog_content = "而且......你看！",
  ui_story_5029_50290020_44_dialog_content = "我們終於找到這個了咳咳......",
  ui_story_5029_50290020_45_dialog_content = "妳咳嗽成這樣，一定是傷到哪裡了吧？",
  ui_story_5029_50290020_46_dialog_content = "我真的沒事。",
  ui_story_5029_50290020_47_dialog_content = "比起這個，那個犯人應該還沒有跑遠。",
  ui_story_5029_50290020_48_dialog_content = "我們接著去追！",
  ui_story_5029_50290020_49_dialog_content = "啊……",
  ui_story_5029_50290020_50_dialog_content = "薇絲……？",
  ui_story_5029_50290020_51_dialog_content = "妳的腳踝附近好紅......是不是腫了？",
  ui_story_5029_50290020_52_dialog_content = "我們不要勉強了，快點回去請醫生給妳看看吧。",
  ui_story_5029_50290020_53_dialog_content = "只差一步！只差一步就可以抓住犯人了。",
  ui_story_5029_50290020_54_dialog_content = "PlayerName，我不甘心。",
  ui_story_5029_50290020_55_dialog_content = "你也和我一樣想要抓住他，對吧？",
  ui_story_5029_50290020_56_option_content = "說服薇絲",
  ui_story_5029_50290020_57_dialog_content = "雖然妳一直跟我說妳沒事，但我也不是三歲的小孩子。",
  ui_story_5029_50290020_58_dialog_content = "還是能看得出，妳剛剛一定是摔到自己了。",
  ui_story_5029_50290020_59_dialog_content = "我承認我是很想抓住真正的犯人，但是我更不想妳的傷情惡化......",
  ui_story_5029_50290020_60_dialog_content = "PlayerName……",
  ui_story_5029_50290020_61_dialog_content = "領主說過只要我們能找到銀盒就好。",
  ui_story_5029_50290020_62_dialog_content = "我們已經完成任務了，就別再勉強自己了，好嗎？",
  ui_story_5029_50290020_63_dialog_content = "......嗯，聽你的。",
  ui_story_5029_50290020_64_dialog_content = "多謝PlayerName和薇絲小姐！",
  ui_story_5029_50290020_65_dialog_content = "竟然在這麼短的時間內就找回了我的遺失之物。",
  ui_story_5029_50290020_66_dialog_content = "聽說薇絲小姐是啟光的探索隊隊長？",
  ui_story_5029_50290020_67_dialog_content = "怪不得有這樣強的搜查能力，有您二位的幫助實在是我的榮幸！",
  ui_story_5029_50290020_68_dialog_content = "別客氣，我也很感激您幫我找名醫治療呢。",
  ui_story_5029_50290020_69_dialog_content = "不過是找個盒子，竟然把自己傷成這樣嗎......",
  ui_story_5029_50290020_70_dialog_content = "欸？領主大叔身旁放著的就是那個丟失的銀盒子嗎？",
  ui_story_5029_50290020_71_dialog_content = "哼，看起來也滿普通嘛。",
  ui_story_5029_50290020_72_dialog_content = "這次也非常感謝卡蓮大人能夠出手相助。",
  ui_story_5029_50290020_73_dialog_content = "接下來還希望您能好好享受在好泊城的旅程！",
  ui_story_5029_50290020_74_dialog_content = "還有菲雅呢！",
  ui_story_5029_50290020_75_dialog_content = "哦，當然。菲雅偵探，也辛苦妳了。",
  ui_story_5029_50290020_76_dialog_content = "我為大家準備了一些辛苦費，還安排了好泊城的特色晚宴。",
  ui_story_5029_50290020_77_dialog_content = "大家這邊請。",
  ui_story_5029_50290020_78_option_content = "同意薇絲",
  ui_story_5029_50290020_79_dialog_content = "是，我是想抓到犯人沒錯。",
  ui_story_5029_50290020_80_dialog_content = "可是我也不能放著妳的傷勢不管。",
  ui_story_5029_50290020_81_dialog_content = "你今天是怎麼了嘛。",
  ui_story_5029_50290020_82_dialog_content = "我們一起經歷過了那麼多大風大浪，你見過我有什麼時候退縮過嗎？",
  ui_story_5029_50290020_83_dialog_content = "......沒有，妳一直很勇敢。",
  ui_story_5029_50290020_84_dialog_content = "PlayerName，相信我！",
  ui_story_5029_50290020_85_dialog_content = "這點小小的皮肉傷對我來說真的沒什麼的。",
  ui_story_5029_50290020_86_dialog_content = "而且，那個犯人說不定還會做出別的壞事......",
  ui_story_5029_50290020_87_dialog_content = "只有我們能將他繩之以法了。",
  ui_story_5029_50290020_88_dialog_content = "嗯！",
  ui_story_5029_50290021_1_dialog_content = "凱羅，做得好！",
  ui_story_5029_50290021_2_dialog_content = "幸虧凱羅剛才擋住了通往後山的路。",
  ui_story_5029_50290021_3_dialog_content = "要不然我真的跟不上犯人上山的速度......",
  ui_story_5029_50290021_4_dialog_content = "可在城市的街道上，他跑得就比我們更快了。",
  ui_story_5029_50290021_5_dialog_content = "我們不是還有凱羅嗎？",
  ui_story_5029_50290021_6_dialog_content = "囉......",
  ui_story_5029_50290021_7_dialog_content = "凱羅，我們就靠你了喔。",
  ui_story_5029_50290021_8_dialog_content = "去攔住剛才那個犯人吧！",
  ui_story_5029_50290021_9_dialog_content = "囉囉囉？",
  ui_story_5029_50290021_10_dialog_content = "凱羅，怎麼了，為什麼停下來了？",
  ui_story_5029_50290021_11_dialog_content = "那個壞蛋就在前面！",
  ui_story_5029_50290021_12_dialog_content = "囉......",
  ui_story_5029_50290021_13_dialog_content = "街道上人變多了......凱羅已經分不清誰是犯人了。",
  ui_story_5029_50290021_14_dialog_content = "唔呀，沒關係，我帶了訊號槍。",
  ui_story_5029_50290021_15_dialog_content = "我把訊號標記到哪個人身上，你就去攔住他，別讓他帶走銀盒。",
  ui_story_5029_50290021_16_dialog_content = "凱羅，懂了嗎？",
  ui_story_5029_50290021_17_dialog_content = "囉！",
  ui_story_5029_50290021_18_dialog_content = "菲雅的致命訊號攻擊——嗶唷！",
  ui_story_5029_50290021_19_dialog_content = "……？",
  ui_story_5029_50290021_20_dialog_content = "嚕......囉！！！",
  ui_story_5029_50290021_21_dialog_content = "就是這樣，凱羅，追上他狠狠咬住他的手！",
  ui_story_5029_50290021_22_dialog_content = "囉囉囉！",
  ui_story_5029_50290021_23_dialog_content = "！！！",
  ui_story_5029_50290021_24_dialog_content = "菲雅，我之前都不知道妳的槍法竟然這麼準。",
  ui_story_5029_50290021_25_dialog_content = "說實話，我也不知道。",
  ui_story_5029_50290021_26_dialog_content = "<color=#828282>嗶唷！</color>",
  ui_story_5029_50290021_27_dialog_content = "嗯？怎麼又打出去一槍？",
  ui_story_5029_50290021_28_dialog_content = "哎呀呀呀......打到哪裡去了？",
  ui_story_5029_50290021_29_dialog_content = "凱羅，別管我剛才的第二槍！",
  ui_story_5029_50290021_30_dialog_content = "繼續咬住那個人，別讓他帶走銀盒！",
  ui_story_5029_50290021_31_dialog_content = "……！",
  ui_story_5029_50290021_32_dialog_content = "犯人摔倒了！",
  ui_story_5029_50290021_33_dialog_content = "凱羅和銀盒一起滾落到地上了......",
  ui_story_5029_50290021_34_dialog_content = "凱羅，你沒事吧？",
  ui_story_5029_50290021_35_dialog_content = "囉！",
  ui_story_5029_50290021_36_dialog_content = "銀盒被你保護得很好呢！",
  ui_story_5029_50290021_37_dialog_content = "你今天可是立了大功一件喔。",
  ui_story_5029_50290021_38_dialog_content = "拿回這個銀盒子，就有獎金可以領囉～",
  ui_story_5029_50290021_39_dialog_content = "不好，犯人跑向港口的方向了。",
  ui_story_5029_50290021_40_dialog_content = "哼，休想逃出菲雅的手掌心。",
  ui_story_5029_50290021_41_dialog_content = "我們繼續追！",
  ui_story_5029_50290021_42_dialog_content = "等等！",
  ui_story_5029_50290021_43_dialog_content = "欸？叫我？",
  ui_story_5029_50290021_44_dialog_content = "剛才就是妳在街上開槍的吧？膽子很大嘛。",
  ui_story_5029_50290021_45_dialog_content = "說！是誰指使妳襲擊我的？",
  ui_story_5029_50290021_46_dialog_content = "欸，第二發竟然打到兵大叔身上了......",
  ui_story_5029_50290021_47_dialog_content = "這麼說，妳在這裡打了好幾槍？",
  ui_story_5029_50290021_48_dialog_content = "我現在懷疑妳故意破壞好泊城的治安，跟我走一趟吧！",
  ui_story_5029_50290021_49_dialog_content = "菲雅現在有很重要的事情要忙，不能跟你走。",
  ui_story_5029_50290021_50_dialog_content = "竟敢當街拒捕？！",
  ui_story_5029_50290021_51_dialog_content = "等一下，這中間可能是有什麼誤會。",
  ui_story_5029_50290021_52_dialog_content = "你是這姑娘的哥哥嗎？",
  ui_story_5029_50290021_53_dialog_content = "才不是呢，菲雅沒有哥哥！他是菲雅的神奇動物。",
  ui_story_5029_50290021_54_dialog_content = "......就是同夥囉？那就一起走吧！",
  ui_story_5029_50290021_55_dialog_content = "那個，我們剛才確實有點著急了，咳咳，菲雅......",
  ui_story_5029_50290021_56_dialog_content = "第二發信號彈打到別人身上的確是我們做錯了，快給人家道個歉吧。",
  ui_story_5029_50290021_57_dialog_content = "哼。",
  ui_story_5029_50290021_58_dialog_content = "菲雅！",
  ui_story_5029_50290021_59_dialog_content = "哦......好吧。剛才是我不小心，對不起。",
  ui_story_5029_50290021_60_dialog_content = "對不起，對不起。",
  ui_story_5029_50290021_61_dialog_content = "這種道歉如果有用的話，還要維持治安的官兵幹什麼？",
  ui_story_5029_50290021_62_dialog_content = "跟我去接受審訊吧！",
  ui_story_5029_50290021_63_option_content = "同意跟私兵走",
  ui_story_5029_50290021_64_dialog_content = "好，我同意跟你走。",
  ui_story_5029_50290021_65_dialog_content = "PlayerName，你在說什麼呀？犯人怎麼辦......",
  ui_story_5029_50290021_66_dialog_content = "領主說過只要我們能找到銀盒就好。",
  ui_story_5029_50290021_67_dialog_content = "雖然我也很想抓到犯人，但我們一時半會和這個私兵也說不清楚。",
  ui_story_5029_50290021_68_dialog_content = "還是不要再節外生枝了。",
  ui_story_5029_50290021_69_dialog_content = "好吧......反正只要我能拿到獎金就行。",
  ui_story_5029_50290021_70_dialog_content = "你們在講什麼悄悄話呢？",
  ui_story_5029_50290021_71_dialog_content = "我們同意跟你走，但希望你能把我們帶到領主那裡。",
  ui_story_5029_50290021_72_dialog_content = "領主可沒時間處理這種小事。",
  ui_story_5029_50290021_73_dialog_content = "無論如何......領主到時候一定會替我們給你一個交代的。",
  ui_story_5029_50290021_74_dialog_content = "這兩位是我的客人，這次事件我會為他們的行動負責。",
  ui_story_5029_50290021_75_dialog_content = "這些補償，應該能夠支付清洗訊號彈痕跡的費用了吧？",
  ui_story_5029_50290021_76_dialog_content = "夠了，足夠了！多謝領主大人！",
  ui_story_5029_50290021_77_dialog_content = "多謝PlayerName和菲雅小姐！",
  ui_story_5029_50290021_78_dialog_content = "竟然在這麼短的時間內就找回了我的遺失之物。",
  ui_story_5029_50290021_79_dialog_content = "聽說菲雅小姐還是神奇動物專家？",
  ui_story_5029_50290021_80_dialog_content = "我也讀過一些神奇動物的著作，有機會一定要好好切磋一下！",
  ui_story_5029_50290021_81_dialog_content = "欸，菲雅還沒想過自己也能收徒弟呢......",
  ui_story_5029_50290021_82_dialog_content = "菲雅，領主應該沒有那個意思。",
  ui_story_5029_50290021_83_dialog_content = "總而言之，有您兩位的幫助實在是我的榮幸！",
  ui_story_5029_50290021_84_dialog_content = "哎呀，領主大叔別客氣～",
  ui_story_5029_50290021_85_dialog_content = "不過要不是你的私兵把我們攔住，我們一定給你把犯人也抓回來不可！",
  ui_story_5029_50290021_86_dialog_content = "菲雅不會把這個消息搞得滿城皆知了吧......",
  ui_story_5029_50290021_87_dialog_content = "這樣還能算是祕密調查嗎？",
  ui_story_5029_50290021_88_dialog_content = "放心，雖然追犯人的過程被人看到了，不過他們應該不知道其中的緣由。",
  ui_story_5029_50290021_89_dialog_content = "這次也非常感謝卡蓮大人和薇絲小姐能夠花時間相助。",
  ui_story_5029_50290021_90_dialog_content = "接下來還希望二位能好好享受在好泊城的旅程！",
  ui_story_5029_50290021_91_dialog_content = "我為大家準備了一些辛苦費，還安排了好泊城的特色晚宴。",
  ui_story_5029_50290021_92_dialog_content = "大家這邊請。",
  ui_story_5029_50290021_93_option_content = "拒絕跟私兵走",
  ui_story_5029_50290021_94_dialog_content = "抱歉，我們真的有很重要的事情，而且這件事是領主直接交代我們的。",
  ui_story_5029_50290021_95_dialog_content = "請想清楚，如果你還是執意要攔住我們的話......",
  ui_story_5029_50290021_96_dialog_content = "到時候我們沒能完成任務，你可要對此負責。",
  ui_story_5029_50290021_97_dialog_content = "這……",
  ui_story_5029_50290021_98_dialog_content = "你們有什麼證據嗎，我為什麼要相信你們的一面之詞？",
  ui_story_5029_50290021_99_dialog_content = "如果你不相信，大可以現在就帶我們回去見領主。",
  ui_story_5029_50290021_100_dialog_content = "看看到時候領主會怎麼跟你說。",
  ui_story_5029_50290022_1_dialog_content = "哇——！！！",
  ui_story_5029_50290022_2_dialog_content = "菲雅來到好泊城之後，還沒見過這麼多好吃的！",
  ui_story_5029_50290022_3_dialog_content = "哼，領主大叔還算有良心嘛。",
  ui_story_5029_50290022_4_dialog_content = "今天跑來跑去的，肚子早就餓扁了！我就不客氣囉～",
  ui_story_5029_50290022_5_dialog_content = "......慢點吃，沒人跟妳搶。",
  ui_story_5029_50290022_6_dialog_content = "這一箱白夜幣都是給我們的辛苦費嗎？",
  ui_story_5029_50290022_7_dialog_content = "領主真是太慷慨了！",
  ui_story_5029_50290022_8_dialog_content = "人人有份的話，要怎麼分才好呢？",
  ui_story_5029_50290022_9_dialog_content = "功勞最大的人......",
  ui_story_5029_50290022_10_dialog_content = "我記得妳上學的時候，並沒有這樣愛算計錢財。",
  ui_story_5029_50290022_11_dialog_content = "咳咳，我......我也是生活所迫。",
  ui_story_5029_50290022_12_dialog_content = "畢竟不是白夜城的大小姐、貴公子，走到哪裡都有人供著。",
  ui_story_5029_50290022_13_dialog_content = "......那，妳們分這些錢就好了。不用算我的那一份。",
  ui_story_5029_50290022_14_dialog_content = "欸欸欸，竟然有人不要嗎？那給菲雅好啦。",
  ui_story_5029_50290022_15_dialog_content = "我可以給詩燁師姐也買個禮物，這樣就能堵住她吐槽我的嘴了！",
  ui_story_5029_50290022_16_dialog_content = "還是把卡蓮的那份平均分比較公平吧？",
  ui_story_5029_50290022_17_dialog_content = "凱羅凱羅，來張嘴！",
  ui_story_5029_50290022_18_dialog_content = "菲雅，寵物是不能上餐桌的。",
  ui_story_5029_50290022_19_dialog_content = "......凱羅是我的夥伴，才不是寵物呢！",
  ui_story_5029_50290022_20_dialog_content = "（這三個人之間的氛圍，似乎還是有點不太對啊。）",
  ui_story_5029_50290022_21_dialog_content = "（領主離席之後怎麼還不回來？也許只有他能化解大家之間的尷尬了。）",
  ui_story_5029_50290022_22_dialog_content = "（哎，早知道當初就應該......）",
  ui_story_5029_50290022_23_dialog_content = "領主大人......",
  ui_story_5029_50290022_24_dialog_content = "什麼？！",
  ui_story_5029_50290022_25_dialog_content = "（領主，領主終於回來了。）",
  ui_story_5029_50290022_26_dialog_content = "（嗯？贊恩在領主耳邊說什麼呢？）",
  ui_story_5029_50290022_27_dialog_content = "（為什麼領主的臉色忽然變得那麼難看？）",
  ui_story_5029_50290022_28_dialog_content = "（呼吸......忽然變得急促。）",
  ui_story_5029_50290022_29_dialog_content = "（為什麼有一種不祥的預感？）",
  ui_story_5029_50290022_30_dialog_content = "（究竟是怎麼了？）",
  ui_story_5029_50290022_31_dialog_content = "（......犯人？！）",
  ui_story_5029_50290022_32_dialog_content = "（是犯人又回來了嗎？）",
  ui_story_5029_50290022_33_dialog_content = "（這次，他又會做出什麼事......）",
  ui_story_5029_50290022_34_dialog_content = "<color=#828282>叮鈴——</color>",
  ui_story_5029_50290022_35_dialog_content = "歡迎回來，我親愛的客人。",
  ui_story_5029_50290022_36_dialog_content = "看到我的臉，讓您感到失望了嗎？",
  ui_story_5029_50290022_37_dialog_content = "現在您知道了，主宰命運或許並不是那麼輕鬆的一件事。",
  ui_story_5029_50290022_38_dialog_content = "而您似乎對自己親手寫下的結局，不是那麼滿意。",
  ui_story_5029_50290022_39_dialog_content = "心中有許多疑問和困惑？哈哈哈......",
  ui_story_5029_50290022_40_dialog_content = "不止是夢境，真實的生活又何嘗不是如此。",
  ui_story_5029_50290022_41_dialog_content = "它欠我們一個清晰的答案。",
  ui_story_5029_50290022_42_dialog_content = "但話說回來，總是把選擇權交給別人，又怎能擁有自己的故事？",
  ui_story_5029_50290022_43_dialog_content = "呼......所幸我們還有時間。",
  ui_story_5029_50290022_44_dialog_content = "前提是，您還想改寫夢中的結局。",
  ui_story_5029_50290023_1_dialog_content = "卡蓮，怎麼樣？",
  ui_story_5029_50290023_2_dialog_content = "……",
  ui_story_5029_50290023_3_dialog_content = "那個人很狡猾，完全沒有留下一絲痕跡。",
  ui_story_5029_50290023_4_dialog_content = "我也感應不到那個人的方位了......",
  ui_story_5029_50290023_5_dialog_content = "枉我身為白夜城衛隊長，竟然跟丟了犯人。",
  ui_story_5029_50290023_6_dialog_content = "這件事怪我，如果不是我剛才被砸得暈頭轉向，現在我們早就抓住犯人了。",
  ui_story_5029_50290023_7_dialog_content = "別這麼說，是你替我捱了那一下。",
  ui_story_5029_50290023_8_dialog_content = "總之......總之當時我可以有更好的處理方法的！",
  ui_story_5029_50290023_9_dialog_content = "而且這個犯人，真的是我見過的跑得最快的人了。",
  ui_story_5029_50290023_10_dialog_content = "他爬上坡路竟然都不喘，暗鬼都沒有他這麼能跑。",
  ui_story_5029_50290023_11_dialog_content = "不用再安慰我了，PlayerName。",
  ui_story_5029_50290023_12_dialog_content = "我明白你是想讓我心裡好受一些。",
  ui_story_5029_50290023_13_dialog_content = "但是你知道嗎？",
  ui_story_5029_50290023_14_dialog_content = "成為騎士的條件不是帶過多少兵、打過多少仗......",
  ui_story_5029_50290023_15_dialog_content = "而是敢於去承擔責任，敢於為自己的行為負責，也包括失敗。",
  ui_story_5029_50290023_16_dialog_content = "卡蓮……",
  ui_story_5029_50290023_17_dialog_content = "怎麼了，為什麼忽然露出這種表情？",
  ui_story_5029_50290023_18_dialog_content = "雖然早就覺得妳比我們這些同齡人更冷靜、更堅強......",
  ui_story_5029_50290023_19_dialog_content = "但最近，我覺得妳好像比往常又成熟了幾分。",
  ui_story_5029_50290023_20_dialog_content = "我就當你是在誇我了，多謝。",
  ui_story_5029_50290023_21_dialog_content = "......妳好像一直在壓抑自己。",
  ui_story_5029_50290023_22_dialog_content = "嗯？",
  ui_story_5029_50290023_23_dialog_content = "也許是我的錯覺......",
  ui_story_5029_50290023_24_dialog_content = "但我覺得妳好像在逼自己成為一個全知全能、沒有弱點的聖人。",
  ui_story_5029_50290023_25_dialog_content = "……",
  ui_story_5029_50290023_26_dialog_content = "所以不知道為什麼，妳愈是堅強、愈是果斷，我就愈覺得心疼。",
  ui_story_5029_50290023_27_dialog_content = "心疼妳不能像我一樣大剌剌。",
  ui_story_5029_50290023_28_dialog_content = "心疼妳不能吐露自己的喜怒哀樂。",
  ui_story_5029_50290023_29_dialog_content = "心疼妳明明已經承擔了許多，還仍然被許多人嘲笑是嬌弱的溫室花朵。",
  ui_story_5029_50290023_30_dialog_content = "……",
  ui_story_5029_50290023_31_dialog_content = "噗嗤，哈哈哈哈哈。",
  ui_story_5029_50290023_32_dialog_content = "妳，妳笑什麼？",
  ui_story_5029_50290023_33_dialog_content = "抱歉抱歉，我也不知道為什麼。",
  ui_story_5029_50290023_34_dialog_content = "只是從來沒有人和我說過這些，我也有點不知道怎麼回答才好。",
  ui_story_5029_50290023_35_dialog_content = "嗯，千，千萬不要在意我說了些什麼亂七八糟的。",
  ui_story_5029_50290023_36_dialog_content = "可能是剛才我被砸壞了腦袋吧......",
  ui_story_5029_50290023_37_dialog_content = "唉，還是想想回去以後該怎麼跟領主他們交代吧。",
  ui_story_5029_50290023_38_dialog_content = "也不是一無所獲，至少我們追回了他的銀盒。",
  ui_story_5029_50290023_39_dialog_content = "而且，我們還在無意間發現了其他的寶藏。",
  ui_story_5029_50290023_40_dialog_content = "其他的寶藏？",
  ui_story_5029_50290023_41_dialog_content = "PlayerName，抬頭呀。",
  ui_story_5029_50290023_42_dialog_content = "欸？",
  ui_story_5029_50290023_43_dialog_content = "看，這山頂上竟然有一座荒廢的觀景台。",
  ui_story_5029_50290023_44_dialog_content = "站在這裡，可以看見整個好泊城的夜景。",
  ui_story_5029_50290023_45_dialog_content = "我們現在是站在好泊城背靠的那座山上，對不對？",
  ui_story_5029_50290023_46_dialog_content = "怪不得視野這麼好。",
  ui_story_5029_50290023_47_dialog_content = "以前竟然從來都沒人告訴過我好泊城附近有這種好地方！",
  ui_story_5029_50290023_48_dialog_content = "（卡蓮......好像忽然變得很開心？）",
  ui_story_5029_50290023_49_dialog_content = "PlayerName，還愣著幹什麼？",
  ui_story_5029_50290023_50_dialog_content = "這裡風景真的好好看！",
  ui_story_5029_50290023_51_dialog_content = "海洋已經化作一頭沉睡的黑獸，只有好泊城依舊燈火閃爍。",
  ui_story_5029_50290023_52_dialog_content = "整座城市就好像鑲嵌在艾斯特拉大陸上的一串珍珠......",
  ui_story_5029_50290023_53_dialog_content = "真的......好美。",
  ui_story_5029_50290023_54_option_content = "謝謝妳，卡蓮",
  ui_story_5029_50290023_55_dialog_content = "彼此彼此，這也是我想對你說的。",
  ui_story_5029_50290023_56_dialog_content = "我還沒說我想謝妳什麼呢......",
  ui_story_5029_50290023_57_dialog_content = "彼此彼此，我也沒說想謝你什麼呢。",
  ui_story_5029_50290023_58_dialog_content = "妳......妳怎麼忽然變得這麼幼稚？",
  ui_story_5029_50290023_59_dialog_content = "你剛剛還嫌棄我太成熟。",
  ui_story_5029_50290023_60_option_content = "妳是不是有話對我說？",
  ui_story_5029_50290023_61_dialog_content = "嗯……",
  ui_story_5029_50290023_62_dialog_content = "你知道嗎，白夜城的夜景也不输給好泊城。",
  ui_story_5029_50290023_63_dialog_content = "但我那是總是形單影隻，不是在執行任務，就是在執行任務的路上。",
  ui_story_5029_50290023_64_dialog_content = "總覺得白夜城離開我好像就運轉不起來似的。",
  ui_story_5029_50290023_65_dialog_content = "愈那麼想，我就愈賣力......",
  ui_story_5029_50290023_66_dialog_content = "從來沒有停下腳步，好好享受夜晚的美麗。",
  ui_story_5029_50290023_67_dialog_content = "那個時候的我，肯定不會想到多年以後的某一天......",
  ui_story_5029_50290023_68_dialog_content = "我不僅沒能圓滿完成任務，甚至還在這裡悠閒地欣賞起風景來了。",
  ui_story_5029_50290023_69_dialog_content = "哈哈哈，是啊，以前的卡蓮一定不會想到有這麼一天。",
  ui_story_5029_50290023_70_dialog_content = "她也一定想不到，這種時候身邊竟然還站著一位空裔。",
  ui_story_5029_50290023_71_dialog_content = "聽起來像是我把妳帶壞了一樣......",
  ui_story_5029_50290023_72_dialog_content = "但我很慶幸是你。",
  ui_story_5029_50290023_73_dialog_content = "這句話就當作是對你的回答吧。",
  ui_story_5029_50290023_74_dialog_content = "什，什麼回答？",
  ui_story_5029_50290023_75_dialog_content = "難道剛剛是另一位空裔對我說了一堆排比句嗎？",
  ui_story_5029_50290023_76_dialog_content = "我……",
  ui_story_5029_50290023_77_dialog_content = "看，那裡是不是馬戲團？",
  ui_story_5029_50290023_78_dialog_content = "還有那裡，是我們今天去搜查過的高級酒店嗎？",
  ui_story_5029_50290023_79_dialog_content = "（這一刻，卡蓮好像放下了所有的戒備。）",
  ui_story_5029_50290023_80_dialog_content = "（我從來沒有見過她這麼開心地笑著、鬧著......）",
  ui_story_5029_50290023_81_dialog_content = "（也許她孩子氣的這一面，會成為一個祕密。）",
  ui_story_5029_50290023_82_dialog_content = "（一個只屬於我們两個人的祕密。）",
  ui_story_5029_50290023_83_dialog_content = "<color=#828282>叮鈴——</color>",
  ui_story_5029_50290023_84_dialog_content = "歡迎回來，我親愛的客人。",
  ui_story_5029_50290023_85_dialog_content = "看到我的臉，讓您感到失望了嗎？",
  ui_story_5029_50290023_86_dialog_content = "抱歉，我不小心看到了屬於你們兩個人的祕密。",
  ui_story_5029_50290023_87_dialog_content = "哦，但您大可不必這樣失望。",
  ui_story_5029_50290023_88_dialog_content = "夢境要依託現實的基礎才能成型。",
  ui_story_5029_50290023_89_dialog_content = "這意味著您與她在現實之中亦有可能經歷相似的情景。",
  ui_story_5029_50290023_90_dialog_content = "不過，與夢境不同的是，現實之中並沒有這樣的把戲。",
  ui_story_5029_50290023_91_dialog_content = "完全生活在這種由我創造出的虛幻之中......那樣多少會有些困難。",
  ui_story_5029_50290023_92_dialog_content = "話說回來，您對這個親筆寫下的結局滿意嗎？",
  ui_story_5029_50290023_93_dialog_content = "不會覺得有那麼一絲缺憾嗎？",
  ui_story_5029_50290023_94_dialog_content = "我想告訴您的是......我們還有時間。",
  ui_story_5029_50290023_95_dialog_content = "前提是，您還想在夢中找到那個謎底、那個答案。",
  ui_story_5029_50290024_1_dialog_content = "找到了！",
  ui_story_5029_50290024_2_dialog_content = "他就躲在那邊的草叢裡......",
  ui_story_5029_50290024_3_dialog_content = "嗯？",
  ui_story_5029_50290024_4_dialog_content = "仔細看，他的衣角露出來了！我去把他給揪出來。",
  ui_story_5029_50290024_5_dialog_content = "等等……",
  ui_story_5029_50290024_6_dialog_content = "這次不能再讓他跑掉了。",
  ui_story_5029_50290024_7_dialog_content = "目標追蹤！",
  ui_story_5029_50290024_8_dialog_content = "<color=#828282>轟隆！</color>",
  ui_story_5029_50290024_9_dialog_content = "啊……",
  ui_story_5029_50290024_10_dialog_content = "薇絲！！！",
  ui_story_5029_50290024_11_dialog_content = "PlayerName，對不起......",
  ui_story_5029_50290024_12_dialog_content = "呼......忽然說什麼對不起啊。",
  ui_story_5029_50290024_13_dialog_content = "我想了很久，覺得有時候我真的很衝動，總是想速戰速決地完成任務......",
  ui_story_5029_50290024_14_dialog_content = "所以經常會忽略身邊的危險。",
  ui_story_5029_50290024_15_dialog_content = "剛才......也是。",
  ui_story_5029_50290024_16_dialog_content = "遇到犯人後，就不管不顧地帶著你追到這種荒郊野嶺。",
  ui_story_5029_50290024_17_dialog_content = "結果最後掉進了犯人的陷阱。",
  ui_story_5029_50290024_18_dialog_content = "扭傷了腳踝走不了路不說，還連累你......要背著我走回去。",
  ui_story_5029_50290024_19_dialog_content = "所以，對不起！",
  ui_story_5029_50290024_20_dialog_content = "呼哧......薇絲，妳別這麼說。",
  ui_story_5029_50290024_21_dialog_content = "追趕犯人是我們兩個人共同做出的決定，怎麼能都怪到妳頭上去呢。",
  ui_story_5029_50290024_22_dialog_content = "何況剛才還是我帶的路，是我把妳領到了陷阱附近......",
  ui_story_5029_50290024_23_dialog_content = "如果非要說對不起，也應該是我對妳說。",
  ui_story_5029_50290024_24_dialog_content = "PlayerName，你不用這樣安慰我的。",
  ui_story_5029_50290024_25_dialog_content = "我知道今天是我做了錯事，才沒有抓住犯人。",
  ui_story_5029_50290024_26_dialog_content = "還記得嗎？",
  ui_story_5029_50290024_27_dialog_content = "當初要不是妳稀裡糊塗地把臨空者號敲出一個大洞......",
  ui_story_5029_50290024_28_dialog_content = "我也不會見到妳，更不會從地底下走出來了。",
  ui_story_5029_50290024_29_dialog_content = "那件事不一樣啦。",
  ui_story_5029_50290024_30_dialog_content = "我是真的有好好勘察才......",
  ui_story_5029_50290024_31_dialog_content = "等等，原來你一直覺得我當時是「稀裡糊塗」的啊？",
  ui_story_5029_50290024_32_dialog_content = "難道不是嗎？哈哈哈......",
  ui_story_5029_50290024_33_dialog_content = "你......原來你一直在心裡取笑我？",
  ui_story_5029_50290024_34_dialog_content = "喂喂，輕點敲我啊。",
  ui_story_5029_50290024_35_dialog_content = "啊，對不起，我把你敲痛了嗎？",
  ui_story_5029_50290024_36_dialog_content = "沒有很痛，就是覺得有點......有點背不動了。",
  ui_story_5029_50290024_37_dialog_content = "那邊有片草地，先把我放下來吧！",
  ui_story_5029_50290024_38_dialog_content = "嗯，小心不要再碰到腳踝。",
  ui_story_5029_50290024_39_dialog_content = "呼......累了一天，終於能躺一下了。",
  ui_story_5029_50290024_40_dialog_content = "是不是我太重了？",
  ui_story_5029_50290024_41_dialog_content = "妳一點也不重，只是......",
  ui_story_5029_50290024_42_dialog_content = "只是......？",
  ui_story_5029_50290024_43_dialog_content = "只是回程的路太長了。",
  ui_story_5029_50290024_44_dialog_content = "......我還以為你又要取笑我了。",
  ui_story_5029_50290024_45_dialog_content = "薇絲。",
  ui_story_5029_50290024_46_dialog_content = "嗯？",
  ui_story_5029_50290024_47_dialog_content = "我永遠都不會取笑妳的。",
  ui_story_5029_50290024_48_dialog_content = "……",
  ui_story_5029_50290024_49_dialog_content = "妳是帶我走出地底的人，也是鼓勵我走向遠方的人。",
  ui_story_5029_50290024_50_dialog_content = "沒有妳，我永遠都沒辦法認識那麼多人，看到那麼多風景。",
  ui_story_5029_50290024_51_dialog_content = "好啦好啦，我知道啦。",
  ui_story_5029_50290024_52_dialog_content = "你已經說過好多次啦，怎麼又提起這個來了。",
  ui_story_5029_50290024_53_dialog_content = "可能大家都以為，妳今天這麼賣力地查這起案子是因為豐厚的賞金。",
  ui_story_5029_50290024_54_dialog_content = "但是他們忘了，妳是啟光的一員。這些錢對妳來說一點用都沒有。",
  ui_story_5029_50290024_55_dialog_content = "妳想得到賞金，其實是為了補貼巨像的費用吧？",
  ui_story_5029_50290024_56_dialog_content = "嘿嘿，被你看出來了......沒關係的，我們是夥伴嘛！",
  ui_story_5029_50290024_57_dialog_content = "這些事情都是我應該做的。",
  ui_story_5029_50290024_58_dialog_content = "剛才背著妳的時候，我也想了很多。",
  ui_story_5029_50290024_59_dialog_content = "以前妳總是在身邊安慰我，鼓勵我，讓我學會依靠夥伴的力量。",
  ui_story_5029_50290024_60_dialog_content = "但我以前都沒有想過......",
  ui_story_5029_50290024_61_dialog_content = "其實薇絲，妳也不用一直那麼逞強。",
  ui_story_5029_50290024_62_dialog_content = "欸？",
  ui_story_5029_50290024_63_dialog_content = "妳也可以像今天這樣......",
  ui_story_5029_50290024_64_dialog_content = "偶爾也依靠一下妳的夥伴，依靠一下我嘛！",
  ui_story_5029_50290024_65_dialog_content = "PlayerName……",
  ui_story_5029_50290024_66_option_content = "一直以來多謝了！",
  ui_story_5029_50290024_67_dialog_content = "既然你都這麼說了，那我只能說......",
  ui_story_5029_50290024_68_dialog_content = "不客氣！",
  ui_story_5029_50290024_69_dialog_content = "那......以後也請多指教！",
  ui_story_5029_50290024_70_dialog_content = "彼此彼此，請多指教囉～",
  ui_story_5029_50290024_71_dialog_content = "真好。",
  ui_story_5029_50290024_72_dialog_content = "嗯？什麼真好？",
  ui_story_5029_50290024_73_dialog_content = "這裡的夕陽真好看啊。",
  ui_story_5029_50290024_74_dialog_content = "要是我腳沒有受傷就更好了。",
  ui_story_5029_50290024_75_option_content = "欸，妳沒事吧？",
  ui_story_5029_50290024_76_dialog_content = "沒事......",
  ui_story_5029_50290024_77_dialog_content = "我只是在回想，回想今天發生的所有事情。",
  ui_story_5029_50290024_78_dialog_content = "回想我們在書樓裡搜查的每一個細節。",
  ui_story_5029_50290024_79_dialog_content = "回想我們去劇院裡欣賞戲劇。",
  ui_story_5029_50290024_80_dialog_content = "回想我受傷後，你一直忙個不停。",
  ui_story_5029_50290024_81_dialog_content = "我以前真的沒有注意過，你還有這麼會照顧人的一面。",
  ui_story_5029_50290024_82_dialog_content = "你真的是個值得依靠的夥伴呢。",
  ui_story_5029_50290024_83_dialog_content = "那是當然！",
  ui_story_5029_50290024_84_dialog_content = "還有......我也想感受現在的這一刻。",
  ui_story_5029_50290024_85_dialog_content = "<color=#828282>呼啦啦——</color>",
  ui_story_5029_50290024_86_dialog_content = "感受清風吹過草叢，又拂過我的髮絲的時刻。",
  ui_story_5029_50290024_87_dialog_content = "感受夕陽的餘暉在雲朵裡作畫的時刻。",
  ui_story_5029_50290024_88_dialog_content = "感受只有我們兩個人，這樣安靜地發呆的時刻。",
  ui_story_5029_50290024_89_dialog_content = "我甚至在想，如果能一直這樣下去也不錯呢。",
  ui_story_5029_50290024_90_dialog_content = "聽起來確實滿不錯，不過......",
  ui_story_5029_50290024_91_dialog_content = "妳想一直崴著腳讓我背著妳走路嗎？",
  ui_story_5029_50290024_92_dialog_content = "唉，虧我剛才還以為你開竅了呢。",
  ui_story_5029_50290024_93_dialog_content = "原來你還是不懂怎麼和女孩子說話......",
  ui_story_5029_50290024_94_dialog_content = "我還是看我的夕陽美景好了。",
  ui_story_5029_50290024_95_dialog_content = "咳咳......我只是想開個玩笑。",
  ui_story_5029_50290024_96_dialog_content = "不然這樣吧？",
  ui_story_5029_50290024_97_dialog_content = "等妳的傷養好了，我們再一起來這裡看日落。",
  ui_story_5029_50290024_98_dialog_content = "說好了，不許反悔喔。",
  ui_story_5029_50290024_99_dialog_content = "誰反悔誰就變成西瓜蟲暗鬼！",
  ui_story_5029_50290024_100_dialog_content = "哈哈哈我才不要呢......",
  ui_story_5029_50290024_101_dialog_content = "（薇絲雖然受了傷，但是這一刻的她似乎比往常更加放鬆和愜意。）",
  ui_story_5029_50290024_102_dialog_content = "（風開始變涼了，順著我的鼻腔灌進胸膛。）",
  ui_story_5029_50290024_103_dialog_content = "（整個世界好像忽然距離我很遙遠，我只能聽見自己的心跳怦怦作響。）",
  ui_story_5029_50290024_104_dialog_content = "（我好像有些期待了......）",
  ui_story_5029_50290024_105_dialog_content = "（那個只屬於我們兩個人之間的祕密約定。）",
  ui_story_5029_50290024_106_dialog_content = "<color=#828282>叮鈴——</color>",
  ui_story_5029_50290024_107_dialog_content = "歡迎回來，我親愛的客人。",
  ui_story_5029_50290024_108_dialog_content = "看到我的臉，讓您感到失望了嗎？",
  ui_story_5029_50290024_109_dialog_content = "抱歉，我不小心看到了屬於你們兩個人的祕密。",
  ui_story_5029_50290024_110_dialog_content = "哦，但您大可不必這樣失望。",
  ui_story_5029_50290024_111_dialog_content = "夢境要依託現實的基礎才能成型。",
  ui_story_5029_50290024_112_dialog_content = "這意味著您與她在現實之中亦有可能經歷相似的情景。",
  ui_story_5029_50290024_113_dialog_content = "不過，與夢境不同的是，現實之中並沒有這樣的把戲。",
  ui_story_5029_50290024_114_dialog_content = "完全生活在這種由我創造出的虛幻之中......那樣多少會有些困難。",
  ui_story_5029_50290024_115_dialog_content = "話說回來，您對這個親筆寫下的結局滿意嗎？",
  ui_story_5029_50290024_116_dialog_content = "不會覺得有那麼一絲缺憾嗎？",
  ui_story_5029_50290024_117_dialog_content = "我想告訴您的是......我們還有時間。",
  ui_story_5029_50290024_118_dialog_content = "前提是，您還想在夢中找到那個謎底、那個答案。",
  ui_story_5029_50290025_1_dialog_content = "PlayerName，你剛才太帥了吧？",
  ui_story_5029_50290025_2_dialog_content = "那個兵大叔一開始那麼兇，結果你只說了幾句話，他就泄氣了！",
  ui_story_5029_50290025_3_dialog_content = "哈哈哈，不就是菲雅的訊號彈不小心彈到他身上了？",
  ui_story_5029_50290025_4_dialog_content = "訊號彈根本沒造成任何傷害，可他非要逮捕我。哼！",
  ui_story_5029_50290025_5_dialog_content = "不管有沒有造成傷害，弄到人家身上就是我們的錯。",
  ui_story_5029_50290025_6_dialog_content = "妳剛才的道歉太敷衍了。",
  ui_story_5029_50290025_7_dialog_content = "等我們找到犯人，妳再去跟人家好好道歉。",
  ui_story_5029_50290025_8_dialog_content = "等抓到犯人再說啦。",
  ui_story_5029_50290025_9_dialog_content = "怎麼樣，你能感應到犯人在哪裡嗎？",
  ui_story_5029_50290025_10_dialog_content = "......沒有，這裡人太多了。",
  ui_story_5029_50290025_11_dialog_content = "也是，港口現在到處都是來參加慶典的人。",
  ui_story_5029_50290025_12_dialog_content = "犯人就是看準了這點，才跑到這麼熱鬧的地方來的。",
  ui_story_5029_50290025_13_dialog_content = "總之，我再試試！",
  ui_story_5029_50290025_14_dialog_content = "嗯，菲雅也不能閒著，我去人群裡找。",
  ui_story_5029_50290025_15_dialog_content = "凱羅，跟我走！",
  ui_story_5029_50290025_16_dialog_content = "欸？凱羅？",
  ui_story_5029_50290025_17_dialog_content = "囉......啵嘰啵嘰。",
  ui_story_5029_50290025_18_dialog_content = "凱羅，你在吃什麼東西啊？",
  ui_story_5029_50290025_19_dialog_content = "啵嘰啵嘰。",
  ui_story_5029_50290025_20_dialog_content = "咿......好噁心喔。",
  ui_story_5029_50290025_21_dialog_content = "凱羅不要吃啦，萬一有毒怎麼辦？",
  ui_story_5029_50290025_22_dialog_content = "哈哈，妳真是少見多怪。",
  ui_story_5029_50290025_23_dialog_content = "這是海藻味的冰淇淋，雖然看起來噁心，但是吃起來解渴又消暑！",
  ui_story_5029_50290025_24_dialog_content = "這種事我，我當然知道了！",
  ui_story_5029_50290025_25_dialog_content = "呃，我的冰淇淋去哪裡了？",
  ui_story_5029_50290025_26_dialog_content = "不對啊，妳的小狗吃的是我的冰淇淋？！",
  ui_story_5029_50290025_27_dialog_content = "這可是我攢了好久的零用錢才買到的，妳賠我！",
  ui_story_5029_50290025_28_dialog_content = "欸，凱羅吃了你的東西嗎？對不起......",
  ui_story_5029_50290025_X28_dialog_content = "別跟我說對不起，妳要是能賠給我五個冰淇淋的錢，我就原諒妳。",
  ui_story_5029_50290025_X29_dialog_content = "可是我身上已經沒有錢了......",
  ui_story_5029_50290025_X30_dialog_content = "沒錢可以把妳的小狗賣掉啊？",
  ui_story_5029_50290025_X31_dialog_content = "我會賠給你的......但是我不會賣掉凱羅，而且凱羅也不是小狗。",
  ui_story_5029_50290025_29_dialog_content = "牠不是小狗，那妳就是小狗！",
  ui_story_5029_50290025_30_dialog_content = "我，我不是......",
  ui_story_5029_50290025_31_dialog_content = "妳就是小狗，偷吃人冰淇淋的小狗！",
  ui_story_5029_50290025_32_dialog_content = "菲雅，送妳一條項鍊。",
  ui_story_5029_50290025_33_dialog_content = "我們覺得妳戴上一定會很好看！",
  ui_story_5029_50290025_34_dialog_content = "真的嗎，謝謝～菲雅這就戴上！",
  ui_story_5029_50290025_35_dialog_content = "大家快來看啊，菲雅戴著狗項圈出門了！",
  ui_story_5029_50290025_36_dialog_content = "菲雅是小狗！菲雅是小狗！",
  ui_story_5029_50290025_37_dialog_content = "菲雅不是......",
  ui_story_5029_50290025_38_dialog_content = "菲雅不是小狗......",
  ui_story_5029_50290025_39_dialog_content = "哭也沒用，小狗快點賠我冰淇淋！",
  ui_story_5029_50290025_40_dialog_content = "喂，小孩子兇什麼兇？",
  ui_story_5029_50290025_41_dialog_content = "有人來撐腰也沒用。",
  ui_story_5029_50290025_42_dialog_content = "我的冰淇淋被她的小狗偷吃了，我才是受害者。",
  ui_story_5029_50290025_X42_dialog_content = "那我替她向你道歉，對不起......",
  ui_story_5029_50290025_43_dialog_content = "給，這些錢夠你買十個冰淇淋了吧？",
  ui_story_5029_50290025_44_dialog_content = "這還差不多......",
  ui_story_5029_50290025_45_dialog_content = "別走，我話還沒說完呢。",
  ui_story_5029_50290025_46_dialog_content = "你明明知道菲雅不是故意的，為什麼還要這樣刁難她？",
  ui_story_5029_50290025_47_dialog_content = "欺負女孩子、讓女孩子哭，算什麼本事？",
  ui_story_5029_50290025_48_dialog_content = "……",
  ui_story_5029_50290025_49_dialog_content = "下次再讓我看見你欺負別人，可就沒有今天這麼幸運了！",
  ui_story_5029_50290025_50_dialog_content = "知道了嗎？",
  ui_story_5029_50290025_51_dialog_content = "知道了......",
  ui_story_5029_50290025_52_dialog_content = "那你發誓不會再有下次了。",
  ui_story_5029_50290025_53_dialog_content = "不會再有下次了。",
  ui_story_5029_50290025_54_dialog_content = "好了，菲雅，沒事了。",
  ui_story_5029_50290025_55_dialog_content = "平時妳天不怕地不怕的，怎麼遇見個小男孩就一句話都說不出來了？",
  ui_story_5029_50290025_56_dialog_content = "這要是讓妳的師父......",
  ui_story_5029_50290025_57_dialog_content = "嗚嗚......！",
  ui_story_5029_50290025_58_dialog_content = "PlayerName，你怎麼現在才來？",
  ui_story_5029_50290025_59_dialog_content = "欸？",
  ui_story_5029_50290025_60_dialog_content = "啊......對不起對不起，是我來晚了。",
  ui_story_5029_50290025_61_dialog_content = "嗚嗚嗚，凱羅不是小狗，菲雅也不是小狗。",
  ui_story_5029_50290025_62_dialog_content = "菲雅知道凱羅不是故意的......誰讓那個男孩把冰淇淋亂放在一邊的嗚嗚嗚。",
  ui_story_5029_50290025_X62_dialog_content = "而且菲雅已經道過歉了......",
  ui_story_5029_50290025_63_dialog_content = "我知道，沒事沒事，都過去了。",
  ui_story_5029_50290025_64_dialog_content = "嗚嗚嗚菲雅最討厭蠻橫不講理的小孩子了！",
  ui_story_5029_50290025_65_dialog_content = "明明自己還是小孩子......",
  ui_story_5029_50290025_66_dialog_content = "菲雅才不是小孩子呢，菲雅早就長大了。",
  ui_story_5029_50290025_67_dialog_content = "而且，而且......",
  ui_story_5029_50290025_68_dialog_content = "菲雅才不會無緣無故地欺負別的小朋友、嘲笑別的小朋友呢嗚嗚嗚。",
  ui_story_5029_50290025_69_dialog_content = "哈哈哈，我知道！但菲雅有時候會欺負一下大朋友倒是真的。",
  ui_story_5029_50290025_70_dialog_content = "才沒有呢！",
  ui_story_5029_50290025_71_dialog_content = "囉！",
  ui_story_5029_50290025_72_dialog_content = "看，凱羅都在擔心妳了。",
  ui_story_5029_50290025_73_dialog_content = "我們找個地方坐下說，好嗎？",
  ui_story_5029_50290025_74_dialog_content = "嗯。",
  ui_story_5029_50290025_75_dialog_content = "如果，我只是說如果，菲雅真的惹你生過氣的話......",
  ui_story_5029_50290025_76_dialog_content = "菲雅跟你道歉......",
  ui_story_5029_50290025_77_option_content = "沒關係的！",
  ui_story_5029_50290025_78_dialog_content = "我一直都知道，菲雅是個好孩子。",
  ui_story_5029_50290025_79_dialog_content = "雖然有時候嘴上不饒人，但是行動上又總是幫著大家、想著大家。",
  ui_story_5029_50290025_80_dialog_content = "這次妳想要得到賞金，不也是為了給師父買禮物嗎？",
  ui_story_5029_50290025_81_dialog_content = "買禮物只是順便的事啦。",
  ui_story_5029_50290025_82_dialog_content = "要不是師父給的旅費不夠，菲雅和凱羅才不會這麼辛苦呢！",
  ui_story_5029_50290025_83_dialog_content = "也不會被路邊的小孩子罵哭......",
  ui_story_5029_50290025_84_dialog_content = "啊，對了，PlayerName你要答應我！",
  ui_story_5029_50290025_85_option_content = "怎麼忽然這麼說？",
  ui_story_5029_50290025_86_dialog_content = "其實......小時候菲雅很渴望和同齡的小朋友一起玩。",
  ui_story_5029_50290025_87_dialog_content = "可是身邊的小朋友總是覺得我很好欺負......久而久之我就變成了大家的笑柄。",
  ui_story_5029_50290025_88_dialog_content = "那個時候，菲雅特別希望自己有個厲害的哥哥。",
  ui_story_5029_50290025_89_dialog_content = "能幫菲雅教訓那幫欺負菲雅的孩子。",
  ui_story_5029_50290025_90_dialog_content = "也渴望自己有一天能夠成為那幫孩子所羨慕的對象。",
  ui_story_5029_50290025_91_dialog_content = "可是……",
  ui_story_5029_50290025_92_dialog_content = "菲雅只能躲在家裡。",
  ui_story_5029_50290025_93_dialog_content = "每次遇見他們，菲雅只能裝作不在意、不在乎。",
  ui_story_5029_50290025_94_dialog_content = "但愈是這樣，那些孩子就愈猖狂。菲雅，菲雅真的好無助......",
  ui_story_5029_50290025_95_dialog_content = "剛才，那個男孩又讓我想起了那段過去。",
  ui_story_5029_50290025_96_dialog_content = "那一刻，我好像又變成了當年那個無助的小孩子。",
  ui_story_5029_50290025_97_dialog_content = "但是今天不一樣，今天，真的有人幫菲雅教訓了欺負菲雅的人！",
  ui_story_5029_50290025_98_dialog_content = "那個人就是你，PlayerName......",
  ui_story_5029_50290025_99_dialog_content = "所以我忍不住在想，如果PlayerName真的是菲雅的哥哥就好了。",
  ui_story_5029_50290025_100_dialog_content = "如果菲雅從小就有PlayerName在身邊保護自己就好了。",
  ui_story_5029_50290025_101_dialog_content = "沒問題啊，我比妳大好幾歲，本來就是妳哥哥嘛。",
  ui_story_5029_50290025_102_dialog_content = "而且菲雅也不是當年無助的小孩子了。",
  ui_story_5029_50290025_103_dialog_content = "妳依靠自己的力量，成為了厲害的神奇動物專家。",
  ui_story_5029_50290025_104_dialog_content = "這可是妳的同齡人難以取得的成就吧？",
  ui_story_5029_50290025_105_dialog_content = "......我不管。",
  ui_story_5029_50290025_106_dialog_content = "總之，你以後也要像今天一樣保護菲雅，不能讓菲雅受一點委屈！",
  ui_story_5029_50290025_107_dialog_content = "好，我答應你。",
  ui_story_5029_50290025_108_dialog_content = "一言為定？",
  ui_story_5029_50290025_109_dialog_content = "嗯，一言為定！",
  ui_story_5029_50290025_110_dialog_content = "PlayerName，哥哥......",
  ui_story_5029_50290025_111_dialog_content = "做哥哥的第一個任務就是——",
  ui_story_5029_50290025_112_dialog_content = "不能讓別人知道菲雅今天哭過的事情！",
  ui_story_5029_50290025_113_dialog_content = "否則菲雅又要被人笑話了。",
  ui_story_5029_50290025_114_dialog_content = "我答應妳，絕對不會告訴別人。",
  ui_story_5029_50290025_115_dialog_content = "呼～好累......",
  ui_story_5029_50290025_116_dialog_content = "那當然了，號啕大哭可是件體力活呢。",
  ui_story_5029_50290025_117_dialog_content = "結果......到最後。",
  ui_story_5029_50290025_118_dialog_content = "還是沒有......抓到，犯人。",
  ui_story_5029_50290025_119_dialog_content = "沒關係，至少我們找回了銀盒。",
  ui_story_5029_50290025_120_dialog_content = "呼......呼......呼......",
  ui_story_5029_50290025_121_dialog_content = "這孩子，坐著都能睡著嗎？",
  ui_story_5029_50290025_122_dialog_content = "（熙熙攘攘的人潮之中，菲雅睡得很香甜。）",
  ui_story_5029_50290025_123_dialog_content = "（被菲雅的淚水浸濕的衣角，在夕陽之下慢慢晾乾。）",
  ui_story_5029_50290025_124_dialog_content = "（如果我有妹妹，或許現在也像菲雅一般大吧？）",
  ui_story_5029_50290025_125_dialog_content = "<color=#828282>叮鈴——</color>",
  ui_story_5029_50290025_126_dialog_content = "歡迎回來，我親愛的客人。",
  ui_story_5029_50290025_127_dialog_content = "看到我的臉，讓您感到失望了嗎？",
  ui_story_5029_50290025_128_dialog_content = "抱歉，我不小心看到了屬於你們兩個人的祕密。",
  ui_story_5029_50290025_129_dialog_content = "哦，但您大可不必這樣失望。",
  ui_story_5029_50290025_130_dialog_content = "夢境要依託現實的基礎才能成型。",
  ui_story_5029_50290025_131_dialog_content = "這意味著您與她在現實之中亦有可能經歷相似的情景。",
  ui_story_5029_50290025_132_dialog_content = "不過，與夢境不同的是，現實之中並沒有這樣的把戲。",
  ui_story_5029_50290025_133_dialog_content = "完全生活在這種由我創造出的虛幻之中......那樣多少會有些困難。",
  ui_story_5029_50290025_134_dialog_content = "話說回來，您對這個親筆寫下的結局滿意嗎？",
  ui_story_5029_50290025_135_dialog_content = "不會覺得有那麼一絲缺憾嗎？",
  ui_story_5029_50290025_136_dialog_content = "我想告訴您的是......我們還有時間。",
  ui_story_5029_50290025_137_dialog_content = "前提是，您還想在夢中找到那個謎底、那個答案。",
  ui_story_5029_50290026_1_dialog_content = "（嗯......）",
  ui_story_5029_50290026_2_dialog_content = "（這裡是......領主的書樓。）",
  ui_story_5029_50290026_3_dialog_content = "（我怎麼又回來了？）",
  ui_story_5029_50290026_4_dialog_content = "（奇怪，我為什麼說「又回來」了呢。）",
  ui_story_5029_50290026_5_dialog_content = "接下來各位偵探大人可以在這間房子裡自由地調查。",
  ui_story_5029_50290026_6_dialog_content = "有什麼問題可以隨時來問我，我就在大廳待命。",
  ui_story_5029_50290026_7_dialog_content = "（這句話，好像聽過很多次了......）",
  ui_story_5029_50290026_8_option_content = "找贊恩",
  ui_story_5029_50290026_9_option_content = "隨便逛逛",
  ui_story_5029_50290026_10_dialog_content = "（不對！）",
  ui_story_5029_50290026_11_dialog_content = "（現在不是做這種選擇的時候。）",
  ui_story_5029_50290026_12_dialog_content = "（如果這樣發展下去，我們一定找不到真正的犯人。）",
  ui_story_5029_50290026_13_dialog_content = "（如果找不到犯人，領主也許會遇到危險......我也會被永遠困在這裡。）",
  ui_story_5029_50290026_14_dialog_content = "（嗯？會被困在這裡？我在說什麼？總之......）",
  ui_story_5029_50290026_15_option_content = "大家快過來！",
  ui_story_5029_50290026_16_option_content = "卡蓮、薇絲、菲雅！",
  ui_story_5029_50290026_17_dialog_content = "PlayerName，你怎麼忽然這麼大聲？",
  ui_story_5029_50290026_18_dialog_content = "是找到什麼線索了嗎？",
  ui_story_5029_50290026_19_dialog_content = "有什麼事快點說喔！我感覺我距離重要的線索只有一步之遙了。",
  ui_story_5029_50290026_20_dialog_content = "這個案子不是遊戲，也不是競賽。",
  ui_story_5029_50290026_21_dialog_content = "我希望我們可以合作，一起調查！",
  ui_story_5029_50290026_22_dialog_content = "為什麼呀，那樣獎金不就要被分走了嘛。",
  ui_story_5029_50290026_23_dialog_content = "PlayerName，如果你找不到偵探搭檔，可以隨時來找我呀。",
  ui_story_5029_50290026_24_dialog_content = "我不會嫌棄你的。",
  ui_story_5029_50290026_25_dialog_content = "大家聽我說，時間真的不多了......",
  ui_story_5029_50290026_26_dialog_content = "如果我們不能合作抓住犯人，後果會很嚴重。",
  ui_story_5029_50290026_27_dialog_content = "這一點不用你說我們也知道。",
  ui_story_5029_50290026_28_dialog_content = "請大家相信我，我有一種預感。",
  ui_story_5029_50290026_29_dialog_content = "犯人很快就會帶著銀盒逃跑，僅憑一兩個人的力量沒辦法抓住他。",
  ui_story_5029_50290026_30_dialog_content = "我們必須在那之前鎖定犯人的身分，採取行動！",
  ui_story_5029_50290026_31_dialog_content = "可是......我們為什麼要相信你的預感啊？",
  ui_story_5029_50290026_32_dialog_content = "菲雅，妳最好不要讓凱羅靠近咖啡廳的地板角落。",
  ui_story_5029_50290026_33_dialog_content = "那裡有一把沾滿草莓醬的小刀，如果不小心的話會被割傷。",
  ui_story_5029_50290026_34_dialog_content = "是，是這樣嗎？",
  ui_story_5029_50290026_35_dialog_content = "卡蓮，二樓的書桌上有一本古籍很破舊。",
  ui_story_5029_50290026_36_dialog_content = "如果拿起來看的話，很可能會撕碎古籍，難以向領主交代。",
  ui_story_5029_50290026_37_dialog_content = "哦？",
  ui_story_5029_50290026_38_dialog_content = "薇絲，大廳裡那盆妳覺得很漂亮的花有毒，最好不要靠近它。",
  ui_story_5029_50290026_39_dialog_content = "不過只要不吃進肚子裡就沒事。",
  ui_story_5029_50290026_40_dialog_content = "欸？你怎麼知道我想去看看那盆花的？",
  ui_story_5029_50290026_41_dialog_content = "就是，就是有那種預感。",
  ui_story_5029_50290026_42_dialog_content = "你是不是趁我們不注意，搜查了整座房子？",
  ui_story_5029_50290026_43_dialog_content = "也......也許吧。",
  ui_story_5029_50290026_44_dialog_content = "既然如此，想必你已經有個十全十美的合作方案了吧？",
  ui_story_5029_50290026_45_dialog_content = "十全十美算不上，但大家可以按我說的去做......",
  ui_story_5029_50290026_46_dialog_content = "<color=#828282>過了一段時間</color>",
  ui_story_5029_50290026_47_dialog_content = "真的被PlayerName說中了，那個來洽談的商人果然是狡木。",
  ui_story_5029_50290026_48_dialog_content = "按PlayerName交代的那樣，我答應他會安排他與領主再次見面。",
  ui_story_5029_50290026_49_dialog_content = "他便一五一十地交代了！",
  ui_story_5029_50290026_50_dialog_content = "我看見領主鎖上門離開，就偷偷撬開鎖進去了。",
  ui_story_5029_50290026_51_dialog_content = "說句題外話，我的撬鎖技術，在紅油扳手裡也算得上一流。",
  ui_story_5029_50290026_52_dialog_content = "把好幾本《赤浪醒之助專》放在了最顯眼的地方後，我就走了。",
  ui_story_5029_50290026_53_dialog_content = "嗯，接著就是白夜城的公爵大人——貝芙麗。她說......",
  ui_story_5029_50290026_54_dialog_content = "我等了半天，發現一個綠色頭髮的小個子從書樓裡出來了。",
  ui_story_5029_50290026_55_dialog_content = "確定周圍沒人之後，我就進去尋找我遺失的徽章。",
  ui_story_5029_50290026_56_dialog_content = "但是找了很久都沒有找到。後來我聽到好像有別人來了，就離開了。",
  ui_story_5029_50290026_57_dialog_content = "貝芙麗說的別人就是「真枝」吧？唔，就是你們口中的「早苗」，她說......",
  ui_story_5029_50290026_58_dialog_content = "我，我看見門沒鎖，就悄悄地進去了。",
  ui_story_5029_50290026_59_dialog_content = "我把被我藏在沙發下面的花瓶碎片打掃乾淨，還擺上了新的花瓶。",
  ui_story_5029_50290026_60_dialog_content = "本以為誰都不會發現，結果還是被庫克先生發現了......",
  ui_story_5029_50290026_61_dialog_content = "庫克先生答應我不會告發我，還交代我鎖好門窗。",
  ui_story_5029_50290026_62_dialog_content = "所以領主回來的時候，才會發現門鎖是鎖好的......",
  ui_story_5029_50290026_63_dialog_content = "他們進出書樓的順序沒有錯。",
  ui_story_5029_50290026_64_dialog_content = "我剛才找到了三個目擊證人，他們也能證實。",
  ui_story_5029_50290026_65_dialog_content = "領主鎖上門之後沒多久，綠頭髮哥哥就又回來了。",
  ui_story_5029_50290026_66_dialog_content = "我確實在晚飯時間，看到一位漂亮的貴族小姐。",
  ui_story_5029_50290026_67_dialog_content = "我看到「真枝」悄悄去了領主的書房，非常可疑。",
  ui_story_5029_50290026_68_dialog_content = "PlayerName你今天的預感都太準了吧？",
  ui_story_5029_50290026_69_dialog_content = "不僅猜到了三個人的真實身分，連目擊者都能找到！",
  ui_story_5029_50290026_70_dialog_content = "雖然問出了這些，但是實際上我們又回到了原點。",
  ui_story_5029_50290026_71_dialog_content = "三個人雖然都悄悄回過書樓，但都是前後相連的。",
  ui_story_5029_50290026_72_dialog_content = "這樣的話，犯人還是只能在他們三個人之中......",
  ui_story_5029_50290026_73_dialog_content = "但是PlayerName看起來並不想懷疑這三個人。",
  ui_story_5029_50290026_74_dialog_content = "唉，就沒有出現第四個人嗎？",
  ui_story_5029_50290026_75_dialog_content = "第四個人......？",
  ui_story_5029_50290026_76_dialog_content = "有這個可能。",
  ui_story_5029_50290026_77_dialog_content = "比如有個人一直在我們的身邊，導致我們沒有懷疑過他。",
  ui_story_5029_50290026_78_dialog_content = "菲雅，昨天凱羅有沒有偷吃什麼金屬製品呀？",
  ui_story_5029_50290026_79_dialog_content = "囉囉囉？",
  ui_story_5029_50290026_80_dialog_content = "凱羅才沒有那麼傻呢！",
  ui_story_5029_50290026_81_dialog_content = "我看犯人就是贊恩大叔吧？",
  ui_story_5029_50290026_82_dialog_content = "贊恩？怎麼可能？",
  ui_story_5029_50290026_83_dialog_content = "愈是不可能的人，就愈有可能！",
  ui_story_5029_50290026_84_dialog_content = "嚴絲合縫的邏輯鏈條裡，只要有一環扣不上，整個鏈條就無法轉動。",
  ui_story_5029_50290026_85_dialog_content = "一定是有哪個地方被遺漏了。",
  ui_story_5029_50290026_86_dialog_content = "一個已經看到過，但是卻被我們忽略的地方......",
  ui_story_5029_50290026_87_dialog_content = "喂，你們不打算盤問一下贊恩嗎？",
  ui_story_5029_50290026_88_dialog_content = "不會只有我一個人覺得他很可疑吧？",
  ui_story_5029_50290026_89_dialog_content = "可疑......",
  ui_story_5029_50290026_90_dialog_content = "早苗？",
  ui_story_5029_50290026_91_dialog_content = "PlayerName，你又覺得早苗可疑了嗎？",
  ui_story_5029_50290026_92_dialog_content = "不是我......",
  ui_story_5029_50290026_93_dialog_content = "是有一個人一直在對我刻意強調這件事。",
  ui_story_5029_50290026_94_dialog_content = "囉！",
  ui_story_5029_50290026_95_dialog_content = "凱羅，你在窗邊看什麼呢？",
  ui_story_5029_50290026_96_dialog_content = "外面只有幾棵樹而已啦......",
  ui_story_5029_50290026_97_dialog_content = "（糟了，他已經行動了嗎？）",
  ui_story_5029_50290026_98_dialog_content = "欸？大家快看，外面那個人好奇怪啊！",
  ui_story_5029_50290027_1_dialog_content = "（還是沒能趕上嗎......）",
  ui_story_5029_50290027_2_dialog_content = "（不，還有機會！）",
  ui_story_5029_50290027_3_dialog_content = "（大家團結在一起，這次一定可以的！）",
  ui_story_5029_50290027_4_dialog_content = "（深呼吸......快想辦法，想一個抓住犯人的辦法......）",
  ui_story_5029_50290027_5_dialog_content = "那個人確實很奇怪欸，這麼熱的天捂得那麼嚴實。",
  ui_story_5029_50290027_6_dialog_content = "他好像在挖什麼東西？",
  ui_story_5029_50290027_7_dialog_content = "（挖東西......）",
  ui_story_5029_50290027_8_dialog_content = "（原來如此......原來他一直把東西埋在後花園裡？）",
  ui_story_5029_50290027_9_dialog_content = "大家聽我說！那個人就是偷走銀盒的犯人。",
  ui_story_5029_50290027_10_dialog_content = "他正在挖被他埋藏在後花園的銀盒，然後準備逃跑。",
  ui_story_5029_50290027_11_dialog_content = "那還等什麼呀，我們快去抓住他！",
  ui_story_5029_50290027_12_dialog_content = "菲雅，等等。",
  ui_story_5029_50290027_13_dialog_content = "PlayerName，準備好指揮了嗎？",
  ui_story_5029_50290027_14_dialog_content = "大家......？",
  ui_story_5029_50290027_15_dialog_content = "不是你讓我們幾個合作的嗎？",
  ui_story_5029_50290027_16_dialog_content = "雖然不是與暗鬼對抗，但是要論指揮團隊，還是你最熟悉呢。",
  ui_story_5029_50290027_17_dialog_content = "嗯……好！",
  ui_story_5029_50290027_18_dialog_content = "菲雅，妳先帶著凱羅去堵住通向後山的路。",
  ui_story_5029_50290027_19_dialog_content = "如果讓他順著山路逃跑，我們要追起來就麻煩多了。",
  ui_story_5029_50290027_20_dialog_content = "瞭解！",
  ui_story_5029_50290027_21_dialog_content = "薇絲、卡蓮，分別從左側和右側出發。",
  ui_story_5029_50290027_22_dialog_content = "記得帶上武器，以備不時之需。",
  ui_story_5029_50290027_23_dialog_content = "我會直接從後面追，防止他順原路返回。",
  ui_story_5029_50290027_24_dialog_content = "好的！",
  ui_story_5029_50290027_25_dialog_content = "這一次......一定不會再讓你跑掉了！",
  ui_story_5029_50290027_26_dialog_content = "情況如何？",
  ui_story_5029_50290027_27_dialog_content = "計畫成功！犯人向著港口的方向逃跑了。",
  ui_story_5029_50290027_28_dialog_content = "呼哧......他跑得太快了。",
  ui_story_5029_50290027_29_dialog_content = "沒關係，菲雅帶了訊號槍！",
  ui_story_5029_50290027_30_dialog_content = "凱羅，我把訊號標記到哪個人身上，你就去攔住他，別讓他帶走銀盒。",
  ui_story_5029_50290027_31_dialog_content = "囉！",
  ui_story_5029_50290027_32_dialog_content = "奇怪，我怎麼覺得自己好像在哪裡說過同樣的話。",
  ui_story_5029_50290027_33_dialog_content = "不管了......菲雅的致命訊號攻擊——嗶唷！",
  ui_story_5029_50290027_34_dialog_content = "……？",
  ui_story_5029_50290027_35_dialog_content = "嚕......囉！！！",
  ui_story_5029_50290027_36_dialog_content = "就是這樣，凱羅，追上他狠狠咬住他的手！",
  ui_story_5029_50290027_37_dialog_content = "囉囉囉！",
  ui_story_5029_50290027_38_dialog_content = "哎呀......犯人把銀盒朝著凱羅扔過去了。",
  ui_story_5029_50290027_39_dialog_content = "凱羅，小心啊！",
  ui_story_5029_50290027_40_dialog_content = "<color=#828282>咚！</color>",
  ui_story_5029_50290027_41_dialog_content = "啊......這盒子還真重呢。",
  ui_story_5029_50290027_42_dialog_content = "太好了，薇絲姐姐替凱羅接住銀盒了。",
  ui_story_5029_50290027_43_dialog_content = "凱羅，好好保管銀盒。接下來就交給我和卡蓮吧。",
  ui_story_5029_50290027_44_dialog_content = "薇絲快跟上來，犯人已經跑遠了。",
  ui_story_5029_50290027_45_dialog_content = "沒關係，遠距離狙擊可是我的拿手好戲～",
  ui_story_5029_50290027_46_dialog_content = "目標追蹤！",
  ui_story_5029_50290027_47_dialog_content = "唔……",
  ui_story_5029_50290027_48_dialog_content = "哇！薇絲姐姐太厲害了，犯人一下子就被擊倒在地上啦。",
  ui_story_5029_50290027_49_dialog_content = "......薇絲是不是怕傷到犯人所以減弱了攻擊力？",
  ui_story_5029_50290027_50_dialog_content = "犯人好像又要站起來了？",
  ui_story_5029_50290027_51_dialog_content = "他逃不掉的，卡蓮姐姐已經追上他了！",
  ui_story_5029_50290027_52_dialog_content = "死到臨頭，還想逃跑嗎？",
  ui_story_5029_50290027_53_dialog_content = "什麼？！",
  ui_story_5029_50290027_54_dialog_content = "長槍之下，焉有陰影！",
  ui_story_5029_50290027_55_dialog_content = "呃唔......",
  ui_story_5029_50290027_56_dialog_content = "終於。",
  ui_story_5029_50290027_57_dialog_content = "終於抓住犯人了嗎......",
  ui_story_5029_50290027_58_dialog_content = "薇絲，合作愉快。",
  ui_story_5029_50290027_59_dialog_content = "哈哈，合作愉快喔。",
  ui_story_5029_50290027_60_dialog_content = "剛才距離那麼遠，妳都能這樣精準地射中犯人，實在是精彩。",
  ui_story_5029_50290027_61_dialog_content = "但他實在是跑得太快了......",
  ui_story_5029_50290027_62_dialog_content = "還好我們有白夜城的衛隊長——卡蓮。",
  ui_story_5029_50290027_63_dialog_content = "有妳在，什麼樣的犯人都休想逃跑。",
  ui_story_5029_50290027_64_dialog_content = "打住打住，妳再說下去我都要起雞皮疙瘩了。",
  ui_story_5029_50290027_65_dialog_content = "我是在誇妳，這有什麼不好意思的。",
  ui_story_5029_50290027_66_dialog_content = "妳剛才誇我的話我可是照單全收了喔。",
  ui_story_5029_50290027_67_dialog_content = "薇絲姐姐、卡蓮姐姐，等等我......還有我呢！",
  ui_story_5029_50290027_68_dialog_content = "當然不會忘了妳喔。",
  ui_story_5029_50290027_69_dialog_content = "擋住通往後山道路的菲雅也功不可沒。",
  ui_story_5029_50290027_70_dialog_content = "嘿嘿嘿，菲雅也功不可沒嗎......",
  ui_story_5029_50290027_71_dialog_content = "不過，我們也不能忘了最重要的那個人呢。",
  ui_story_5029_50290027_72_dialog_content = "要不是他，我們也許根本不知道後花園裡那個奇怪的人就是犯人。",
  ui_story_5029_50290027_73_dialog_content = "凱羅，薇絲姐姐和卡蓮姐姐在說你呢！",
  ui_story_5029_50290027_74_dialog_content = "囉？",
  ui_story_5029_50290027_75_dialog_content = "咳咳，說的是呢。",
  ui_story_5029_50290027_76_dialog_content = "凱羅也辛苦啦，晚上帶凱羅吃好吃的喔！",
  ui_story_5029_50290027_77_dialog_content = "囉囉囉！",
  ui_story_5029_50290027_78_dialog_content = "欸，PlayerName在和犯人說什麼啊？",
  ui_story_5029_50290027_79_dialog_content = "真的是你嗎？",
  ui_story_5029_50290027_80_dialog_content = "哼。",
  ui_story_5029_50290027_81_dialog_content = "所以你才會千方百計地讓我懷疑別人。",
  ui_story_5029_50290027_82_dialog_content = "你所有的偽裝都只是為了偷這個東西嗎？",
  ui_story_5029_50290027_83_dialog_content = "……",
  ui_story_5029_50290027_84_dialog_content = "PlayerName，今天多謝有你出謀劃策。",
  ui_story_5029_50290027_85_dialog_content = "對呀。",
  ui_story_5029_50290027_85X1_dialog_content = "要不是你在關鍵時刻讓大家團結起來，我們還真的抓不到這個狡猾的犯人呢。",
  ui_story_5029_50290027_86_dialog_content = "可我還是很好奇，當時我們只是覺得後花園裡的人很奇怪......",
  ui_story_5029_50290027_87_dialog_content = "你怎麼知道他就是偷走銀盒的犯人？不會又是你的預感吧？",
  ui_story_5029_50290027_88_dialog_content = "經歷的事情多了，總會長點教訓的。",
  ui_story_5029_50290027_89_dialog_content = "嗯？",
  ui_story_5029_50290027_90_dialog_content = "菲雅還是很好奇，這個犯人究竟是誰啊？會不會就是贊恩？！",
  ui_story_5029_50290027_91_dialog_content = "剛才PlayerName還說在懷疑早苗。",
  ui_story_5029_50290027_92_dialog_content = "這個人雖然還沒有摘下面罩，但是看起來絕對不是早苗吧？",
  ui_story_5029_50290027_93_dialog_content = "故意讓我懷疑早苗的......就是這個犯人。",
  ui_story_5029_50290027_94_dialog_content = "領主家的男僕，早苗進入書樓的目擊者——",
  ui_story_5029_50290027_95_dialog_content = "庫克。",
  ui_story_5029_50290027_96_dialog_content = "……",
  ui_story_5029_50290028_1_dialog_content = "庫克？",
  ui_story_5029_50290028_2_dialog_content = "早苗提到過這個名字。",
  ui_story_5029_50290028_3_dialog_content = "庫克當時還交代早苗鎖好門窗呢，聽起來是個不錯的大叔啊？",
  ui_story_5029_50290028_4_dialog_content = "早苗有沒有說過，是在哪裡遇見庫克的？",
  ui_story_5029_50290028_5_dialog_content = "應該就是在書樓裡......欸？",
  ui_story_5029_50290028_6_dialog_content = "沒錯，庫克就是進入書樓的第四個人。",
  ui_story_5029_50290028_7_dialog_content = "我犯了一個不該犯的錯誤——在潛意識裡把目擊者當成了無辜的人。",
  ui_story_5029_50290028_8_dialog_content = "你們是說這個被你們捆住的犯人是庫克？",
  ui_story_5029_50290028_9_dialog_content = "哇，領主大叔也來了！",
  ui_story_5029_50290028_10_dialog_content = "我只是在敘述我未完成的推理。",
  ui_story_5029_50290028_11_dialog_content = "其實我們還沒有解開犯人的面罩......",
  ui_story_5029_50290028_12_dialog_content = "無妨，我也很想聽聽PlayerName的推理。",
  ui_story_5029_50290028_13_dialog_content = "如果我沒猜錯的話......",
  ui_story_5029_50290028_14_dialog_content = "<color=#828282>吱呀——</color>",
  ui_story_5029_50290028_15_dialog_content = "有人來了？",
  ui_story_5029_50290028_16_dialog_content = "我還是改日再來尋找吧。",
  ui_story_5029_50290028_17_dialog_content = "哈哈哈哈哈，天助我也。",
  ui_story_5029_50290028_18_dialog_content = "本來只是想送個報紙，沒想到領主不在，書樓也沒鎖。",
  ui_story_5029_50290028_19_dialog_content = "領主的寶貝今天就是我的了！",
  ui_story_5029_50290028_20_dialog_content = "<color=#828282>吱呀——</color>",
  ui_story_5029_50290028_21_dialog_content = "誰來了？！",
  ui_story_5029_50290028_22_dialog_content = "是她？呵呵，這姑娘應該很好糊弄。",
  ui_story_5029_50290028_23_dialog_content = "可是不能讓她看到我抱著銀盒。",
  ui_story_5029_50290028_24_dialog_content = "先把銀盒從窗戶扔出去，等一下再去撿好了。",
  ui_story_5029_50290028_25_dialog_content = "<color=#828282>咚！</color>",
  ui_story_5029_50290028_26_dialog_content = "（嘶......倒霉！竟然不小心撞到了窗戶旁的沙漠植物。）",
  ui_story_5029_50290028_27_dialog_content = "欸，什麼聲音？",
  ui_story_5029_50290028_28_dialog_content = "這麼晚了妳一個人在領主的書樓裡幹什麼？",
  ui_story_5029_50290028_29_dialog_content = "我、我……",
  ui_story_5029_50290028_30_dialog_content = "是不是又把領主的東西打碎了？",
  ui_story_5029_50290028_31_dialog_content = "我買了新的過來，不會給大家造成任何損失的......",
  ui_story_5029_50290028_32_dialog_content = "求求您，不要告訴領主大人和女僕長。",
  ui_story_5029_50290028_33_dialog_content = "否則，我會被開除的......",
  ui_story_5029_50290028_34_dialog_content = "嗯......既然妳賠了新的，估計沒人會發現的。",
  ui_story_5029_50290028_35_dialog_content = "欸？",
  ui_story_5029_50290028_36_dialog_content = "我會當做沒見過妳。",
  ui_story_5029_50290028_37_dialog_content = "不過，妳可要記得把這裡的門窗鎖好囉。",
  ui_story_5029_50290028_38_dialog_content = "所以，在貝芙麗之後來的人並不是早苗，而是庫克！",
  ui_story_5029_50290028_39_dialog_content = "那個傻妞，最後還擦了一遍地板，把我的腳印也擦沒了。",
  ui_story_5029_50290028_40_dialog_content = "哈哈哈哈哈，這本來該是多麼完美啊！",
  ui_story_5029_50290028_41_dialog_content = "這個聲音……",
  ui_story_5029_50290028_42_dialog_content = "……",
  ui_story_5029_50290028_43_dialog_content = "庫克，真的是你？！",
  ui_story_5029_50290028_44_dialog_content = "PlayerName說對了！PlayerName是真的神探吧？",
  ui_story_5029_50290028_45_dialog_content = "如果我今天沒有急著逃跑，你們永遠都不會知道是我！",
  ui_story_5029_50290028_46_dialog_content = "不，你還是留下了把柄！",
  ui_story_5029_50290028_47_dialog_content = "不可能！",
  ui_story_5029_50290028_48_dialog_content = "你是不是忘了咖啡廳的報紙？",
  ui_story_5029_50290028_49_dialog_content = "領主昨天一天都在會客，沒有收到過你送去的報紙。",
  ui_story_5029_50290028_50_dialog_content = "但是那份昨天剛出版的報紙怎麼會出現在咖啡廳呢？",
  ui_story_5029_50290028_51_dialog_content = "……",
  ui_story_5029_50290028_52_dialog_content = "我第一次見你的時候就覺得奇怪。",
  ui_story_5029_50290028_53_dialog_content = "腿腳不好、行動不便的人，鞋子上為什麼會有泥土？",
  ui_story_5029_50290028_54_dialog_content = "現在想想，你是為了避嫌，連夜把銀盒埋進了後花園裡。",
  ui_story_5029_50290028_54X1_dialog_content = "所以鞋上才會沾上泥土。",
  ui_story_5029_50290028_55_dialog_content = "有這些證據，找出你只是時間問題。",
  ui_story_5029_50290028_56_dialog_content = "可惜......如果再早一點推理出來，就不用這麼大動干戈了。",
  ui_story_5029_50290028_57_dialog_content = "庫克，你腿上的傷不是還沒有好嗎？",
  ui_story_5029_50290028_58_dialog_content = "問我的第一個問題竟然是這個嗎？",
  ui_story_5029_50290028_59_dialog_content = "哼，要不是因為恨你，我的腿好得也不會那麼快。",
  ui_story_5029_50290028_60_dialog_content = "告訴你吧！平時我裝作腿腳不便，就是為了偷走你的寶貝之後不被人懷疑。",
  ui_story_5029_50290028_61_dialog_content = "我不明白，你為什麼要做這種事......",
  ui_story_5029_50290028_62_dialog_content = "如果你需要用錢，完全可以告訴我。",
  ui_story_5029_50290028_63_dialog_content = "不要在這裡假慈悲了，這根本不是錢的問題！",
  ui_story_5029_50290028_64_dialog_content = "我只是想要奪走你最寶貝的東西，讓你嚐嚐這種失去的滋味罷了。",
  ui_story_5029_50290028_65_dialog_content = "庫克，領主大人明明沒有任何對不起你的地方。",
  ui_story_5029_50290028_66_dialog_content = "你受傷之後也讓你好好地休養，你為什麼要這麼對領主大人？",
  ui_story_5029_50290028_67_dialog_content = "呵，哈哈哈哈哈。",
  ui_story_5029_50290028_68_dialog_content = "我家世代追隨領主，為領主一族當牛做馬。",
  ui_story_5029_50290028_69_dialog_content = "我也沒有任何對不起你們的地方。可是你呢？",
  ui_story_5029_50290028_70_dialog_content = "去年我為了救你，墜下懸崖摔傷了腿。",
  ui_story_5029_50290028_71_dialog_content = "很快，你就找贊恩填補了我的職位。",
  ui_story_5029_50290028_72_dialog_content = "而我，卻只能幫女僕們做些雜事......這我也就忍了。",
  ui_story_5029_50290028_73_dialog_content = "可是你居然還打算把我像隻野狗一樣趕出家門？",
  ui_story_5029_50290028_74_dialog_content = "我不會那樣做的。",
  ui_story_5029_50290028_75_dialog_content = "我親耳聽到的！你告訴女僕長說等我走了，可以把我的住處讓給贊恩......",
  ui_story_5029_50290028_76_dialog_content = "我家世世代代忠誠護主，得到的就是這種下場嗎？",
  ui_story_5029_50290028_77_dialog_content = "你誤會領主大人的好心了......",
  ui_story_5029_50290028_78_dialog_content = "贊恩，別急！你遲早也會像我一樣哈哈哈哈。",
  ui_story_5029_50290028_79_dialog_content = "唉。",
  ui_story_5029_50290028_80_dialog_content = "領主大人，他說的是真的嗎......？",
  ui_story_5029_50290028_81_dialog_content = "是真的，也不是真的。",
  ui_story_5029_50290028_82_dialog_content = "庫克，你以前擅長跑步，而受傷以後卻可能一輩子無法好好走路。",
  ui_story_5029_50290028_83_dialog_content = "因此我一直都覺得對不起你。",
  ui_story_5029_50290028_84_dialog_content = "你是個忠心勇猛的人，更是個聰慧果敢的人。",
  ui_story_5029_50290028_85_dialog_content = "如果你不是被困在我家的宅子裡，大可以在商界闖出一片天地。",
  ui_story_5029_50290028_86_dialog_content = "於是我就想著給你籌備一筆啟動資金，幫助你出去闖一闖。",
  ui_story_5029_50290028_87_dialog_content = "可惜，我還沒來得及告訴你......",
  ui_story_5029_50290028_88_dialog_content = "你在胡說八道什麼？！",
  ui_story_5029_50290028_89_dialog_content = "不......不可能！",
  ui_story_5029_50290028_90_dialog_content = "你的意思是，我誤會了你？",
  ui_story_5029_50290028_91_dialog_content = "怎麼可能！",
  ui_story_5029_50290028_92_dialog_content = "你這段時間以來連看都不看我一眼，怎麼可能為我這種人考慮這麼多？",
  ui_story_5029_50290028_93_dialog_content = "別以為這種謊話能騙得過我！",
  ui_story_5029_50290028_94_dialog_content = "你只不過是在給自己開脫。",
  ui_story_5029_50290028_95_dialog_content = "對啊，因為你當著白夜城公主的面，不敢承認吧？",
  ui_story_5029_50290028_96_dialog_content = "所以你才找了一個狗屁不通的解釋吧？啊？",
  ui_story_5029_50290028_97_dialog_content = "領主說的都是真的，我可以作證！",
  ui_story_5029_50290028_98_dialog_content = "你閉嘴！",
  ui_story_5029_50290028_99_dialog_content = "想不到我也有看人看走眼的時候。",
  ui_story_5029_50290028_100_dialog_content = "妳……",
  ui_story_5029_50290028_101_dialog_content = "你心胸狹隘，可能的確不適合去經商。",
  ui_story_5029_50290028_102_dialog_content = "我要走哪條路用不著你來評判！",
  ui_story_5029_50290028_103_dialog_content = "我費心費力服侍你這麼多年，沒想到現在你還是要騙我......",
  ui_story_5029_50290028_104_dialog_content = "哼，哈哈哈哈哈！",
  ui_story_5029_50290028_105_dialog_content = "傻子才會相信你的滿口胡言！",
  ui_story_5029_50290028_106_dialog_content = "呸！",
  ui_story_5029_50290028_107_dialog_content = "你......你遲早會後悔的。",
  ui_story_5029_50290028_108_dialog_content = "這裡的人開始變多了。",
  ui_story_5029_50290028_109_dialog_content = "贊恩，你先帶庫克回去吧。",
  ui_story_5029_50290028_110_dialog_content = "是！",
  ui_story_5029_50290028_111_dialog_content = "領主大人，我很抱歉......",
  ui_story_5029_50290028_112_dialog_content = "無論如何，多謝大家幫我找回銀盒和庫克。",
  ui_story_5029_50290028_113_dialog_content = "啊，這個盒子還給您。",
  ui_story_5029_50290028_114_dialog_content = "鎖好像有點摔壞了，您看看裡面的東西有沒有少。",
  ui_story_5029_50290028_115_dialog_content = "有勞了。",
  ui_story_5029_50290028_116_dialog_content = "<color=#828282>喀嗒。</color>",
  ui_story_5029_50290028_117_dialog_content = "不錯，東西還在。",
  ui_story_5029_50290028_118_dialog_content = "<color=#828282>呼——</color>",
  ui_story_5029_50290028_119_dialog_content = "啊，有個東西被風吹出來了。",
  ui_story_5029_50290028_120_dialog_content = "我去撿回來！",
  ui_story_5029_50290028_121_dialog_content = "欸，這是......",
  ui_story_5029_50290028_122_dialog_content = "一張舊畫像罷了。",
  ui_story_5029_50290028_123_dialog_content = "既然被放在你最寶貴的盒子裡面......這張畫像對你來說應該很珍貴吧？",
  ui_story_5029_50290028_124_dialog_content = "嗯。",
  ui_story_5029_50290028_125_dialog_content = "不過我永遠也回不去了......",
  ui_story_5029_50290028_126_dialog_content = "不說這個了。",
  ui_story_5029_50290028_127_dialog_content = "PlayerName、卡蓮大人、薇絲小姐還有菲雅小姐，謝謝各位。",
  ui_story_5029_50290028_128_dialog_content = "若是不嫌棄，今晚我會在家裡安排好泊城的特色晚宴，請各位務必前來。",
  ui_story_5029_50290028_129_dialog_content = "唔，還以為銀盒裡面會放什麼更值錢的東西呢。",
  ui_story_5029_50290028_130_dialog_content = "原來只是一張畫像啊，真搞不懂。",
  ui_story_5029_50290028_131_dialog_content = "如果是菲雅的話，是不是會把妳師父的著作放進去呀？",
  ui_story_5029_50290028_132_dialog_content = "才不會呢，要放也要放自己的嘛。",
  ui_story_5029_50290028_133_dialog_content = "畫像裡的人......好像有點眼熟？",
  ui_story_5029_50290028_134_dialog_content = "PlayerName，事情已經告一段落，就不要再多想了。",
  ui_story_5029_50290028_135_dialog_content = "我相信艾維斯一定會妥善處理這件事的。",
  ui_story_5029_50290028_136_dialog_content = "另外……",
  ui_story_5029_50290028_137_dialog_content = "我聽聞附近的山頂有一處觀景台，雖然荒廢已久但是視野極好。",
  ui_story_5029_50290028_138_dialog_content = "要不要一同前去欣賞美景？",
  ui_story_5029_50290028_139_dialog_content = "哎呀，放鬆的時候當然是要鍛鍊啦！",
  ui_story_5029_50290028_140_dialog_content = "我聽說山後面有一片草地很適合練長跑。",
  ui_story_5029_50290028_141_dialog_content = "PlayerName，走吧。今天的鍛鍊也不要落下喔～",
  ui_story_5029_50290028_142_dialog_content = "等等啊，可是我看見好多人都去那邊的美食慶典去了。",
  ui_story_5029_50290028_143_dialog_content = "聽說晚上的時候更熱鬧呢。",
  ui_story_5029_50290028_144_dialog_content = "PlayerName，不是說好要帶我和凱羅吃好吃的東西嗎？",
  ui_story_5029_50290028_145_dialog_content = "我們就去夜市嘛～",
  ui_story_5029_50290028_146_dialog_content = "去草地跑步吧！",
  ui_story_5029_50290028_147_dialog_content = "去觀景台賞景吧！",
  ui_story_5029_50290028_148_dialog_content = "這……",
  ui_story_5029_50290028_149_dialog_content = "這個……",
  ui_story_5029_50290028_150_dialog_content = "我要怎麼選......",
  ui_story_5029_50290028_151_dialog_content = "<color=#828282>叮鈴——</color>",
  ui_story_5029_50290028_152_dialog_content = "歡迎回來，我親愛的客人。",
  ui_story_5029_50290028_153_dialog_content = "您沒有讓今晚的時光白白流淌。",
  ui_story_5029_50290028_154_dialog_content = "可喜可賀，您成功地解開了夢中的謎底。",
  ui_story_5029_50290028_155_dialog_content = "為什麼要這樣驚詫地看著我，親愛的客人？",
